window.__CHRONICLE_CHUNK["cn-08"] = [
  {"id":"cn--73--m01","track":"cn","year":73,"yearApprox":false,"dim":"military","weight":3,"title":"窦固出塞取伊吾卢","summary":"明帝复图西域，窦固击呼衍王于天山，屯田伊吾。","detail":{"background":"明帝以比年丰稔、北虏（北匈奴）内乱，欲复武帝故事，断匈奴右臂，重通西域。","process":"73年（永平十六年）窦固与耿秉等分道出塞，固出酒泉塞，至天山击呼衍王，追至蒲类海，取伊吾卢地，置宜禾都尉屯田其地。","impact":"东汉对西域的用兵与屯田自此重启，伊吾、卢水成为其后经营西域的桥头与粮运基地，河西四郡与塔里木之间的驿道重行打通。","figures":["窦固","耿秉","刘庄"],"place":"伊吾卢（今新疆哈密一带）","state":"东汉","sources":["《后汉书·窦融传》","《后汉书·西域传》"],"tags":["东汉北边","屯田","西域"]},"related":["cn--73--x01"]},
  {"id":"cn--73--x01","track":"cn","year":73,"yearApprox":false,"dim":"explore","weight":3,"title":"班超三十六人定鄯善","summary":"以假司马随窦固出塞，夜纵火击匈奴使，南道复通。","detail":{"background":"王莽末西域绝役，北虏遂并力役属诸国；班超家贫，常为官佣书，久之苦，投笔叹当效傅介子、张骞立功异域。","process":"73年超以假行司马随窦固至蒲类海，捕斩呼衍王部，遂奉使入鄯善。会匈奴使者数十人继至，鄯善王广礼敬渐衰，超率官属三十六人因夜纵火击斩匈奴使及从者，王乃纳子为质，西域南道复通。","impact":"以三十余人定一国，开了东汉重设西域都护之端，亦为班氏父子三十余年经营西域之始。","figures":["班超","窦固"],"place":"鄯善（今新疆若羌一带）","state":"东汉","sources":["《后汉书·班超传》","《后汉书·西域传》"],"tags":["西域通汉","出使","丝绸之路"]},"related":["cn--73--m01"]},
  {"id":"cn--89--m01","track":"cn","year":89,"yearApprox":false,"dim":"military","weight":4,"title":"窦宪破北单于登燕然刻石","summary":"永元元年分道出塞，大破北虏于稽落山，刻石纪功。","detail":{"background":"北匈奴自南单于归汉后渐衰弱，部争与饥疫相乘，南单于求会汉兵击之，朝议遂决北出。","process":"89年（永元元年）窦宪将骑出塞，与耿秉分道，与北单于战于稽落山，大破之，单于被创遁走；汉军北出塞三千余里，遂登燕然山，使中护军班固作《封燕然山铭》，刻石纪汉德而还。","impact":"北单于远遁，漠北权力层随之更替，此后北匈奴余部西迁；《封燕然山铭》摩崖在今蒙古国杭爱山被发现，可与史文互证。","figures":["窦宪","耿秉","班固"],"place":"稽落山、燕然山（今蒙古国杭爱山一带）","state":"东汉","sources":["《后汉书·窦宪传》","《后汉书·南匈奴列传》","《封燕然山铭》摩崖（蒙古国杭爱山）"],"tags":["北匈奴","塞外用兵","刻石"]},"related":[]},
  {"id":"cn--91--p01","track":"cn","year":91,"yearApprox":false,"dim":"politics","weight":4,"title":"班超拜西域都护","summary":"龟兹、姑墨既定，超都护西域，五十余国内属。","detail":{"background":"超自73年入西域，以夷狄制夷狄，历鄯善、于窴、疏勒，不发中国一人之粮而渐定诸国。","process":"91年（永元三年）龟兹、姑墨等国归附，朝廷拜班超为西域都护，驻它乾城，以徐干为长史，塞外诸国咸纳质子、悉内属，唯焉耆尚未服。","impact":"东汉的西域统治体系至此重建：都护治所、戊己校尉与屯田点连成一线，塔里木周缘与中原之间的驿道、屯戍与贡赐关系稳定约二十年。","figures":["班超","刘肇"],"place":"它乾城（今新疆库车一带）","state":"东汉","sources":["《后汉书·班超传》","《后汉书·西域传》"],"tags":["西域都护","纳质内属","边疆建制"]},"related":["cn--73--x01"]},
  {"id":"cn--92--f01","track":"cn","year":92,"yearApprox":false,"dim":"figure","weight":2,"title":"班固下狱死汉书未竟","summary":"坐窦氏党与，系狱而卒，年六十一；诏班昭踵成之。","detail":{"background":"班固以撰《汉书》名世，为大将军窦宪护军，与谋北伐；宪贵盛而骄，朝臣多附之。","process":"92年（永元四年）窦宪诛，固免官，其奴得罪洛阳令种兢，兢承望权势逮系固，固死于狱，年六十一。所撰八表及《天文志》未竟，和帝诏其妹昭就东观藏书阁踵而成之，学者号曰曹大家。","impact":"《汉书》由是得完，成为断代史之体的范本；一位女性学者参与并完成官学意义上的史书，在正史中留下罕见的明证。","figures":["班固","班昭","刘肇"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·班固传》","《后汉书·列女传》"],"tags":["汉书","史学","文字之狱"]},"related":["cn--92--p01"]},
  {"id":"cn--92--p01","track":"cn","year":92,"yearApprox":false,"dim":"politics","weight":3,"title":"和帝与郑众谋诛窦宪","summary":"年十四亲政，闭北宫收大将军印，宪兄弟就第自杀。","detail":{"background":"窦宪以破北单于之功威名大盛，以郭崇等为侍中，潜谋不轨；和帝幼冲，窦太后临朝，帝与内外隔绝。","process":"92年（永元四年）夏，帝与中常侍郑众定议，幸北宫，诏执金吾、五校尉勒兵闭门，收捕宪党郭崇等，即收大将军印绶，遣宪与兄弟就第，寻迫令自杀，宪党诛徙殆尽。","impact":"外戚以军功专政的局面十年而终；郑众以功封侯，宦官始得以参与机密预政，东汉中后期外戚与宦官交替擅权的循环由此而始。","figures":["刘肇","郑众","窦宪"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·窦宪传》","《后汉书·宦者列传》"],"tags":["外戚","宦官","皇权亲政"]},"related":["cn--92--f01"]},
  {"id":"cn--97--x01","track":"cn","year":97,"yearApprox":false,"dim":"explore","weight":4,"title":"甘英使大秦临西海而还","summary":"班超遣使西行，历条支临大海，为汉使所及最西。","detail":{"background":"班超定西域五十余国，以大秦（罗马）与条支之远未通，欲结其绝域之好，乃遣甘英使之。","process":"97年（永元九年）甘英奉使西行，渡葱岭，历悬度、条支，临大海欲渡；安息西界船人谓英海水广大，往来者逢善风三月乃得度，若遇迟风亦有二岁者，故入海人皆赍三岁粮，英穷而还。","impact":"这是汉使西行所到最远的确切记录；安息居间转贩之利未替，汉与罗马的直接道路终未打通，而《后汉书·西域传》所载大秦地理风物即本此行传闻。","figures":["甘英","班超"],"place":"条支、大海（今两河流域至波斯湾一带）","state":"东汉","sources":["《后汉书·西域传》","《后汉书·班超传》"],"tags":["中西交通","丝绸之路","远使"]},"related":["cn--91--p01"]},
  {"id":"cn--102--f01","track":"cn","year":102,"yearApprox":false,"dim":"figure","weight":3,"title":"班超上书愿生入玉门","summary":"久客绝域三十年，年七十一征还，其年秋卒。","detail":{"background":"超自73年出塞，镇抚西域三十年，年老思归；朝廷以北虏新破、西域初定，未遑征代。","process":"102年（永元十四年）超上书言「臣不敢望到酒泉郡，但愿生入玉门关」，并遣子班勇入侍；朝廷乃征超还，八月至洛阳，拜射声校尉。超素有胸胁疾，其年秋卒，年七十一。","impact":"超卒后仅五年西域反、都护再罢，其经营的基础与代价同时显现；其子班勇后任西域长史，续其父旧图。","figures":["班超","班勇","刘肇"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·班超传》","《后汉书·西域传》"],"tags":["西域","上书求归","晚年"]},"related":["cn--91--p01", "cn--123--p01"]},
  {"id":"cn--105--s01","track":"cn","year":105,"yearApprox":false,"dim":"science","weight":5,"title":"蔡伦奏造纸天下称蔡侯纸","summary":"用树肤麻头敝布鱼网为纸，元兴元年奏上，帝善之。","detail":{"background":"自古书契多编以竹简，其用缣帛者谓之为纸；缣贵而简重，并不便于人，而天下文书日繁。","process":"105年（元兴元年）尚方令龙亭侯蔡伦造意，用树肤、麻头及敝布、鱼网以为纸，奏上之，帝善其能，自是莫不从用焉，故天下咸称蔡侯纸。","impact":"书写材料第一次得到廉价而可量产的植物纤维载体，典籍抄写与文书传播的物质条件就此改变；其法后传东亚诸国，8世纪起经阿拉伯世界西传欧洲。","figures":["蔡伦","刘肇"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·蔡伦传》"],"tags":["造纸术","书写材料","手工业"]},"related":[]},
  {"id":"cn--106--p01","track":"cn","year":106,"yearApprox":false,"dim":"politics","weight":3,"title":"邓太后临朝定策立安帝","summary":"殇帝在抱百日即位，殂后太后与邓骘迎立平原侯祜。","detail":{"background":"105年冬和帝崩于章德前殿，无嗣，皇后邓氏迎殇帝隆即位，帝始生百余日，太后临朝称制。","process":"106年（延平元年）殇帝殂，太后与兄车骑将军邓骘定策，迎立平原王刘祜（安帝），太后仍临朝，邓氏兄弟并据权要，太后崩（121年）而后已。","impact":"女主临朝与外戚辅政自此成为东汉中后期的常例：安、顺、冲、质、桓诸帝多以幼年入继，邓、阎、梁三后相继称制。","figures":["邓太后","刘隆","刘祜"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·皇后纪》","《后汉书·孝殇帝纪》"],"tags":["女主临朝","外戚","皇位继承"]},"related":["cn--92--p01"]},
  {"id":"cn--121--c01","track":"cn","year":121,"yearApprox":false,"dim":"culture","weight":4,"title":"许慎说文解字遣子奏上","summary":"十四篇九千余文，首创部首相从、说解形音义。","detail":{"background":"许慎字叔重，汝南召陵人，从贾逵受业，时人为之语曰「五经无双许叔重」；时经学家说字多任意失真，慎以为文字者经义之本。","process":"121年（建光元年）慎病，遣子冲奏上《说文解字》凡十四篇并叙，合文九千三百五十三、重一千一百六十三，立五百四十部首，分别部居，说解以六书为本。","impact":"汉字第一次被当作有系统的构形对象加以整比，部首之法为后世字书所沿，也是考释甲骨文、金文与训诂经义的基本依据。","figures":["许慎","许冲","刘祜"],"place":"汝南召陵（今河南偃城一带）","state":"东汉","sources":["《说文解字·叙》","《后汉书·许慎传》"],"tags":["文字学","说文解字","经学"]},"related":[]},
  {"id":"cn--123--p01","track":"cn","year":123,"yearApprox":false,"dim":"politics","weight":3,"title":"班勇为西域长史屯柳中","summary":"复通北道，发诸国兵击走北虏，焉耆遂定。","detail":{"background":"107年西域反、罢都护，北虏与车师共抄边郡，敦煌城门不闭；班勇以习其父子旧事，屡上议于公府。","process":"123年（延光二年）朝廷采勇议，以勇为西域长史，将兵五百人出屯柳中，抚柔鄯善、龟兹，发其兵击走北虏呼衍王；127年进击焉耆，焉耆降，天山以南诸国复内属。","impact":"都护之号虽不复常置，长史将兵屯抚之制自此确定，东汉与西域的关系得以维持至中平之乱以后。","figures":["班勇","邓太后","刘祜"],"place":"柳中（今新疆鄯善西南、吐鲁番盆地）","state":"东汉","sources":["《后汉书·班勇传》","《后汉书·西域传》"],"tags":["西域长史","再通西域","屯戍"]},"related":["cn--102--f01"]},
  {"id":"cn--132--s01","track":"cn","year":132,"yearApprox":false,"dim":"science","weight":5,"title":"张衡作候风地动仪","summary":"精铜为樽，中有都柱，陇西地震而一龙机发。","detail":{"background":"安帝以来郡国山崩地裂屡见，132年六月京师及凉州诸郡地震，陇西最甚；太史令张衡以推步之学造为器物。","process":"132年（阳嘉元年）衡造候风地动仪，以精铜铸成，员径八尺，合盖隆起，形似酒尊，中有都柱、傍行八道，施关发机；后一龙机发而京师地不觉动，学者咸怪其无征，数日驿至，果地震陇西，于是皆叹其妙。","impact":"这是世界最早的地震仪器记载；以机械效验代替灾异谴告之说，开了以器物观测地动的先例，其原理亦为后世测震之学的远源。","figures":["张衡"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·张衡传》"],"tags":["地动仪","仪器制造","天文历算"]},"related":[]},
  {"id":"cn--140--e01","track":"cn","year":140,"yearApprox":false,"dim":"economy","weight":3,"title":"郡国志所据永和五年版籍","summary":"司马彪录顺帝末郡国县邑、户口垦田，为东汉至盛之籍。","detail":{"background":"东汉版籍岁上计于司隶、太尉，顺帝时郡国省并屡有改定，司马彪据以撰志。","process":"140年（永和五年）即《续汉书·郡国志》所据计簿之年：志述司隶与诸部郡国、县邑道侯国之名数，并记户口、垦田、去洛阳里数，兼存永建以来省并郡国之迹。","impact":"这是现存东汉一代最完整的地理与户口总记录，后世复原两汉政区、人口与垦田分布皆本于此，与《汉书·地理志》并为早期政区地理的两大根本文献。","figures":["刘保","司马彪"],"place":"京师洛阳（所记及于全国郡国）","state":"东汉","sources":["《续汉书·郡国志》","《后汉书·孝顺帝纪》"],"tags":["版籍","政区地理","户口垦田"]},"related":[]},
  {"id":"cn--142--c01","track":"cn","year":142,"yearApprox":true,"dim":"culture","weight":3,"title":"张陵在蜀中造作道书","summary":"学道鹄鸣山，从受道者出五斗米，天师道由此渐盛。","detail":{"background":"黄老、神仙与方术之风至东汉大盛，符咒禳病、上章首过之术杂出，巴蜀之地巫风尤厚。","process":"顺帝时（相传汉安元年，约142年）张陵客于蜀，学道于鹄鸣山中，造作道书以教百姓，从受道者出五斗米，世号米贼；其后其子衡、其孙鲁于汉中行之，置义舍、以《道德经》教人。","impact":"道书、教团、祭酒与世袭治籍等制度要素在此形成，中国土生宗教有了第一个具规模的教团组织；太平道与黄巾亦沿此路而起。","figures":["张陵","张鲁","刘保"],"place":"蜀郡鹄鸣山（今四川大邑一带）与汉中","state":"东汉","sources":["《三国志·魏书·张鲁传》","《后汉书·刘焉传》"],"tags":["天师道","五斗米道","宗教组织"]},"related":[]},
  {"id":"cn--159--p01","track":"cn","year":159,"yearApprox":false,"dim":"politics","weight":4,"title":"桓帝与五宦者诛梁冀","summary":"皇后梁氏崩，帝谋之单超等，围第收印，冀自杀。","detail":{"background":"梁冀续父商之位为大将军，立冲、质、桓三帝，四方封事皆先关冀，一门五侯、子弟满朝，京师语曰「梁氏」之贵无与为比。","process":"159年（延熹二年）夏皇后梁氏崩，帝阴与中常侍单超、徐璜、具瑗、左悺、唐衡五人定议，勒南北军与虎贲士围冀第，收大将军印绶；冀与妻孙寿皆自杀，诸梁、孙氏在朝者悉诛徙，五同日封侯，世谓之五侯。","impact":"外戚一姓之权可一日而尽，但取代它的仍是亲近宦者；朝士清议与地方吏治更无所系，党锢之祸即起于此萧墙之内。","figures":["刘志","梁冀","单超"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·梁统传》","《后汉书·宦者列传》"],"tags":["外戚","宦官五侯","宫廷政变"]},"related":["cn--92--p01"]},
  {"id":"cn--166--p01","track":"cn","year":166,"yearApprox":false,"dim":"politics","weight":3,"title":"诏捕钩党，李膺等下狱","summary":"太学清议攻忤宦者，诏下三府考捕党人二百余人。","detail":{"background":"桓帝以来宦者子弟宾客遍居州郡，太学诸生三万余人（《后汉书·儒林传》记载之数）相与讥议朝政，以李膺、陈蕃为宗，更相题表，有三君、八俊、八及之名。","process":"166年（延熹九年）李膺收杀托庇宦者之门，其徒因之上书诬告膺等「共为部党、诽讪朝廷」，于是诏三府钩考，膺、杜密等二百余人下狱；太尉陈蕃上疏固争，帝不从，明年大赦而党人皆终身禁锢。","impact":"清议第一次被明文写成「党」的罪名，乡里月旦之名自此成为朝廷忌惮的对象，东汉君臣与士人之间的信任由是破裂。","figures":["刘志","李膺","陈蕃"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·党锢列传》","《后汉书·李膺传》"],"tags":["党锢之祸","清议","太学"]},"related":["cn--159--p01"]},
  {"id":"cn--168--p01","track":"cn","year":168,"yearApprox":false,"dim":"politics","weight":3,"title":"窦武陈蕃谋诛宦官不克","summary":"建宁元年九月事泄，矫诏勒兵，武、蕃皆遇害。","detail":{"background":"桓帝崩，灵帝以宗室入继，窦太后临朝，父武为大将军、陈蕃为太傅；二人素重名士，谋尽诛诸常侍，引尚书尹勋等典领禁省。","process":"168年（建宁元年）九月武等以诛曹节、王甫之议白太后，太后未许，事遂泄；曹节等矫诏取武符节，令张奂勒兵与武战于阙下，武兵多散归，武自杀，陈蕃下狱死，窦、陈宗亲徙九真、日南，门生故吏死者多人。","impact":"士人与外戚联合清除近习的这一次尝试失败之后，朝中不复有能与宦官相抗的辅政格局；汉室之亡，当时识者已见其端。","figures":["窦武","陈蕃","曹节","刘宏"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·窦武传》","《后汉书·陈蕃传》"],"tags":["党锢之祸","外戚","宦官"]},"related":["cn--166--p01", "cn--169--p01"]},
  {"id":"cn--169--p01","track":"cn","year":169,"yearApprox":false,"dim":"politics","weight":4,"title":"大捕钩党，党人死徙废禁","summary":"建宁二年诏州郡刊捕党人，名籍班于朝堂学官。","detail":{"background":"168年窦武败后，诸常侍以清议之士终为己患，因山阳张俭等更相部署之名，奏请穷治其党。","process":"169年（建宁二年）十月诏州郡大捕钩党，连治不已，李膺、杜密等百余人并死，其门生故吏、父子兄弟在位者皆免官禁锢，转相缘染，死徙废禁者六七百人（《后汉书·党锢列传》记载之数）；又刊章写下党人姓名，班于天下郡国学官及朝堂。","impact":"士人的家学、乡评与姻娅网络并未因此消亡，反以名士谱系传世，成为此后州郡大姓与魏晋门阀的政治资本。","figures":["刘志","李膺","杜密","曹节"],"place":"洛阳及诸州郡","state":"东汉","sources":["《后汉书·党锢列传》","《资治通鉴》"],"tags":["党锢之祸","名士","禁锢"]},"related":["cn--166--p01", "cn--168--p01"]},
  {"id":"cn--175--c01","track":"cn","year":175,"yearApprox":false,"dim":"culture","weight":4,"title":"熹平石经始刻于太学","summary":"蔡邕奏定五经文字，书丹镌碑，立于洛阳太学门外。","detail":{"background":"经书转写既久，文字多讹，博士家各以意改字、章句分歧；灵帝熹平四年蔡邕与堂溪典、杨赐、张驯、单飏、蔡质等奏求正定《易》《书》《诗》《礼》《春秋》诸经文字。","process":"175年诏可其奏，邕自书丹于碑，使工镌刻，立于洛阳太学门外；成之后诸儒晚学咸取正焉，观视及摹写者车乘日千余辆，填塞街陌。其残石后世屡出于洛阳、西安一带，字作隶书，世称熹平石经。","impact":"朝廷第一次以刊石的方式统一儒家经典文本，开后世石经之制；以校定的标准本对抗章句异说，是太学教育史与经学史上的一个转折。","figures":["蔡邕","刘宏","杨赐"],"place":"洛阳太学（今河南洛阳东）","state":"东汉","sources":["《后汉书·蔡邕传》","《水经注·谷水》"],"tags":["石经","经典校定","太学"]},"related":["cn--59--c01"]},
  {"id":"cn--178--i01","track":"cn","year":178,"yearApprox":false,"dim":"institution","weight":3,"title":"置鸿都门学以文辞取士","summary":"灵帝好辞赋尺牍，待制鸿都门下，州郡更荐之。","detail":{"background":"灵帝好辞赋、书画与尺牍鸟篆之技，工之者多被引擢；时太学以经学课试取士，博士弟子岁有甲乙之科。","process":"约178年（光和元年）置鸿都门学，召能为文赋、工书奏者待制鸿都门下，其后州郡更相荐举，其人或出刺史、太守、令、长，或受封爵；蔡邕、杨赐等上封事切谏，以为文辞小技不足以当经术之大。","impact":"选官第一次在经学之外另开文艺一途，虽为时论所讥，却是后世文艺待诏、词臣之职与科举试诗赋诸制的远源。","figures":["刘宏","蔡邕","杨赐"],"place":"洛阳鸿都门（今河南洛阳东）","state":"东汉","sources":["《后汉书·蔡邕传》","《后汉书·阳球传》"],"tags":["选官","鸿都门学","文艺"]},"related":["cn--175--c01"]},
  {"id":"cn--184--m01","track":"cn","year":184,"yearApprox":false,"dim":"military","weight":5,"title":"黄巾起事，八州并发","summary":"太平道张角约以甲子同起，皆着黄巾，旬月响应。","detail":{"background":"张角以符水咒说疗病，遣弟子分往青、徐、幽、冀、荆、扬、兗、豫八州，十余年间徒众数十万（记载之数），置三十六方，大方万余人、小方六七百，各立渠帅。","process":"184年（中平元年，岁在甲子）角以「苍天已死，黄天当立，岁在甲子，天下大吉」约为内应；因弟子告变，马元义诛于洛阳，角乃晨夜举兵，皆着黄巾，郡县多应之，杀长吏、燔官府，旬月之间天下并起，京师震动。","impact":"汉家的地方军政体系在数周内失灵，朝廷不得不募兵、赦党人、卖爵以应之；州郡由此得专兵柄，统一帝国转入长期分裂。","figures":["张角","皇甫嵩","刘宏"],"place":"冀、豫、荆诸州（起于巨鹿，波及八州）","state":"东汉","sources":["《后汉书·皇甫嵩传》","《后汉书·孝灵帝纪》"],"tags":["黄巾","太平道","民变"]},"related":["cn--142--c01", "cn--184--p01"]},
  {"id":"cn--184--p01","track":"cn","year":184,"yearApprox":false,"dim":"politics","weight":3,"title":"以寇起诏解党锢","summary":"黄巾发后大赦，除党人之禁，还诸徙者。","detail":{"background":"党锢近二十年，士人废弃于家，州郡以苛察相高；黄巾一起，朝野忧惧，恐变起而士人不为己用。","process":"184年（中平元年）春诏大赦天下，解除党锢之禁，还诸徙者，唯张角不赦；于是皇甫嵩、朱儁、卢植分将四出，征发天下兵，又因修治宫室、军费不给，令关内侯以下至虎贲羽林缇骑营士以钱入左署为差，州郡各募义从。","impact":"清议之士重被纳入仕途与军役，但朝廷以名器与财货应急，卖爵既开、选举益乱，中央号令自此难行于州郡。","figures":["刘宏","皇甫嵩","朱儁"],"place":"洛阳（诏下郡国）","state":"东汉","sources":["《后汉书·孝灵帝纪》","《后汉书·党锢列传》"],"tags":["党锢","大赦","兵制"]},"related":["cn--169--p01", "cn--184--m01"]},
  {"id":"cn--188--m01","track":"cn","year":188,"yearApprox":false,"dim":"military","weight":3,"title":"置西园八校尉以蹇硕为上军","summary":"灵帝分何进之权，禁兵八校皆统于小黄门。","detail":{"background":"黄巾起兵以来郡县兵乱不已，大将军何进辅政录尚书事，朝廷思分其权；灵帝以宦者晓习兵马，欲令内统禁省。","process":"188年（中平五年）十二月初置西园八校尉，以小黄门蹇硕为上军校尉统之，袁绍为中军校尉、曹操为典军校尉，又有鲍鸿、赵融、冯芳、夏牟、淳于琼等分任左右，何进亦以大将军隶焉，所统兵会于西园平乐观。","impact":"禁兵之权落入宦者之手，何进与蹇硕各树朋党，中央军权一分为二；袁、曹二人由禁近起家，为其后逐鹿之局伏一线。","figures":["蹇硕","何进","袁绍","曹操","刘宏"],"place":"洛阳西园（今河南洛阳东）","state":"东汉","sources":["《后汉书·孝灵帝纪》","《后汉书·何进传》"],"tags":["禁军","军制","宦官"]},"related":["cn--188--i01"]},
  {"id":"cn--188--i01","track":"cn","year":188,"yearApprox":false,"dim":"institution","weight":3,"title":"改刺史为州牧分遣重臣","summary":"刘焉议选清名重臣临州，刺史遂有将军之任。","detail":{"background":"自黄巾起兵，郡国失守、刺史多非其才，以货赂拜者相继；朝廷欲以重臣镇安方夏。","process":"188年（中平五年）太常刘焉以为刺史、太守货赂为官、割剥百姓，故远人不服，议选清名重臣以为州牧。于是以焉为益州牧、宗正刘虞为幽州牧、太仆黄琬为豫州牧，皆秩中二千石、持节临州，其后诸州多仿而置牧。","impact":"监察之州一变而有军、政、财赋之实，地方分权之势不可复收；董卓、袁绍、曹操皆以州牧、将军之任割据一方，三国分立之局已伏于此。","figures":["刘焉","刘虞","黄琬","刘宏"],"place":"益、幽、豫诸州（定议于洛阳）","state":"东汉","sources":["《后汉书·刘焉传》","《资治通鉴》"],"tags":["州牧制","地方行政","分裂"]},"related":["cn--184--p01", "cn--188--m01"]},
  {"id":"cn--189--p01","track":"cn","year":189,"yearApprox":false,"dim":"politics","weight":4,"title":"董卓入洛阳废少帝立献帝","summary":"宦者杀何进，董卓迎帝北芒，九月更易皇统。","detail":{"background":"189年四月灵帝崩，太子刘辩即位，何太后临朝；大将军何进谋尽诛诸常侍，白太后召董卓等外兵入京为援。","process":"八月张让等杀何进于阙下，袁绍等尽诛宦者，少帝与陈留王夜出北宫、行到北芒，董卓将兵迎之还宫。九月卓废少帝为弘农王，立陈留王刘协（献帝），改元昭宁、永汉，何太后寻被酖，卓自为太尉，公卿以下皆出其门。","impact":"皇统在一月之间更易，中央军权尽归边将；此后州郡不复禀命于洛阳，东汉之实亡止于此，而其名号又延了三十年。","figures":["董卓","刘协","何进","刘辩"],"place":"洛阳（今河南洛阳东）","state":"东汉","sources":["《后汉书·孝灵帝纪》","《后汉书·何进传》","《后汉书·董卓传》"],"tags":["废立","董卓","皇统"]},"related":["cn--188--i01", "cn--190--m01"]},
  {"id":"cn--190--m01","track":"cn","year":190,"yearApprox":false,"dim":"military","weight":3,"title":"关东州郡起兵讨董卓","summary":"推袁绍为盟主，卓胁帝西迁，联军内竞无成。","detail":{"background":"董卓以废立之威震慑朝廷，又征用名士以自重；关东州郡闻其擅行废立，多怀不平。","process":"190年（初平元年）正月关东州郡起兵讨卓，推渤海太守袁绍为盟主，曹操、袁术、孙坚等各举兵而进；三月董卓胁天子西迁长安，烧洛阳宫庙、官府与民居，二百里内为之丘墟，诸军虽西驻酸枣、北保河内而莫之能先。","impact":"讨董卓之盟未成而割据之势已定：州郡各擅其兵、各私其赋，中央号令不复通行，天下之势自此散漫而不可复收。","figures":["袁绍","曹操","孙坚","董卓"],"place":"酸枣、河内与洛阳至长安道","state":"东汉","sources":["《后汉书·袁绍传》","《三国志·魏书·武帝纪》","《资治通鉴》"],"tags":["联军","迁都","割据"]},"related":["cn--189--p01"]},
  {"id":"cn--192--p01","track":"cn","year":192,"yearApprox":false,"dim":"politics","weight":3,"title":"王允吕布杀董卓","summary":"伏兵北掖门刺卓，李傕郭汜旋用贾诩计袭长安。","detail":{"background":"董卓在长安，政事一出于己，僭拟无上；其腹心吕布以私忿怨卓，司徒王允密与图之。","process":"192年（初平三年）四月，王允与吕布定谋，乘卓入朝伏兵北掖门内刺杀之，又夷其族；朝廷大赦而独不赦凉州诸军。寻而李傕、郭汜用贾诩之谋，率众袭长安，城陷，王允及家族遇害，卓尸以王礼改葬。","impact":"一次成功的宫廷刺杀并未收回关中：凉州军入而长安再乱，天子与朝廷自此成为诸将之手，关东州郡的割据更无从整齐。","figures":["王允","吕布","董卓","李傕","贾诩"],"place":"长安（今陕西西安西北）","state":"东汉","sources":["《后汉书·董卓传》","《后汉书·王允传》","《三国志·魏书·吕布传》"],"tags":["政变","凉州军","关中之乱"]},"related":["cn--190--m01"]},
  {"id":"cn--196--p01","track":"cn","year":196,"yearApprox":false,"dim":"politics","weight":4,"title":"曹操迎天子迁都于许","summary":"李傕郭汜相攻，天子东出，操奉驾居许。","detail":{"background":"195年李傕、郭汜相攻击于长安，天子东出，数年间居处无常，州郡莫之能救；曹操时屯兵于许，毛玠进奉天子以令不臣、修耕植以畜军资之策。","process":"196年（建安元年）七月曹操至洛阳，卫京都，十月奉天子东迁于许，于是复公卿百官之职，操领司隶校尉、录尚书事，自是朝廷号令皆以操名义而行。","impact":"天子成为号令的名分而实权归于曹氏：操据此先后并吕布、袁术、张绣、袁绍，河北、淮南相继入其手，建安之政自此立。","figures":["曹操","刘协","毛玠"],"place":"许（今河南许昌东）","state":"东汉","sources":["《三国志·魏书·武帝纪》","《三国志·魏书·毛玠传》","《后汉书·孝献帝纪》"],"tags":["迎驾","中枢","曹操"]},"related":["cn--196--i01", "cn--200--m01"]},
  {"id":"cn--196--i01","track":"cn","year":196,"yearApprox":false,"dim":"institution","weight":4,"title":"许下屯田与田农官之制","summary":"募民田许下得谷百万斛，州郡例置田官。","detail":{"background":"自黄巾以来四十年，民人流亡、土地荒废，诸军乏粮而无终岁之计，饥则寇略、饱则弃余，瓦解流离者不可胜数。","process":"196年（建安元年）曹操用枣祗、韩浩之议，募民屯田许下，得谷百万斛（《三国志》注引《魏书》记载之数）；于是州郡例置田官，典农中郎将、典农校尉、都尉之属遍于司隶、豫、兗，民以兵农合一之法附于土地。","impact":"屯田把流民、荒地、军需直接挂钩，成为曹魏一代财政与军食的主干，也促成北方人口与耕作区的重新集中；其法为西晋占田、北魏均田诸制之先声。","figures":["曹操","枣祗","韩浩","任峻"],"place":"许下及司隶、豫、兗诸郡","state":"东汉","sources":["《三国志·魏书·武帝纪》裴松之注引《魏书》","《三国志·魏书·任峻传》"],"tags":["屯田","财政","流民安置"]},"related":["cn--196--p01"]},
  {"id":"cn--200--m01","track":"cn","year":200,"yearApprox":false,"dim":"military","weight":4,"title":"官渡之战曹操袭乌巢","summary":"绍连营逼官渡，操夜烧乌巢辎重，河北之众遂溃。","detail":{"background":"袁绍并冀、青、幽、并四州，简精兵南向；曹操东破刘备后还军官渡，诸将皆畏绍，荀彧料其为人多疑而少决。","process":"200年（建安五年）八月袁绍进军官渡、连营稍前，操军粮亦且尽，乃用降人许攸之说，夜率步骑袭乌巢，烧其辎重，斩守将淳于琼；绍军内惊扰，张郃、高览来降，众遂大溃，绍父子北渡。","impact":"官渡一战决定了此后十年北方的归属：袁氏不复能南出，曹操得其户口、田赋与骑兵之源；以少击众、先击辎重的战法亦为后世兵家所征引。","figures":["曹操","袁绍","许攸","淳于琼","荀彧"],"place":"官渡（今河南中牟东北）","state":"东汉","sources":["《三国志·魏书·武帝纪》","《后汉书·袁绍传》","《资治通鉴》"],"tags":["官渡之战","辎重","以少击众"]},"related":["cn--196--p01", "cn--196--i01"]},
  {"id":"cn--200--s01","track":"cn","year":200,"yearApprox":true,"dim":"science","weight":2,"title":"华佗以麻沸散行开腹之术","summary":"针药所不及者，先以酒服麻沸散而刳腹去病。","detail":{"background":"汉代方技之学盛行于郡国，医者以汤液、针灸为本，能破腹去疾者极稀。","process":"约200年前后，沛国谯人华佗以方术行医，史称其精方药、针灸不过数处；若疾发结于内、针药所不能及，乃令先以酒服麻沸散，既醉无所觉，因刳破腹背以去病所，傅药缝腹，膏之得愈；佗后为曹操所杀，所著书亦不传。","impact":"麻醉与开腹的设想以华佗为名载入正史，其术不久失传，但外科与麻醉的问题自此进入中国医学史；佗又以五禽戏示人，谓人体欲得劳动、不当极尔。","figures":["华佗","曹操"],"place":"沛国谯县（今安徽亳州）","state":"东汉","sources":["《三国志·魏书·方技传》","《后汉书·方术列传》"],"tags":["医学","麻醉","方技"]},"related":[]},
  {"id":"cn--204--p01","track":"cn","year":204,"yearApprox":false,"dim":"politics","weight":3,"title":"曹操围邺自领冀州牧","summary":"引漳水灌邺城，审配固守，配甥开门内曹军。","detail":{"background":"202年袁绍病死，二子谭、尚各据一州相攻，袁尚围谭于平原；曹操纳辛毗之说，北定规取河北。","process":"204年（建安九年）曹操围邺，遏漳水以灌城，袁尚自平原来救、屡破之；审配坚守数月，其甥开北门内曹军，城遂溃。操入邺，自领冀州牧，出袁氏府库以赐军士，亲祠袁绍墓。","impact":"邺城之得使曹操有了一处可与许并立的根据，其后魏公建国、丞相府移镇皆在河北；袁氏余众北走乌桓，至207年乃尽平。","figures":["曹操","袁尚","审配","辛毗"],"place":"邺城（今河北临漳西南）","state":"东汉","sources":["《三国志·魏书·武帝纪》","《后汉书·袁绍传》"],"tags":["邺城","冀州","袁氏之亡"]},"related":["cn--200--m01"]},
  {"id":"cn--205--s01","track":"cn","year":205,"yearApprox":true,"dim":"science","weight":4,"title":"张机撰伤寒杂病论","summary":"以六经为纲辨脉证、随证立方，为临证之祖。","detail":{"background":"建安以来大疫数作，家家得之；南阳张机字仲景，以宗族凋零，感往昔之沦丧，乃勤求古训、博采方论。","process":"约205年前后（建安纪年以来）撰《伤寒杂病论》合十六卷，以六经为纲、辨脉证而随证立方，自序谓撰用《素问》《九卷》《八十一难》《阴阳大论》，并平脉辨证，以见病能。","impact":"此书把外感病的证候纳入可辨、可传、可复按的框架，方证相应的体例成为后世临床医学的正统；其书经王叔和编次，后世分为《伤寒论》与《金匮要略》两支行世。","figures":["张机","王叔和"],"place":"南阳郡（今河南南阳）与长沙","state":"东汉","sources":["《伤寒杂病论·序》","《隋书·经籍志》"],"tags":["医学","伤寒","方书"]},"related":["cn--217--d01"]},
  {"id":"cn--208--a01","track":"cn","year":208,"yearApprox":true,"dim":"art","weight":2,"title":"蔡琰归汉作悲愤诗","summary":"曹操以金璧赎之南匈奴，追往事成五言一篇。","detail":{"background":"蔡邕之女琰字昭姬，先适卫氏，董卓之乱后没于胡骑，居南匈奴中十余年，有二子；邕所撰碑颂与典籍散亡殆尽。","process":"约208年（建安中）曹操素与邕善，痛其无嗣，乃遣使者以金璧赎之，重嫁于屯田都尉董祀；琰追痛一二之惨，作五言《悲愤诗》一首，自述丧乱、俘掠、去子之悲，又传其述《胡笳十八拍》。","impact":"以一身之遭遇写一代之乱离，一百二十句、五百余言，是汉末叙事诗中最长的一篇，也是关于汉匈之间人口掠卖与赎归的第一手记录。","figures":["蔡琰","曹操","董祀","蔡邕"],"place":"邺城（今河北临漳西南）","state":"东汉","sources":["《后汉书·列女传》","《悲愤诗》"],"tags":["叙事诗","乱离","汉匈之间"]},"related":["cn--92--f01"]},
  {"id":"cn--208--m01","track":"cn","year":208,"yearApprox":false,"dim":"military","weight":4,"title":"赤壁之战周瑜破曹","summary":"孙权与刘备并力，火攻烧其舟船，曹军北败。","detail":{"background":"208年七月曹操南征刘表，会表卒、刘琮以州降，操遂济江东下，众称八十万，欲会猎于吴；孙权在江东，将相之议纷纷。","process":"208年（建安十三年）冬，孙权以周瑜为督，将三万人进住夏口、南郡，与刘备俱逆曹公，遇于赤壁；曹军众已有疾疫，初一交战不利，引次江北，瑜用黄盖诈降、蒙冲斗舰载燥荻枯柴灌油以炬火之，烧其舟船，延及岸上营落，曹军大败，引军北还。","impact":"南下的军事压力一时解除，荆州为曹、孙、刘三家分有，长江自此成为南北之间的军事界线；孙氏江东基业得以巩固，刘备亦借势取江南诸郡。","figures":["周瑜","曹操","刘备","孙权","黄盖"],"place":"赤壁（今湖北蒲圻至嘉鱼一带长江）","state":"东汉","sources":["《三国志·吴书·周瑜传》","《三国志·魏书·武帝纪》","《资治通鉴》"],"tags":["赤壁之战","水战","火攻"]},"related":["cn--204--p01", "cn--219--m02"]},
  {"id":"cn--213--p01","track":"cn","year":213,"yearApprox":false,"dim":"politics","weight":3,"title":"封魏公建国于邺","summary":"复九州之制，备九锡之礼，魏国置百官立社稷。","detail":{"background":"曹操自平河北、取荆州后位至丞相、封武平侯，子丕、彰、植分据要州；朝廷名器于操已无所复加。","process":"213年（建安十八年）五月准古九州之制、并省诸郡入冀州，封曹操为魏公，加九锡，领魏郡等十郡，建国于邺，置将军、侍中、尚书已下，立宗庙、社稷；二十一年进爵魏王，出警入跸、乘金银车。","impact":"一个与汉朝并存、自有社稷宗庙与百官的魏国在河北成形，禅代的程序自此有了制度模型；220年曹丕受禅即沿魏国之旧而完成。","figures":["曹操","刘协"],"place":"邺城（今河北临漳西南）","state":"东汉","sources":["《三国志·魏书·武帝纪》","《后汉书·孝献帝纪》","《资治通鉴》"],"tags":["魏国","九锡","禅代"]},"related":["cn--220--p01"]},
  {"id":"cn--217--d01","track":"cn","year":217,"yearApprox":false,"dim":"disaster","weight":3,"title":"建安二十二年大疫","summary":"春大疫，邺下文人徐陈应刘一时俱逝。","detail":{"background":"建安以来疫数作，中原连年兵革、水旱相仍，民人既饥且疫，家家得之。","process":"217年（建安二十二年）春大疫，书于帝纪；曹丕《与吴质书》云徐干、陈琳、应玚、刘桢一时俱逝，几案尚存而此人已没；曹植《说疫气》言閭里以为常、亲旧殂丧，虽良平不能救，医家张机之序亦以宗族之夭为言。","impact":"一场疫病使邺下文学集团的核心人物同时凋落，建安风力由繁盛转入余响；它也推动了医家对外感热病证候与方治的系统整理。","figures":["曹丕","曹植","徐干","刘桢","应玚"],"place":"邺城、洛阳与中原诸郡","state":"东汉","sources":["《后汉书·孝献帝纪》","曹丕《与吴质书》","曹植《说疫气》"],"tags":["疫病","建安文学","人口"]},"related":[]},
  {"id":"cn--219--m01","track":"cn","year":219,"yearApprox":false,"dim":"military","weight":3,"title":"关羽围襄阳水淹七军","summary":"霖雨汉水溢，于禁所督七军皆没，威震华夏。","detail":{"background":"刘备取益州、汉中之后，关羽住襄阳，与曹仁诸军对垒数年；孙权为子求昏不许，两家之隙渐深。","process":"219年（建安二十四年）七月关羽率众北围襄阳、攻樊城，会霖雨、汉水溢，所督七军皆没，于禁降，庞德不降而死；羽乘船围之，樊城平地水数尺、几至不守，梁、郏、陆浑群盗遥受羽印号，威震华夏。","impact":"曹操一度议徙许都以避其锐，关东为之骚动；然关羽得襄阳而不能守江陵，覆亡即在数月之后，蜀汉东向之策由此转折。","figures":["关羽","于禁","曹仁","庞德"],"place":"襄阳、樊城（今湖北襄阳一带）","state":"汉","sources":["《三国志·蜀书·关羽传》","《三国志·魏书·满宠传》","《资治通鉴》"],"tags":["襄樊之战","水攻","关羽"]},"related":["cn--219--m02"]},

  {"id":"cn--219--m02","track":"cn","year":219,"yearApprox":false,"dim":"military","weight":4,"title":"吕蒙白衣渡江取荆州","summary":"糜芳、傅士仁举江陵降，关羽走麦城见获。","detail":{"background":"孙权久欲有荆州，吕蒙代鲁肃驻陆口，阳称还都治病、以年少无名的陆逊代之，以骄关羽之心；南郡守将与江上屯候素不和。","process":"219年十二月，蒙乘关羽北围樊城，使白衣摇橹、作商贾之服，昼夜兼行，袭其屯候皆不能御；南郡太守糜芳、将军傅士仁以供军不赡惧诛，举江陵、公安降。关羽自襄阳还，军心思归、无复斗志，西保麦城，至临沮为潘璋司马马忠所获，父子俱死。","impact":"孙权尽有长江之险，关羽一军覆而蜀汉遂失东出之路；孙刘联盟自此破裂，221年至222年的夷陵之战即起于此。","figures":["吕蒙","关羽","陆逊","孙权","糜芳"],"place":"江陵、麦城、临沮（今湖北江陵至当阳一带）","state":"吴","sources":["《三国志·吴书·吕蒙传》","《三国志·蜀书·关羽传》","《资治通鉴》"],"tags":["荆州之失","偷袭","孙刘联盟"]},"related":["cn--208--m01", "cn--222--m01"]},

  {"id":"cn--220--p01","track":"cn","year":220,"yearApprox":false,"dim":"politics","weight":5,"title":"曹丕受禅，汉亡魏立","summary":"十月行禅礼于繁阳，国号魏，改元黄初。","detail":{"background":"220年正月曹操崩于洛阳，曹丕嗣位为魏王、丞相、冀州牧；八月葬操于高陵，汉魏禅代之议遂行。","process":"220年（延康元年、黄初元年）十月，汉帝禅位于魏，魏王升坛受玺绶于繁阳，即皇帝位，国号魏，改元黄初，追尊祖、父为帝，封汉帝为山阳公、食邑万户，行汉正朔、以天子礼郊祀。","impact":"立国四百余年的汉在名分上结束；以禅让之礼完成的王朝更替自此成为后世迭代的定式，魏、蜀、吴三国并立之局于是一名分确定。","figures":["曹丕","刘协","华歆","贾诩"],"place":"繁阳与洛阳（今河南临颍繁城镇一带）","state":"魏","sources":["《三国志·魏书·文帝纪》","《后汉书·孝献帝纪》","《资治通鉴》"],"tags":["禅让","曹魏","汉亡"]},"related":["cn--213--p01", "cn--220--i01"]},

  {"id":"cn--220--i01","track":"cn","year":220,"yearApprox":false,"dim":"institution","weight":4,"title":"九品官人法立","summary":"陈群以选用不尽人才，立州郡中正评人为九品。","detail":{"background":"后汉选官本于察廉与乡里之议，桓、灵以来权移近习、选举失叙，郡国士人沉滞者多；魏国初建，吏部之任益重。","process":"220年（延康元年）吏部尚书陈群以天朝选用不尽人才，乃立九品官人之法：州、郡各置中正，察其人之行能、别为九品以上下之，尚书吏部凭品状补授，而犹参以乡评。","impact":"选官之权自乡里清议移于国家所置的中正，品状成为官阶之凭；西晋以下所谓上品无寒门、下品无势族的门阀格局（《宋书·恩幸传序》所概括）即由此起。","figures":["陈群","曹丕"],"place":"洛阳（法行于州郡）","state":"魏","sources":["《三国志·魏书·陈群传》","《通典·选举典》","《宋书·恩幸传序》"],"tags":["九品中正","选官","门阀"]},"related":["cn--178--i01", "cn--220--p01"]},

  {"id":"cn--221--p01","track":"cn","year":221,"yearApprox":false,"dim":"politics","weight":3,"title":"刘备称帝于成都国号汉","summary":"以继汉为义，改元章武，立太子禅。","detail":{"background":"曹丕代汉之后，蜀中传言献帝已遇害，群臣上图纬、符命请备称汉者甚众；刘备在益州，其势不能不复汉之号。","process":"221年（章武元年）四月，刘备即皇帝位于成都武担之南，国号汉，改元章武，立皇后吴氏、子禅为皇太子，以诸葛亮为丞相、录尚书事；其年七月遂东征孙权。","impact":"以汉之继续自称，使蜀汉的国策不能不以北伐为名义；诸葛亮一出祁山、再出陈仓之路向，皆在此名分与国力之中定。","figures":["刘备","诸葛亮","刘禅"],"place":"成都武担之南（今四川成都）","state":"汉（蜀）","sources":["《三国志·蜀书·先主传》","《资治通鉴》"],"tags":["蜀汉","名分","北伐"]},"related":["cn--220--p01", "cn--223--f01"]},
  {"id":"cn--222--m01","track":"cn","year":222,"yearApprox":false,"dim":"military","weight":3,"title":"陆逊破刘备于夷陵","summary":"缘山截谷连营，逊持重半年，因风纵火破四十余营。","detail":{"background":"孙权既有荆州，刘备衔之，221年秋率众东下；吴诸将请逆战，孙权以陆逊为大都督、假节督诸军拒之。","process":"222年（章武二年、黄武元年）二月先主自巫峡连营至夷陵、猇亭，缘山截谷、分兵守险；陆逊据险不与战，相持半岁，六月令军士各持一茅，因风纵火以塞其外围，遂破四十余营，舟船器械、水军资略尽，先主升马鞍山夜遁，止入白帝城。","impact":"蜀汉东征之军与舟船一战而尽，荆州的归属再不可改；吴蜀之界定于巫峡，自此刘备之力只能北向，此败遂为三国南方之长局。","figures":["刘备","陆逊","孙权","黄权"],"place":"夷陵、猇亭（今湖北宜昌至猇亭一带）","state":"吴、汉","sources":["《三国志·吴书·陆逊传》","《三国志·蜀书·先主传》","《资治通鉴》"],"tags":["夷陵之战","火攻","三国疆界"]},"related":["cn--219--m02", "cn--223--f01"]},
  {"id":"cn--223--f01","track":"cn","year":223,"yearApprox":false,"dim":"figure","weight":4,"title":"先主病笃托孤于诸葛亮","summary":"遗诏辅政于永安宫，君臣以社稷为言。","detail":{"background":"夷陵败后先主收集散兵，西驻永安，不复还成都；其年秋冬遂不豫，乃召诸葛亮。","process":"223年（章武三年）四月先主病笃于永安宫，诸葛亮自成都至，受遗诏辅政；以李严为中护军、留护永安，与亮并受顾命。先主又敕后主事丞相如父，诸葛亮于是遣使重修吴好。","impact":"蜀汉的军政自此出于丞相府，诸葛亮得以专意内治、东和孙权、南平诸郡；其吏职、法治与军需规模皆成于一人之手，开府治事之格由此而立。","figures":["刘备","诸葛亮","李严"],"place":"永安宫（今重庆奉节东）","state":"汉（蜀）","sources":["《三国志·蜀书·诸葛亮传》","《三国志·蜀书·先主传》"],"tags":["托孤","丞相府","蜀汉政制"]},"related":["cn--221--p01", "cn--225--m01"]},
  {"id":"cn--225--m01","track":"cn","year":225,"yearApprox":false,"dim":"military","weight":3,"title":"诸葛亮平南中","summary":"三道并进，渡泸深入，收用其渠帅而不留外人。","detail":{"background":"先主崩后南中遂乱：益州郡大姓雍闿执太守以应吴，牂柯太守朱褒、越嶲夷帅高定元各与之相应。","process":"225年（建兴三年）春诸葛亮率军南征，分道并进：亮出越嶲破高定元，马忠讨朱褒于牂柯，李恢深入建宁；五月渡泸水，至味、昆明之地，雍闿为其众所杀，孟获七纵七擒之说见于后人所传。","impact":"不设外人、不运军粮而取其赋役，南中金银、丹漆、耕织、毡罽之利遂为蜀汉军资之所赖；以攻心为上的经边之说亦因《汉晋春秋》所载孟获之事而传世。","figures":["诸葛亮","李恢","雍闿","孟获"],"place":"越嶲、建宁、牂柯（今四川西南至云南、贵州）","state":"汉（蜀）","sources":["《三国志·蜀书·诸葛亮传》","《华阳国志·南中志》","《汉晋春秋》"],"tags":["南征","南中","经边"]},"related":["cn--223--f01", "cn--227--c01"]},
  {"id":"cn--227--c01","track":"cn","year":227,"yearApprox":false,"dim":"culture","weight":3,"title":"诸葛亮上出师表北驻汉中","summary":"临发致书后主，以亲贤远佞为治国之要。","detail":{"background":"南中既定、军资略备，诸葛亮乃率军北驻汉中，将图北伐；行前上疏于后主。","process":"227年（建兴五年）诸葛亮上《出师表》，言侍卫之臣不懈于内、忠志之士忘身于外者，盖追先帝之殊遇；因以宫中府中宜为一体、亲贤臣远小人为先汉兴隆后汉倾颓之鉴，自言受命以来夙夜忧叹，故五月渡泸、深入不毛，今南方已定、兵甲已足，当奖率三军北定中原。","impact":"此表以家事与国事相起，成为后世奏疏之体的极则；亦将北伐的名义、责任与宫中人事安排明白宣示于朝野。","figures":["诸葛亮","刘禅","蒋琬","费祎"],"place":"成都与汉中（今陕西汉中）","state":"汉（蜀）","sources":["《三国志·蜀书·诸葛亮传》"],"tags":["出师表","奏疏之文","北伐"]},"related":["cn--225--m01", "cn--228--m01"]},
  {"id":"cn--228--m01","track":"cn","year":228,"yearApprox":false,"dim":"military","weight":3,"title":"首次北伐出祁山，街亭失利","summary":"三郡响应而马谡失街亭，亮拔西县千余家而还。","detail":{"background":"蜀以魏有代汉之衅，诸葛亮以为当及此北定中原；魏之陇右久无备，蜀师既出，州郡多应之。","process":"228年（建兴六年）春亮出祁山，天水、南安、安定三郡皆叛魏应亮，关中震怖；魏明帝自至长安，遣张郃拒街亭。参军马谡违亮节度、舍水上山，为郃所破，一线遂断；亮拔西县千余家还于汉中，戮马谡而自贬三等，赵云等亦不利而敛兵自固。","impact":"第一次北伐之败不在众寡，而在山道之险、粮运之难与用命之际；此后亮复出皆以祁山、散关、斜谷为进退之路，数出而不获，成为以攻为守之局。","figures":["诸葛亮","马谡","张郃","赵云"],"place":"祁山、街亭（今甘肃礼县、秦安东北一带）","state":"汉（蜀）、魏","sources":["《三国志·蜀书·诸葛亮传》","《三国志·魏书·张郃传》","《资治通鉴》"],"tags":["北伐","街亭","山地之战"]},"related":["cn--227--c01"]},
  {"id":"cn--230--x01","track":"cn","year":230,"yearApprox":false,"dim":"explore","weight":3,"title":"卫温诸葛直浮海至夷洲","summary":"将甲士万人求夷洲、亶洲，得夷洲数千人而还。","detail":{"background":"江东既平山越，舟行渐习；孙权欲致海外之民以补户口，而临海郡县素传海中有洲夷之俗。","process":"230年（黄龙二年）孙权遣将军卫温、诸葛直将甲士万人浮海求夷洲及亶洲，亶洲波远不可至；得夷洲数千人（此为记载之数）而还，士卒疫死十二三（记载之数），温、直坐无功召还诛之。吴人沈莹后为临海太守，记其土俗物产，即《临海水土异物志》。","impact":"这是大陆与台湾之间海上往来最早的明确记载；万人之役以疫终，然夷洲风俗物产自此见于中国图籍，海行的经验亦入吴人之记载。","figures":["卫温","诸葛直","孙权","沈莹"],"place":"夷洲（今台湾）与临海郡（今浙江东南沿海）","state":"吴","sources":["《三国志·吴书·吴主传》","《临海水土异物志》（辑本）"],"tags":["海上交通","夷洲","航海"]},"related":["cn--97--x01"]},
  {"id":"cn--240--c01","track":"cn","year":240,"yearApprox":true,"dim":"culture","weight":3,"title":"正始之际贵无论兴","summary":"何晏、王弼以无为本，注易老而清谈始盛。","detail":{"background":"曹爽、司马懿共辅政之际，魏室名法之严渐弛，士人舍经术而谈玄远，洛阳有一时之好。","process":"约240年前后，吏部尚书何晏与王弼、夏侯玄等以《老》《易》《论语》为文，主天地以万物为本而贵无；王弼年二十余注《老子》、《周易》，何晏见其论而叹服，正始名理之风遂行于朝士之间。","impact":"玄学把名教与自然的离合变成可论辩的义理，改变了汉代经学的问学方式；其清谈之习入晋而大盛，亦为东晋士族文化与佛理之沟通作了铺垫。","figures":["何晏","王弼","夏侯玄","曹爽"],"place":"洛阳（今河南洛阳东）","state":"魏","sources":["《三国志·魏书·王粲传》裴松之注引何劭《王弼传》","《世说新语·文学》","《晋书·王衍传》"],"tags":["玄学","正始","清谈"]},"related":["cn--249--p01", "cn--262--f01"]},
  {"id":"cn--249--p01","track":"cn","year":249,"yearApprox":false,"dim":"politics","weight":4,"title":"高平陵之变，司马懿夺魏政","summary":"洛阳一日尽归司马，曹爽寻与何晏等同夷三族。","detail":{"background":"曹爽以宗室辅政，更置尚书、移郭太后居永宁宫，兄弟并掌兵权；司马懿外见尊任而内见疏，托疾不复预人事。","process":"249年（正始十年）正月魏帝谒高平陵，爽兄弟皆从；司马懿奏永宁太后闭洛阳城门、据武库，使蒋济等往喻，许以列侯还第。司农桓范出城劝爽奉天子幸许昌以号令天下，爽自以不失作富家翁，遂解兵出降；数日爽与何晏、邓飏、丁谧等并以谋反下廷尉，皆夷三族。","impact":"曹魏宗室之强自此一尽，司马氏以辅政之名握军国之实，改朝之局已定而不必更其号；何晏等同日被戮，正始清谈之风转为晋人口中危论之戒。","figures":["司马懿","曹爽","蒋济","桓范","何晏"],"place":"洛阳（今河南洛阳东）","state":"魏","sources":["《晋书·宣帝纪》","《三国志·魏书·曹爽传》","《资治通鉴》"],"tags":["政变","司马氏","名士之祸"]},"related":["cn--240--c01"]},
  {"id":"cn--256--s01","track":"cn","year":256,"yearApprox":true,"dim":"science","weight":3,"title":"皇甫谧撰《针灸甲乙经》","summary":"合素问、针经、明堂三部，删浮辞而事类相从。","detail":{"background":"魏晋之际，《素问》《针经》《明堂孔穴针灸治要》三部并行，文有重复、事有异同，临用难以检求；安定朝那人皇甫谧（215—282）自加删整。","process":"约 256 年前后成《黄帝三部针灸甲乙经》，自序谓取三书「删其浮辞，除其重复，论其精要」，使事类相从；孔穴之名、部位、针之浅深、灸之壮数与所主之病，各以类相聚而成编。","impact":"此为现存最早专立针灸一部之书，宋臣校正医书、明以后之针灸取穴多本其编次；其以「三部」合为一书之举，使散在诸经的孔穴文字成为可按核的定编。","figures":["皇甫谧"],"place":"安定朝那（今甘肃平凉一带）","state":"魏—西晋","sources":["《针灸甲乙经·序》","《晋书·皇甫谧传》"],"tags":["针灸","甲乙经","皇甫谧"]},"related":["cn--b100--s01","cn--652--s01"]},
  {"id":"cn--260--x01","track":"cn","year":260,"yearApprox":true,"dim":"explore","weight":3,"title":"朱士行西行写大品经","summary":"自长安出塞至于阗，得梵本遣还，为求法之始。","detail":{"background":"汉所译《道行》一经文句多阙，讲习之徒常恨其不备，以为大品之本未东。","process":"约260年（魏甘露中）颍川人朱士行以译本多阙，身往西域以求大本，发长安、出塞至于阗，从其国得《大品》梵书九十章；后遣弟子随使还东，其本至陈留仓垣，为无罗叉、竺叔兰等传出，号《放光般若》。","impact":"这是汉人僧侣西行求法有记载之始；求法之路自此与丝绸之路相合，梵本东传与译场之设立亦由是渐成常例。","figures":["朱士行","无罗叉","竺叔兰"],"place":"于阗（今新疆和田一带）","state":"魏、于阗","sources":["《高僧传·朱士行传》","《出三藏记集》"],"tags":["西行求法","于阗","佛教东传"]},"related":["cn--230--x01"]},
  {"id":"cn--262--f01","track":"cn","year":262,"yearApprox":true,"dim":"figure","weight":3,"title":"嵇康遇害于洛阳东市","summary":"坐吕安之案见杀，太学生三千人请以为师不许。","detail":{"background":"高平陵之变后司马氏诛除不附己者，正始名士多遇其害；嵇康以魏之宗室姻亚居河内山阳，与阮籍、向秀相从，锻于柳下而不答钟会之访。","process":"262年（景元三年，一说263年），嵇康因吕安之案为司隶钟会所构，司马昭责以非汤武而薄周孔，收系下狱；太学学生三千人上书请以为师，不许，遂与吕安同遇害于洛阳东市。康顾视日影，索琴弹《广陵散》而卒。","impact":"嵇康之死使竹林之名成一代之标志，其《声无哀乐论》《养生论》与与山涛绝交之书并传；此后名士口不臧否人物，魏晋之际言论之祸于斯可见。","figures":["嵇康","吕安","钟会","司马昭","阮籍"],"place":"洛阳东市（今河南洛阳东）","state":"魏","sources":["《晋书·嵇康传》","《三国志·魏书·王粲传》裴松之注引《魏氏春秋》"],"tags":["竹林","名士","言论之祸"]},"related":["cn--240--c01", "cn--249--p01"]},
  {"id":"cn--263--m01","track":"cn","year":263,"yearApprox":false,"dim":"military","weight":4,"title":"邓艾自阴平入成都，蜀亡","summary":"诸葛瞻战于绵竹，后主面缚舆榇，遣使奉降书。","detail":{"background":"魏以蜀有内衅，司马昭谋伐之；邓艾自阴平，钟会自斜谷骆谷分入，姜维退守剑阁以拒会。","process":"263年（景元四年）冬钟会与姜维相持于剑阁，邓艾自阴平行无人之地七百余里，凿山通道、以毡裹腹而坠险坡，遂至江油、绵竹；诸葛瞻战死，后主刘禅降艾于成都，姜维之众在剑阁者亦降，蜀汉遂亡，刘禅东迁洛阳。","impact":"立国四十三年的蜀汉以一郡之奇兵而亡，其险要在山川而不只在众寡；三国鼎立自此去其一，次年司马昭受晋公之封，魏祚亦尽。","figures":["邓艾","钟会","诸葛瞻","刘禅","姜维"],"place":"成都、绵竹、剑阁（今四川成都至剑阁一带）","state":"魏、汉（蜀）","sources":["《三国志·魏书·邓艾传》","《三国志·蜀书·后主传》","《资治通鉴》"],"tags":["阴平之奇袭","蜀汉之亡","山地之战"]},"related":["cn--228--m01", "cn--266--p01"]},

  {"id":"cn--263--s01","track":"cn","year":263,"yearApprox":false,"dim":"science","weight":4,"title":"刘徽注九章算术，立割圆之术","summary":"以割圆求周径密率，注九章而设重差以测高深。","detail":{"background":"《九章算术》为汉世所传算学之经，本文与注历世相沿，而旧说多未尽其义；刘徽以齐人，甄析难原、考核源流。","process":"263年（景元四年）刘徽注《九章算术》九卷毕，各为之释以明其所以然；又立割圆之说，自圆内接正六边形倍之至一百九十二边形，以勾股弦求圆径周率之差，定为周率周三径一之非密，又作《重差》一卷以测山高渊深。","impact":"中国算学自此有了以推理与极限求数的明证方法，割圆之术为其后祖冲之定密率所本；《九章》注本与《海岛算经》成为隋唐算学教育的定本。","figures":["刘徽"],"place":"曹魏洛阳与齐地（今山东临淄一带）","state":"魏","sources":["《九章算术》刘徽注","《隋书·经籍志》"],"tags":["算学","割圆术","数学方法"]},"related":["cn--121--c01"]},

  {"id":"cn--266--p01","track":"cn","year":266,"yearApprox":false,"dim":"politics","weight":4,"title":"司马炎代魏，国号晋","summary":"受禅于南郊，国号晋，改元泰始，追尊宣文景为帝。","detail":{"background":"265年八月司马昭卒于洛阳，其子炎嗣为晋王、相国；魏室之名器与典祀已在晋王之府，禅代之仪一仍曹魏故事。","process":"266年（泰始元年）十二月炎即皇帝位于洛阳南郊，国号晋，改元，追尊祖宣王懿、景王师、文帝昭为帝，封魏帝为陈留王，食邑万户、出嗣魏祀；大封宗室诸王，兼以郡国兵属之。","impact":"晋以禅代而有天下，故于君臣大义无所树立，唯以家族与共天下；宗室并握兵符临国，此制正为二十余年后八王之乱的张本。","figures":["司马炎","司马昭","魏帝","贾充"],"place":"洛阳（今河南洛阳东）","state":"晋","sources":["《晋书·武帝纪》","《三国志·魏书·三少帝纪》","《资治通鉴》"],"tags":["禅代","西晋","宗室封建"]},"related":["cn--249--p01", "cn--263--m01"]},

  {"id":"cn--268--i01","track":"cn","year":268,"yearApprox":false,"dim":"institution","weight":3,"title":"泰始律成，张杜为之注","summary":"贾充等定律二十篇，张斐、杜预为之注，与律并行。","detail":{"background":"汉魏以来律令章句繁乱，老吏舞文；晋室初兴，以魏《新律》为基更定律令，命贾充、杜预、张斐等参掌其事。","process":"268年（泰始四年）新律告成，凡二十篇，删苛漏、正名例，令文与律并行；张斐注律、杜预为之集解，诏以其注与律同用，又置律博士、令学者传习。其律以齐八姓、峻格、准五服以制罪为异于前代之处。","impact":"此律上承汉魏、下开隋唐，礼与律合、五服入罪之路自此而定；其注律之说亦为中国法律解释学之最早专书。","figures":["贾充","杜预","张斐","司马炎"],"place":"洛阳（颁于郡国）","state":"晋","sources":["《晋书·刑法志》","《晋书·杜预传》"],"tags":["泰始律","法典","律学"]},"related":["cn--266--p01"]},

  {"id":"cn--268--s01","track":"cn","year":268,"yearApprox":true,"dim":"science","weight":4,"title":"裴秀立制图六体，作禹贡地域图","summary":"以分率、准望、道里、高下方邪纵横之法画天下之图。","detail":{"background":"汉魏地图多不设分率、又审大径而亡其细数，图画虽存而不可用以核地里；司空裴秀少而好学，留心地利。","process":"约268年（泰始中）司空裴秀上《禹贡地域图》一十八篇并《序》，立制图六体：分率所以审率大之形、准望所以正彼此之体、道里所以定所由之数，加以高下、方邪、迁直之制宜，以纠舆地之失；又省《天下大图》为《方丈图》。","impact":"中国地图学自此有了可校可复的数学基础，其六体之说为后世所遵；唐代贾耽、元代朱思本之图，皆沿此路而来。","figures":["裴秀","司马炎"],"place":"洛阳（司空府上奏）","state":"晋","sources":["《晋书·裴秀传》","《隋书·经籍志》"],"tags":["地图学","制图六体","疆域勘察"]},"related":["cn--97--x01", "cn--520--x01"]},

  {"id":"cn--280--m01","track":"cn","year":280,"yearApprox":false,"dim":"military","weight":4,"title":"六军下江南，吴亡","summary":"王濬自蜀东下，孙皓面缚舆榇而降，天下复为一统。","detail":{"background":"晋既代魏，与吴相持于襄阳、夏口之间，羊祜镇荆州以信义结吴人、杜预代镇而益修军备；吴末孙皓苛虐，君臣解体。","process":"280年（太康元年、天纪四年）正月晋以王浑、王濬、杜预、唐彬、胡奋、王戎六将军分道并下，濬自蜀中连船东下、烧其铁锁铁锥，三月至秣陵之石头，孙皓面缚舆榇于军门请降，送于洛阳，封归命侯；江州诸郡传檄而定。","impact":"自汉末分裂近百年，天下复归一统；而江南士族与北方政权之间的主客之局，此后一直纠缠至永嘉之乱以后。","figures":["司马炎","王濬","杜预","羊祜","孙皓"],"place":"建业（今江苏南京）","state":"晋","sources":["《晋书·武帝纪》","《晋书·王濬传》","《资治通鉴》"],"tags":["灭吴","水战","统一"]},"related":["cn--266--p01", "cn--222--m01"]},

  {"id":"cn--280--i01","track":"cn","year":280,"yearApprox":false,"dim":"institution","weight":3,"title":"颁户调式，行占田课田之制","summary":"男子占田七十亩，课田五十亩，女子各半，户出绢绵。","detail":{"background":"魏晋之际兵革之后，田荒而民流，屯田之制渐坏；太康既定，乃度天下之田而限以品官之荫，欲以劝农而齐赋役。","process":"280年（太康元年）晋颁户调式：男子得占田七十亩、女子三十亩，其外课田男子五十亩、女子二十亩，户出绢三匹、绵三斤；品官以高下得荫人以为衣食客及佃客，又限民徙、定吏之考课。","impact":"此为中央第一次同时规定占田、课田与荫客之数，力图把流民、荒地、赋役连成一体；然占田未必能授、荫客反成豪强之利，故其效甚短，而北魏均田之制实承其余绪。","figures":["司马炎","杜预","张斐"],"place":"洛阳（令行于郡国）","state":"晋","sources":["《晋书·食货志》","《晋书·武帝纪》"],"tags":["占田制","户调","赋役"]},"related":["cn--196--i01", "cn--485--i01"]},

  {"id":"cn--291--p01","track":"cn","year":291,"yearApprox":false,"dim":"politics","weight":5,"title":"八王之乱起，贾后与楚王诛杨氏","summary":"外戚杨骏、汝南王亮、楚王玮相继死，诸王遂争中枢。","detail":{"background":"290年武帝崩，惠帝以不慧即位，太傅杨骏以帝舅秉政，多引后族而疏宗室；皇后贾氏以楚王玮有勇，阴使之。","process":"291年（元康元年）三月诏夺杨骏兵权，楚王玮率众废杨骏，诛其三族，以汝南王亮与卫瓘同辅政；六月贾后又使玮矫诏攻司马亮与卫瓘，杀之，寻数玮专擅之罪而弃市。贾后自此专朝政，张华、裴頠等居其位而无所匡正。","impact":"宗室诸王以勤王之名得入京师，中央威权自此不可复收；十六年间诸王迭起相攻，惠帝废立不常，遂有永嘉、建兴之祸。","figures":["贾后","杨骏","司马玮","司马亮","司马衷"],"place":"洛阳（今河南洛阳东）","state":"晋","sources":["《晋书·惠帝纪》","《晋书·贾充传》","《资治通鉴》"],"tags":["八王之乱","外戚","宗室"]},"related":["cn--280--m01", "cn--311--m01"]},

  {"id":"cn--304--p01","track":"cn","year":304,"yearApprox":false,"dim":"politics","weight":3,"title":"李雄称成都王，成汉立国","summary":"氐人李特之子据蜀，至是称王，年号建兴。","detail":{"background":"永宁以来齐万年之乱与氐蜀流民相仍，李特、李雄兄弟自略阳入蜀，因流民七十余万在东，遂据广汉起事；李特战死于成都。","process":"304年（永兴元年）李雄称成都王，改元建兴，寻于306年即皇帝位，国号大成；其治宽刑省役、收用流民之豪杰，蜀、汉、建宁、宁州之地多附于李氏。","impact":"成汉立国使益州自此不复属于中央近四十年，而衣冠之族南奔与氐羌之内徙并起，巴蜀成为南北之间的另一区。","figures":["李雄","李特","李寿"],"place":"成都（今四川成都）","state":"成汉","sources":["《晋书·李特载记》","《华阳国志·李特雄期寿势志》"],"tags":["成汉","流民","割据"]},"related":["cn--347--m01", "cn--291--p01"]},

  {"id":"cn--304--p02","track":"cn","year":304,"yearApprox":false,"dim":"politics","weight":4,"title":"刘渊称汉王于左国城","summary":"以匈奴五部之众起，追尊汉氏，国号曰汉。","detail":{"background":"南匈奴自东汉以来分部并、平阳一带，其豪右习中国文书；晋室八王相攻，征兵诸部，匈奴左部遂离心。","process":"304年（永兴元年）刘渊于左国城称大单于、寻称汉王，追尊刘禅以绍汉氏之统，年号元熙；其众渐并离石、平阳，招集五部之众。渊卒后其子聪、曜相继，311年陷洛阳、316年陷长安。","impact":"这是六朝时第一个在中原腹地建立的胡族汉式政权；其国号、谥号、礼乐多取汉晋之制，此后石勒、刘曜、慕容、苻氏皆沿其规模。","figures":["刘渊","刘聪","刘曜","司马衷"],"place":"左国城、平阳（今山西离石、临汾一带）","state":"汉（前赵）","sources":["《晋书·刘元海载记》","《资治通鉴》"],"tags":["前赵","匈奴","汉式政权"]},"related":["cn--291--p01", "cn--311--m01"]},

  {"id":"cn--311--m01","track":"cn","year":311,"yearApprox":false,"dim":"military","weight":5,"title":"刘曜、石勒陷洛阳，怀帝见获","summary":"王衍十馀万行军败于宁平，京师倾覆、帝北迁。","detail":{"background":"洛阳自八王之乱后户不聊生、漕运不继，刘渊之子刘聪据平阳，与石勒、刘曜等四出抄司隶；太尉王衍奉东海王司马越之丧东归。","process":"311年（永嘉五年、嘉平元年）四月石勒追及王衍于宁平，晋军十余万（记载之数）不复能战，衍及诸王公皆见杀；六月刘曜、王弥、石勒同会攻京师，城陷，纵兵大掠，帝为所获，迁于平阳，太子、诸王与官僚死者三万余人（记载之数）。","impact":"西晋的中央机构在洛阳一战中被摧毁，中原衣冠之族自此相率南奔；史称永嘉之乱，北方州郡之残破、坞壁之遍立皆起于此。","figures":["司马炽","刘曜","石勒","王衍","王弥"],"place":"洛阳、宁平（今河南鹿邑、永城一带）","state":"晋、汉（前赵）","sources":["《晋书·孝怀帝纪》","《晋书·刘聪载记》","《资治通鉴》"],"tags":["永嘉之乱","洛阳之陷","衣冠南渡"]},"related":["cn--291--p01", "cn--313--e01"]},

  {"id":"cn--313--e01","track":"cn","year":313,"yearApprox":true,"dim":"economy","weight":3,"title":"中州士民避乱南奔江左","summary":"司、豫、兖、青、徐之人流移南下，江左户口为之一变。","detail":{"background":"洛阳倾覆之后，并、司诸州继以兵旱，匈奴、羯、氐、羌诸部更相攻击，坞主不能自固，乃举族随道而行，多者千里而近。","process":"自311年起，中原士女避乱江左者十六七（《晋书·王导传》所记比例），过江者以兖、青、徐、司、豫诸州人为多，沿淮、汉而南；司马睿镇建邺，王导为之收拔荆扬之士，立侨郡侨县以安流寓。","impact":"南方第一次得到大量有户籍、有经学、有耕作与手工业经验的移入人口，江左的财赋与士族皆由是成；南北经济、文化重心的消长自此开始。","figures":["司马睿","王导"],"place":"江左（今江苏南京至浙江北部）","state":"晋","sources":["《晋书·王导传》","《宋书·州郡志》"],"tags":["衣冠南渡","流民","侨置"]},"related":["cn--311--m01", "cn--317--p01"]},

  {"id":"cn--316--m01","track":"cn","year":316,"yearApprox":false,"dim":"military","weight":4,"title":"刘曜围长安，愍帝出降，西晋亡","summary":"长安食尽，帝乘羊出降，送平阳而遇害。","detail":{"background":"洛阳陷后，京兆与弘农之众立秦王司马邺于长安，索綝、麴允等守之而内相疑贰；刘曜西并陇右之众，长围渐合。","process":"316年（建兴四年）十一月，刘曜急攻长安，城中米斗万钱、人相食，守者多亡；帝乃乘羊出降，肉袒舆榇，送于平阳，素衣青袍行酒于宴群臣之间，明年遇害于平阳。","impact":"晋室在长安的最后一任朝廷倾覆，愍帝一死而司马氏之南渡遂不复以还都为念；北中方有刘、石分据之局。","figures":["司马邺","刘曜","麴允","索綝"],"place":"长安（今陕西西安西北）","state":"晋、汉（前赵）","sources":["《晋书·孝愍帝纪》","《晋书·刘曜载记》"],"tags":["长安之陷","西晋之亡","前赵"]},"related":["cn--311--m01", "cn--317--p01"]},
  {"id":"cn--317--p01","track":"cn","year":317,"yearApprox":false,"dim":"politics","weight":5,"title":"司马睿即晋王位，东晋立国江南","summary":"长安音问断绝，睿于建康即晋王位，宗庙社稷移于江表","detail":{"background":"怀帝陷平阳之后，豫章王端在长安不为南人所附，睿以疏宗镇江东，王导与从兄敦左右扶持，江东方渐宁辑。","process":"建武元年三月，睿即晋王位，改元建武，备置百官，立宗庙社稷于建康；次年愍帝遇害之问至，乃即皇帝位，是为元帝。","impact":"晋室社稷由黄河流域移至长江下游，门阀与皇权共治之局定型，宋、齐、梁、陈皆承此疆而立。","figures":["司马睿","王导","刁协","刘隗"],"place":"建康（今江苏南京）","state":"东晋","sources":["《晋书·元帝纪》","《晋书·王导传》"],"tags":["东晋立国","门阀政治","衣冠南渡"]},"related":["cn--316--m01", "cn--319--p01"]},

  {"id":"cn--319--p01","track":"cn","year":319,"yearApprox":false,"dim":"politics","weight":3,"title":"石勒即赵王位，都襄国","summary":"勒与刘曜自相恃转为相攻，据河北而建国号赵","detail":{"background":"石勒早年流徙被卖，后聚众起兵，得张宾为谋主，取襄国为根基，与长安刘曜由相凭恃转为相疑。","process":"319年，石勒即赵王位，以襄国为都，建置百官，尊张宾为右侯；又聚中州衣冠士族于崇仁里，谓之君子营，为之立学。","impact":"河北入后赵统绪，两赵并立使中原相持更久；胡汉分治与劝课农桑并行，为十六国前期较稳固的统治。","figures":["石勒","张宾","刘曜"],"place":"襄国（今河北邢台）","state":"后赵","sources":["《晋书·石勒载记》"],"tags":["后赵","胡汉分治","坞壁流民"]},"related":["cn--316--m01", "cn--317--p01"]},

  {"id":"cn--321--f01","track":"cn","year":321,"yearApprox":true,"dim":"figure","weight":3,"title":"祖逖卒于雍丘，北伐中辍","summary":"黄河以南已多归晋，会朝廷方任刘隗，逖志未就","detail":{"background":"祖逖少与刘琨同居司州，以鸡鸣相励；永嘉乱后率宗党数百家南渡，元帝用为豫州刺史，听其自征集。","process":"逖屯淮阴，起冶铸兵，得二千余人而后进，渡江中流击楫而誓；进军雍丘，黄河以南多归晋。太兴四年病卒于雍丘。","impact":"逖既卒，赵人乘势取河南，所复城邑多没；东晋遂以守淮为界，无复建武初北向之锐。","figures":["祖逖","司马睿","刘隗","刁协"],"place":"雍丘（今河南杞县）","state":"东晋","sources":["《晋书·祖逖传》","《晋书·元帝纪》"],"tags":["北伐","流民武装","君臣相疑"]},"related":["cn--317--p01", "cn--311--m01"]},

  {"id":"cn--322--m01","track":"cn","year":322,"yearApprox":false,"dim":"military","weight":3,"title":"王敦举兵，陷建康","summary":"以讨刘隗为名顺江而下，周顗、戴若思遇害","detail":{"background":"元帝用刘隗、刁协，欲以法绳豪强，又出隗于合肥以潜为之备；敦以兴复之功自居，内不能平。","process":"永昌元年，敦于武昌以讨刘隗为名举兵，沈充、钱凤应之，舟师东下；六月陷建康，顗、若思并为所杀，敦还屯姑孰。","impact":"朝廷威权大损，王导闭门待罪而反得固位；东晋门阀政治由共治转为强藩挟制中枢。","figures":["王敦","刘隗","周顗","司马睿"],"place":"武昌、建康（今湖北鄂州、江苏南京）","state":"东晋","sources":["《晋书·王敦传》","《晋书·元帝纪》"],"tags":["门阀政治","江州兵权","士族"]},"related":["cn--317--p01", "cn--328--m01"]},

  {"id":"cn--328--m01","track":"cn","year":328,"yearApprox":false,"dim":"military","weight":3,"title":"苏峻入建康，寻阳结盟讨之","summary":"庾亮征峻而峻与祖约同反，陶侃温峤立盟东下","detail":{"background":"峻以平王敦之功拥兵淮南，朝廷不能制；庾亮辅政，欲征峻以解其兵，峻遂与祖约同举。","process":"咸和二年峻、约举兵，三年二月陷建康，宫寺为火所焚；亮与王导泛舟白石，峤与陶侃盟于寻阳，是年峻于石头战死。","impact":"台城焚毁略尽，东晋兵权由此长在上游方镇，荆江与朝廷之势自此相持不移。","figures":["苏峻","庾亮","陶侃","温峤"],"place":"建康、寻阳（今江苏南京、江西九江）","state":"东晋","sources":["《晋书·苏峻传》","《晋书·陶侃传》"],"tags":["流民帅","上游方镇","宫室焚毁"]},"related":["cn--322--m01"]},

  {"id":"cn--330--s01","track":"cn","year":330,"yearApprox":false,"dim":"science","weight":4,"title":"虞喜推得岁差之数","summary":"校古历与今之天度，谓五十年退行一度","detail":{"background":"历家自汉以来皆以周天三百六十五度四分之一为定，不知冬至日岁有西移；魏晋之际，旧历与天渐不相中。","process":"喜取古历与当世所测相较，推其差数，以为五十年退行一度，岁自有差而天不止，后之治历者须随差而改。","impact":"岁差之数既立，历法须代改乃可密合；祖冲之用其法以造大明历，北朝历家亦渐取之。","figures":["虞喜","祖冲之"],"place":"会稽余姚（今浙江余姚）","state":"东晋","sources":["《宋书·历志》","《晋书·儒林传》"],"tags":["历法","岁差","天文"]},"related":["cn--132--s01", "cn--462--s01"]},

  {"id":"cn--337--p01","track":"cn","year":337,"yearApprox":false,"dim":"politics","weight":3,"title":"慕容皝即燕王位，都龙城","summary":"鲜卑慕容氏建于辽西，东北由是成一政治重心","detail":{"background":"慕容廆居辽西，招抚中州流亡士民，置侨郡县，渐慕华夏文物；皝嗣位，与后赵石虎争于幽冀之间。","process":"337年，皝即鲜卑大单于、燕王位，国号燕，史称前燕；其后营龙城而徙都之，劝课农桑，立小学以教胄子。","impact":"前燕为东方一强，与关中、襄国相持；辽西一隅保存衣冠礼乐，为北朝后期之盛业所自出。","figures":["慕容皝","慕容廆","封裕","韩恒"],"place":"龙城（今辽宁朝阳）","state":"前燕","sources":["《晋书·慕容皝载记》","《晋书·慕容廆载记》"],"tags":["前燕","鲜卑","辽西"]},"related":["cn--319--p01", "cn--370--m01"]},

  {"id":"cn--347--m01","track":"cn","year":347,"yearApprox":false,"dim":"military","weight":4,"title":"桓温溯江，平成汉","summary":"李势面缚请罪，三蜀之地归于建康","detail":{"background":"李氏有蜀四十余年，至势而政刑弛紊，人心离散；温欲立功以重其望，朝士多以为不可，庾冰独谓必克。","process":"永和三年，温率袁乔等步骑溯江西上，至彭模分兵而进，与势战于成都笮桥，温军小却而力战破之；势夜遁，明旦面缚请罪，温释之。","impact":"成汉亡，长江上游尽入温有，荆江之势由是足以倾动中朝；温寻有三度北伐之举。","figures":["桓温","李势","袁乔","庾冰"],"place":"成都（今四川成都）","state":"东晋","sources":["《晋书·桓温传》","《华阳国志·李特雄期寿势志》"],"tags":["成汉","巴蜀","上游方镇"]},"related":["cn--304--p01", "cn--371--p01"]},

  {"id":"cn--353--a01","track":"cn","year":353,"yearApprox":false,"dim":"art","weight":4,"title":"会稽兰亭修禊，王羲之作序","summary":"四十余人列坐流觞，醉为之序，世以为绝唱","detail":{"background":"江左承平，名士以任达相尚，上巳祓除之会渐为文酒之集；羲之时以右军将军领会稽内史。","process":"永和九年三月三日，与谢安、孙绰、许询等会于山阴兰亭之次，流觞赋诗，列叙其人；羲之为之文序，以鼠须笔书之。","impact":"序文与其书并行后世，行书由是有典范；江南士族文酒雅集之风，至是定型。","figures":["王羲之","谢安","孙绰","许询"],"place":"会稽山阴兰亭（今浙江绍兴）","state":"东晋","sources":["《晋书·王羲之传》","《兰亭集序》"],"tags":["书法","雅集","玄言"]},"related":["cn--383--m01"]},

  {"id":"cn--366--a01","track":"cn","year":366,"yearApprox":false,"dim":"art","weight":4,"title":"乐僔于鸣沙山始凿石窟","summary":"沙门东游见光影如列佛，架空岩石而造一龛","detail":{"background":"前秦建元之世，沙门以苦行感俗者往往山居立龛；敦煌当玉门、阳关之口，僧徒东来者多止于此。","process":"建元二年，沙门乐僔东游至鸣沙山，忽睹光影状若列佛，即而架凿岩石，始造一龛；未几法良继之，历代增修，窟龛渐盛。","impact":"莫高窟之营建由此始，历北朝、隋、唐续凿至千余区，为丝道上最大石窟寺群。","figures":["乐僔","法良"],"place":"敦煌鸣沙山（今甘肃敦煌）","state":"前秦","sources":["《莫高窟修佛龛碑》","《沙州图经》"],"tags":["石窟","敦煌","丝路"]},"related":["cn--460--a01", "cn--516--a01"]},

  {"id":"cn--370--m01","track":"cn","year":370,"yearApprox":false,"dim":"military","weight":5,"title":"王猛克邺，前燕亡","summary":"秦师出壶关，慕容评军溃，慕容暐出走见禽","detail":{"background":"猛相秦而关陇遂宁，坚欲东向；会燕政在慕容评，猜逐名将，慕容垂奔秦，猛因请师。","process":"建元六年，猛率杨安等出上党，攻壶关，克晋阳；评拥众距潞川，军志曰不鼓不列，猛进而大破之，进围邺，暐出降。","impact":"关东郡县尽入于前秦，坚之地东尽山海；徙鲜卑诸种于关中，为后日之乱所自起。","figures":["王猛","苻坚","慕容垂","慕容暐"],"place":"邺城（今河北临漳西）","state":"前秦","sources":["《晋书·苻坚载记》","《晋书·王猛传》","《晋书·慕容暐载记》"],"tags":["前燕","前秦","邺城"]},"related":["cn--337--p01", "cn--375--f01"]},

  {"id":"cn--371--p01","track":"cn","year":371,"yearApprox":false,"dim":"politics","weight":3,"title":"桓温废海西公","summary":"温入朝称疾，以太后令行废立，立会稽王昱","detail":{"background":"温既有平蜀之功，三举北伐而还，自谓有伊、周之任；海西居位，温欲以危惴之事动之。","process":"太和六年十一月，温入朝，与崇德太后谋，奏帝昏聩，废为东海王，出就旧第；立会稽王昱，是为简文帝，温还姑孰。","impact":"废立于上游方镇之口，皇权轻重视强臣为转移；温寻求九锡，谢安、王坦之从容制之。","figures":["桓温","司马奕","司马昱"],"place":"建康（今江苏南京）","state":"东晋","sources":["《晋书·海西公纪》","《晋书·桓温传》"],"tags":["废立","门阀政治","荆州"]},"related":["cn--347--m01", "cn--322--m01"]},

  {"id":"cn--375--f01","track":"cn","year":375,"yearApprox":false,"dim":"figure","weight":4,"title":"王猛病笃，苻坚亲问后事","summary":"遗表以晋未可图、鲜卑羌为仇，秦失其柱石","detail":{"background":"猛起于微时，一见坚而若符，任以机务，明法峻断，贵戚不能容而坚任之不疑。","process":"建元十一年猛病笃，坚亲诣其第问之；猛遗表以为晋虽僻在江南，正朔相承，未可图也，鲜卑、羌虏并我之仇，愿不以伐晋为念。","impact":"猛卒而坚慟之，以为天不令其混一；八年之后有淝水之败，关中遂分，秦之兴亡多系于猛之存亡。","figures":["王猛","苻坚","慕容垂"],"place":"长安（今陕西西安西北）","state":"前秦","sources":["《晋书·王猛传》","《晋书·苻坚载记》"],"tags":["前秦","丞相","淝水"]},"related":["cn--370--m01", "cn--383--m01"]},

  {"id":"cn--376--p01","track":"cn","year":376,"yearApprox":false,"dim":"politics","weight":3,"title":"前秦灭前凉，乘取代国","summary":"张天锡面缚出降，代国内乱而秦分其众","detail":{"background":"凉自张轨保有河右，世修职贡，中州士民避地多归之，至天锡而内难寻起；代国拓跋什翼犍与秦相邻，诸部未定。","process":"建元十二年，坚遣吕光等西征，天锡面缚请罪，凉亡，以其地为凉州；同年代国内乱，什翼犍见杀于其子，秦以刘库仁分领其东部。","impact":"北境自刘曜以来复归一家，坚之地西接西域、北至漠南；江南由是独当其冲。","figures":["苻坚","张天锡","吕光","拓跋什翼犍"],"place":"姑臧、云中（今甘肃武威、内蒙古托克托东北）","state":"前秦","sources":["《晋书·苻坚载记》","《晋书·张轨传》"],"tags":["前凉","代国","河西"]},"related":["cn--370--m01", "cn--386--p01"]},

  {"id":"cn--383--m01","track":"cn","year":383,"yearApprox":false,"dim":"military","weight":5,"title":"淝水之战，秦师溃还","summary":"坚率大众南下，谢玄请退师而战，秦军遂坏","detail":{"background":"坚并关陇、辽海之众，以为江南可一举而定，朝臣多谏，慕容垂、姚苌独劝之；晋以谢安处内，谢玄、谢石当外。","process":"太元八年八月，坚发诸军，以为以吾之众投鞭于江足以为限；十月前锋至淝水，玄等请秦军少却以决战，小退而不可复止，朱序在阵后呼秦兵败，苻融马倒见杀，坚中流矢，单骑还洛阳。","impact":"秦师星散，人声鹤唳皆为晋兵，北方复分；江南由是获安，谢氏之望遂重。","figures":["苻坚","谢安","谢玄","苻融","朱序"],"place":"淝水（今安徽寿县东）","state":"东晋","sources":["《晋书·苻坚载记》","《晋书·谢安传》","《世说新语·雅量》"],"tags":["淝水","前秦","东晋"]},"related":["cn--375--f01", "cn--384--p01"]},

  {"id":"cn--384--p01","track":"cn","year":384,"yearApprox":false,"dim":"politics","weight":3,"title":"慕容垂复国，北方再分","summary":"垂称燕王于河北，姚苌亦自立于关中","detail":{"background":"淝水之后，诸没落部众各怀去就；慕容垂请以省陵为名出邺，至河间而起兵，河北鲜卑皆应之。","process":"384年正月，垂称燕王，史称后燕，进围邺城以固河北；同年慕容冲称王于关中，姚苌亦自立称秦王，西燕、后秦并起。","impact":"前秦之北一分而为后燕、西燕、后秦之数方，数十年相攻不绝；拓跋氏亦乘是复其代业。","figures":["慕容垂","姚苌","慕容冲","苻坚"],"place":"中山、邺城（今河北定州、临漳西）","state":"后燕","sources":["《晋书·慕容垂载记》","《晋书·姚苌载记》"],"tags":["后燕","分裂","关东"]},"related":["cn--383--m01", "cn--386--p01"]},
  {"id":"cn--386--p01","track":"cn","year":386,"yearApprox":false,"dim":"politics","weight":4,"title":"拓跋珪即代王位，国号称魏","summary":"什翼犍之孙收抚旧部于牛川，代业复立","detail":{"background":"代国为前秦所并，什翼犍死于内难；淝水之后诸部星散，珪以旧王之孙还自后燕，收集遗众于牛川。","process":"登国元年正月，珪即代王位，改元登国，国号称魏，都于盛乐；其夏独孤部刘显来争，珪击破之，诸部稍附。","impact":"拓跋氏复国，是为北魏之始；自此河北之局转为魏与后燕相持，十余年而有中原。","figures":["拓跋珪","刘显","慕容垂"],"place":"盛乐（今内蒙古和林格尔西北）","state":"北魏","sources":["《魏书·太祖纪》"],"tags":["北魏","复国","盛乐"]},"related":["cn--384--p01", "cn--391--m01"]},

  {"id":"cn--391--m01","track":"cn","year":391,"yearApprox":false,"dim":"military","weight":3,"title":"拓跋珪破铁弗刘卫辰","summary":"卫辰兵败见杀，其子勃勃奔于后秦","detail":{"background":"刘卫辰居朔方，先附前秦，秦败而贰于代；珪既复国，卫辰数侵西北边。","process":"登国六年珪西讨之，济河而阵，卫辰走死，收其部众，尽徙而东；其子勃勃奔后秦，依没弈干。","impact":"河济之北尽为魏有；夏赫连氏由亡国之余起于关右，与拓跋氏世为仇敌。","figures":["拓跋珪","刘卫辰","赫连勃勃"],"place":"朔方（今内蒙古南部、陕西北部一带）","state":"北魏","sources":["《魏书·太祖纪》","《晋书·赫连勃勃载记》"],"tags":["铁弗","赫连","河套"]},"related":["cn--430--m01"]},

  {"id":"cn--398--p01","track":"cn","year":398,"yearApprox":false,"dim":"politics","weight":4,"title":"拓跋珪称帝，徙都平城","summary":"并中山之后建国号称魏，朝仪粗具","detail":{"background":"魏自盛乐而南，克晋阳、取中山，河北略定；旧都在塞外，于中原为远。","process":"天兴元年珪即皇帝位，改元天兴，国号大魏；是年徙都平城，营宗庙社稷宫室，徙六州吏民以实京师，命崔宏草创朝仪。","impact":"平城为北方之都垂百年，至孝文迁洛而后已；华夏仪制与鲜卑部落之俗并行于其间。","figures":["拓跋珪","崔宏"],"place":"平城（今山西大同东北）","state":"北魏","sources":["《魏书·太祖纪》","《魏书·崔宏传》"],"tags":["北魏","平城","朝仪"]},"related":["cn--386--p01", "cn--494--p01"]},

  {"id":"cn--399--x01","track":"cn","year":399,"yearApprox":true,"dim":"explore","weight":4,"title":"法显等发长安，西行求戒律","summary":"以中土律藏阙如，遂逾流沙历三十余国","detail":{"background":"法显以晋世律藏阙如，众经多残，常欲西征以求其本；同志慧景、慧达、道整等相与结侣。","process":"隆安中，与慧景等发长安，出玉门而涉流沙，随众行道；历三十余国，于摩头罗等处写经求律，至师子国得弥沙塞律藏。","impact":"义熙中年泛海而还，至青州长广郡牢山，后至建康译出所将诸部；所撰行记为求法僧人最早完整行记之一。","figures":["法显","慧景"],"place":"自长安至中天竺、师子国","state":"东晋","sources":["《历游天竺记传》","《出三藏记集》"],"tags":["求法","律藏","陆去海还"]},"related":["cn--402--c01"]},
  {"id":"cn--400--s01","track":"cn","year":400,"yearApprox":true,"dim":"science","weight":3,"title":"《孙子算经》明十进位值布算","summary":"凡算之法，先识其位；一纵十横，百立千僵。","detail":{"background":"以算筹记数布算之法起于春秋战国，汉世算学诸经已惯用之而不着其例；《孙子算经》不题撰人，其书经北周甄鸾注、唐李淳风等奉诏注释乃显。","process":"卷下明布算之式曰「凡算之法，先识其位。一纵十横，百立千僵，千十相望，万百相当」：以纵横二式分置个、百、万与十、千、亿之位，空位不以筹填之，一至九之实值由其所在之位定之；其乘除、开方诸术皆就此位制而行。","impact":"十进位值制配以算筹，使四则、开方、联立方程诸术可依固定程式逐步施行，历算、田赋、工程之算皆由此出；中国算筹之位值制与印度—阿拉伯数码之位值制，学界多以为各自独立形成而同归十进。","figures":["甄鸾","李淳风"],"place":"建康、长安（书传于南北）","state":"魏晋至唐","sources":["《孙子算经·卷下》","《隋书·经籍志》"],"tags":["算筹","十进位值制","孙子算经"]},"related":["cn--50--s01","cn--263--s01"]},

  {"id":"cn--402--c01","track":"cn","year":402,"yearApprox":false,"dim":"culture","weight":3,"title":"庐山僧众像前共期西方","summary":"慧远集同志建斋立誓，净土之盟发端","detail":{"background":"慧远自太元中止庐山三十余年，影不出山，江左士庶宗之；山中造无量寿佛像。","process":"元兴元年，与刘遗民、周续之等同志集于精舍无量寿像前，建斋立誓，共期西方，遗民为之文。","impact":"净土之盟自此发端，后世以庐山为莲社之祖；其誓愿之文载于本传。","figures":["慧远","刘遗民","周续之"],"place":"庐山（今江西九江西南）","state":"东晋","sources":["《高僧传·慧远传》"],"tags":["净土","庐山","僧团"]},"related":["cn--399--x01", "cn--446--c01"]},

  {"id":"cn--404--m01","track":"cn","year":404,"yearApprox":false,"dim":"military","weight":3,"title":"刘裕起兵京口，克建康","summary":"桓玄移晋祚未久，裕与何无忌等盟而讨之","detail":{"background":"玄以荆楚之众东下而移晋祚，政刑不立，人望日轻；北府旧兵多居京口，为江左劲旅。","process":"元兴三年，裕与何无忌、刘毅、孟昶等起于京口，斩桓修；刘毅等于广陵杀桓谦，裕进克堂邑，以寡击众，数十日而入建康，玄西走见杀。","impact":"裕以此立佐命之功而居朝右，桓氏荆江之业渐入北府之手；晋之威权自此尽归于裕。","figures":["刘裕","何无忌","刘毅","桓玄"],"place":"京口、建康（今江苏镇江、南京）","state":"东晋","sources":["《宋书·武帝纪》","《晋书·桓玄传》"],"tags":["北府兵","京口","晋宋之际"]},"related":["cn--420--p01", "cn--410--m01"]},

  {"id":"cn--405--f01","track":"cn","year":405,"yearApprox":false,"dim":"figure","weight":4,"title":"陶渊明去彭泽令，作归去来兮辞","summary":"郡遣督邮至县，不堪束带而解印绶去职","detail":{"background":"渊明家贫亲老，尝仕于桓氏之幕，后为彭泽令；郡遣督邮至县，吏白应束带见之。","process":"义熙元年十一月，叹曰岂能为五斗米折腰向乡里小儿，即日解印绶去职，赋归去来兮辞以见其志。","impact":"归田之志与田园之文自此并行；其诗为后世隐逸一派之宗，其辞千载传诵。","figures":["陶潜","刘敬宣"],"place":"彭泽、柴桑（今江西彭泽、九江西南）","state":"东晋","sources":["《晋书·隐逸传》","《宋书·隐逸传》","《归去来兮辞序》"],"tags":["归隐","田园诗","彭泽"]},"related":[]},

  {"id":"cn--410--m01","track":"cn","year":410,"yearApprox":false,"dim":"military","weight":3,"title":"刘裕克广固，南燕亡","summary":"舍舟过山而进，广固城拔，慕容超见禽","detail":{"background":"南燕保有青兖，数以骑兵南掠宿豫；裕表请伐之，朝议多以为不可。","process":"义熙五年，裕率舟师自淮入泗，舍舟徒步入大岘，过山而喜；进至广固而围之，拔其城，禽慕容超，送建康斩之。","impact":"青兖入于东晋，是为裕第一次北伐之绩；裕由是益重，寻有关洛之谋。","figures":["刘裕","慕容超"],"place":"广固（今山东青州西北）","state":"东晋","sources":["《宋书·武帝纪》","《晋书·慕容超载记》"],"tags":["北伐","南燕","广固"]},"related":["cn--417--m01", "cn--404--m01"]},

  {"id":"cn--417--m01","track":"cn","year":417,"yearApprox":false,"dim":"military","weight":4,"title":"刘裕克长安，后秦亡","summary":"舟师溯河，诸军破潼关，姚泓出降","detail":{"background":"裕既平广固，以关中可以乘取；会姚兴死，诸子相攻，姚泓立而内难未已。","process":"义熙十三年，裕以舟师自淮泗通汴入河，王镇恶等出陆路，破潼关，亲至霸上；泓出降，送建康斩之，长安平。","impact":"两京复为晋有；裕以刘穆之死而东还，诸将相图，长安旋为赫连勃勃所并，而军功盖世，代晋之势成。","figures":["刘裕","姚泓","王镇恶","刘穆之"],"place":"长安（今陕西西安西北）","state":"东晋","sources":["《宋书·武帝纪》","《晋书·姚泓载记》"],"tags":["北伐","关中","两京"]},"related":["cn--410--m01", "cn--420--p01"]},

  {"id":"cn--420--p01","track":"cn","year":420,"yearApprox":false,"dim":"politics","weight":5,"title":"刘裕受晋禅，国号宋","summary":"恭帝逊位，宋王即皇帝位，改元永初","detail":{"background":"裕起于细微，自北府而总大政，平桓氏、禽慕容超、定关洛，封宋公加殊礼，晋之符命已尽。","process":"永初元年六月，裕受晋禅即皇帝位，国号大宋，改元；奉恭帝为零陵王，明年而殒，晋之宗室稍尽。","impact":"东晋亡而南朝更代之局成，宋、齐、梁、陈皆以握兵之臣受禅；北府集团执朝政之柄。","figures":["刘裕","司马德文","傅亮"],"place":"建康（今江苏南京）","state":"南朝宋","sources":["《宋书·武帝纪》","《晋书·恭帝纪》"],"tags":["禅代","南朝","北府兵"]},"related":["cn--417--m01", "cn--404--m01"]},

  {"id":"cn--423--p01","track":"cn","year":423,"yearApprox":false,"dim":"politics","weight":3,"title":"顾命大臣废少帝，迎立文帝","summary":"徐羡之等以太后令行事，易置幼君","detail":{"background":"武帝崩时以少帝年幼，置顾命之臣，徐羡之、傅亮、檀道济、谢晦预焉；少帝亲昵群小，羡之等不自安。","process":"景平元年，羡之等以少帝不堪奉大器，白太后废为营阳王，寻见杀；迎宜都侯义隆于江陵而立之，是为文帝。","impact":"幼主可以大臣之手废立，南朝权臣易君之局至是成习；文帝立而徐、傅寻亦伏诛。","figures":["徐羡之","傅亮","檀道济","刘义隆"],"place":"建康、江陵（今江苏南京、湖北荆州）","state":"南朝宋","sources":["《宋书·少帝纪》","《宋书·徐羡之传》"],"tags":["顾命","废立","南朝宋"]},"related":["cn--420--p01", "cn--429--c01"]},

  {"id":"cn--429--c01","track":"cn","year":429,"yearApprox":false,"dim":"culture","weight":4,"title":"诏裴松之注《三国志》","summary":"以陈寿书简略，命松之多所增广","detail":{"background":"陈寿《三国志》文虽高简而时多阙遗，文帝以寿书所载未备，诏松之为之注。","process":"松之总括补阙，承旨注解，采集诸家传记所载，一事而二三异同者并载之以备异闻，注成上之。","impact":"裴注所引书以百数，多得保存亡佚之说；注与正文并传，开纪传体史书补注之体。","figures":["裴松之","刘义隆","陈寿"],"place":"建康（今江苏南京）","state":"南朝宋","sources":["《宋书·裴松之传》","《三国志》裴注"],"tags":["史注","三国志","备异闻"]},"related":["cn--423--p01"]},

  {"id":"cn--430--m01","track":"cn","year":430,"yearApprox":false,"dim":"military","weight":3,"title":"赫连勃勃都统万城","summary":"于黑水之阳筑城而都之，蒸土以筑其壁","detail":{"background":"勃勃依没弈干、附后秦而自为，破薛干部，收铁弗旧众，据有河曲之北。","process":"真兴之际，于黑水之南、马领之阳筑城，徙其众以实之，号曰统万，即其地而都之；以蒸土筑壁，其坚可以砺刀。","impact":"夏有赫连氏，为魏之河济上游之患；统万去平城不远，拓跋焘后遂乘虚而破之。","figures":["赫连勃勃","拓跋珪"],"place":"统万城（今陕西靖边北白城子）","state":"胡夏","sources":["《晋书·赫连勃勃载记》","《魏书·世祖纪》"],"tags":["胡夏","统万","蒸土筑城"]},"related":["cn--391--m01", "cn--439--m01"]},

  {"id":"cn--439--m01","track":"cn","year":439,"yearApprox":false,"dim":"military","weight":5,"title":"太武帝克姑臧，北凉亡","summary":"以西征之师临姑臧，沮渠牧犍出降","detail":{"background":"蒙逊保河右而数与魏相闻，至牧犍而内难寻起；魏以凉州连岁不修职贡，世祖西讨之。","process":"太延五年，魏帝亲将济河而上，西至姑臧，牧犍出降；收其文武，徙吏民于京师，凉州平。","impact":"十六国在北方之割据至此而尽，北魏统一黄河南北之局成，南北对峙遂定。","figures":["拓跋焘","沮渠牧犍"],"place":"姑臧（今甘肃武威）","state":"北魏","sources":["《魏书·世祖纪》","《魏书·沮渠蒙逊传》"],"tags":["北凉","统一北方","徙民"]},"related":["cn--376--p01", "cn--446--c01"]},

  {"id":"cn--443--c01","track":"cn","year":443,"yearApprox":true,"dim":"culture","weight":4,"title":"临川王义庆集撰《世说》","summary":"撰汉晋以来名士言行，区以别为三十六门","detail":{"background":"江左以清言相高，自裴启《语林》、郭澄之《名语》之书行，而识者病其多不实。","process":"元嘉之际，义庆以宗室镇荆州，招集文士，鲍照、何长瑜之伦并在其幕；撰后汉以至东晋名士言行，分门三十八篇，世谓之《世说》。","impact":"士风玄谈赖此得存，梁刘孝标为之注，所引多后世亡书；一卷之间，江左人物如见。","figures":["刘义庆","鲍照","何长瑜"],"place":"江陵、建康（今湖北荆州、江苏南京）","state":"南朝宋","sources":["《世说新语》","《宋书·刘义庆传》"],"tags":["世说","玄言","士族言行"]},"related":["cn--353--a01"]},

  {"id":"cn--446--c01","track":"cn","year":446,"yearApprox":false,"dim":"culture","weight":4,"title":"太武帝禁断佛教，诸州坑沙门","summary":"崔浩之赞与盖吴之案，遂及寺像","detail":{"background":"魏自太宗以来僧徒渐众，寺塔田产侵民，沙门有司不相摄；世祖颇闻其失，司徒崔浩恶之。","process":"太平真君七年，长安行者案及佛寺，得兵弓矢及酿酒财富之属，世祖怒，诏诸有佛图形像及胡经尽击破焚烧，沙门无少长悉坑之；太子晃奉佛，每存救之。","impact":"北方寺院经像一时焚荡，魏世佛教中绝；文成即位而复行，沙门昙曜因是有武州山凿窟之请。","figures":["拓跋焘","崔浩","昙曜"],"place":"平城及诸州郡（今山西大同一带）","state":"北魏","sources":["《魏书·释老志》"],"tags":["灭佛","寺院","沙门"]},"related":["cn--460--a01", "cn--574--c01"]},

  {"id":"cn--450--m01","track":"cn","year":450,"yearApprox":false,"dim":"military","weight":3,"title":"元嘉北伐败，魏军至瓜步","summary":"王玄谟顿滑台不克，魏人南渡淮而北","detail":{"background":"文帝以北魏有主丧之隙，欲复河南之镇；沈庆之以为不可，争之不能得。","process":"元嘉二十七年，王玄谟北趋滑台，顿兵不克；魏帝自将救之，玄谟退，魏师乘胜南下，缘江诸郡大被钞略，至瓜步而饮江。","impact":"北伐之资一败涂地；元嘉之政自此而衰，江北郡县残破，宋人守淮而已。","figures":["刘义隆","王玄谟","拓跋焘","沈庆之"],"place":"滑台、瓜步（今河南滑县、江苏六合南）","state":"南朝宋","sources":["《宋书·文帝纪》","《宋书·索虏传》"],"tags":["元嘉北伐","瓜步","淮北残破"]},"related":["cn--439--m01", "cn--453--p01"]},

  {"id":"cn--452--p01","track":"cn","year":452,"yearApprox":false,"dim":"politics","weight":3,"title":"太武帝为宗爱所弑","summary":"中常侍惧罪行弑，一岁之间再易君","detail":{"background":"世祖末年刑罚无常，中常侍宗爱以佞幸用事，既谮杀皇太子晃，惧祸及，遂为变。","process":"正平二年，宗爱弑世祖，立南安王余；余忌爱之专，爱又弑之；侍中陆丽等定策迎立文成帝濬，爱遂伏诛。","impact":"数月之间大统三易，权出近习；文成立而寺塔复兴，有武州山五窟之凿。","figures":["拓跋焘","宗爱","拓跋余","陆丽"],"place":"平城（今山西大同东北）","state":"北魏","sources":["《魏书·世祖纪》","《魏书·宗爱传》"],"tags":["弑逆","近习","平城"]},"related":["cn--450--m01", "cn--460--a01"]},
  {"id":"cn--453--p01","track":"cn","year":453,"yearApprox":false,"dim":"politics","weight":3,"title":"太子劭弑文帝于永福省","summary":"元凶行弑而自立，武陵王宣讨寻阳","detail":{"background":"文帝欲行废立，密事久泄；太子劭与始兴王濬同谋，东宫之兵夜入殿省。","process":"元嘉三十年二月，劭与濬率东宫兵入，弑文帝，矫太后令自立；武陵王骏宣讨于寻阳，沈庆之、柳元景诸军并进。","impact":"建康再经兵火，劭败死而濬并诛；元嘉之政自北伐一败之后，至此两乱。","figures":["刘劭","刘濬","刘骏","沈庆之"],"place":"建康（今江苏南京）","state":"南朝宋","sources":["《宋书·文帝纪》","《宋书·元凶劭传》"],"tags":["弑逆","元嘉","讨伐"]},"related":["cn--450--m01", "cn--464--p01"]},

  {"id":"cn--460--a01","track":"cn","year":460,"yearApprox":false,"dim":"art","weight":3,"title":"沙门昙曜奏凿武州山石窟","summary":"和平初于京城西武州塞开窟五所","detail":{"background":"太武之世，北方寺像焚荡略尽；文成即位，复听沙门行道，州郡塔庙寻亦重营。","process":"和平初，沙门昙曜奏于京城西武州塞凿山石壁，开窟五所，各镌一佛，记载高者七十余尺；自是相承续凿，历数十年而功未已。","impact":"云冈由是为北朝造像之宗，其像制窟形东渐于洛阳，南被邺、晋；太武禁法之迹至是尽泯。","figures":["昙曜","拓跋濬"],"place":"武州山（今山西大同西云冈）","state":"北魏","sources":["《魏书·释老志》"],"tags":["云冈","石窟","北朝造像"]},"related":["cn--366--a01", "cn--446--c01"]},

  {"id":"cn--462--s01","track":"cn","year":462,"yearApprox":false,"dim":"science","weight":4,"title":"祖冲之上《大明历》","summary":"取岁差立算法，历成而朝议未决","detail":{"background":"宋元嘉历行之既久，朔气渐失其节；虞喜立岁差之说而历家未用；冲之以博学知名，历算机械无所不综。","process":"大明六年，冲之上新历，取五十年差一度之说立岁差之法，又定交月迟疾之数；朝议是非不决，会明帝崩而事寝，至天监中年其历始行。","impact":"岁差自是入历，治历者不复以天度为无差；其以算学求圆理之说，则具见《隋书·律历志》。","figures":["祖冲之","戴法兴"],"place":"建康（今江苏南京）","state":"南朝宋","sources":["《南史·祖冲之传》","《隋书·律历志》"],"tags":["大明历","岁差","历法"]},"related":["cn--330--s01", "cn--263--s01"]},

  {"id":"cn--464--p01","track":"cn","year":464,"yearApprox":false,"dim":"politics","weight":3,"title":"寿寂之弑前废帝，立明帝","summary":"景和之乱一起，湘东王以幼枝入承","detail":{"background":"前废帝以讨劭之功嗣位，年少凶悖，诛戮大臣，诸王在殿内供其戏弄。","process":"景和元年十一月，寿寂之等乘隙弑之；袁顗、褚渊迎立湘东王彧，是为明帝，改元泰始。","impact":"主相之势愈轻，太宗以疏枝入立而猜忌近属，宋之藩屏自此渐尽。","figures":["刘子业","刘彧","寿寂之","褚渊"],"place":"建康（今江苏南京）","state":"南朝宋","sources":["《宋书·前废帝纪》","《宋书·明帝纪》"],"tags":["宫变","景和","南朝宋"]},"related":["cn--453--p01", "cn--466--p01"]},

  {"id":"cn--466--p01","track":"cn","year":466,"yearApprox":false,"dim":"politics","weight":3,"title":"明帝诛除宗藩，宋室遂微","summary":"休范、休祐之属以次见杀，刘氏枝叶尽矣","detail":{"background":"明帝以疏支入立，猜防诸王；桂阳王休范以近属见任而心不自安，晋安、寻阳之兵寻起。","process":"泰始之际，休范以罪见杀，建安、寻阳诸王相继殂殒，孝武之子多不得其死；朝廷左右无复宗藩之助，唯委事台省与近习。","impact":"宋室枝叶既尽，寒人典掌机要，外任专在方镇；萧道成乘是而起，顺帝之世已无宗籍之卫。","figures":["刘彧","刘休范","刘景素","阮佃夫"],"place":"建康（今江苏南京）","state":"南朝宋","sources":["《宋书·明帝纪》","《宋书·桂阳王休范传》"],"tags":["宗室","寒人掌机要","南朝宋"]},"related":["cn--464--p01", "cn--479--p01"]},

  {"id":"cn--479--p01","track":"cn","year":479,"yearApprox":false,"dim":"politics","weight":4,"title":"顺帝逊位，萧道成建国号齐","summary":"道成以淮泗之功入总朝政，四月受禅","detail":{"background":"淮阴之守、寻阳之平，萧道成皆有功，拥兵东府，位望日重；后主幼弱，江祚遂移。","process":"升明之际，道成入总万机，进封齐公，备九锡；建元元年四月受宋禅即皇帝位，国号大齐。","impact":"宋亡而齐承之，南朝更代之速自此率二十余年而一易；江左兵权长在上游与北府。","figures":["萧道成","刘准","袁粲","褚渊"],"place":"建康（今江苏南京）","state":"南朝齐","sources":["《南齐书·高帝纪》","《宋书·顺帝纪》"],"tags":["禅代","南朝齐","淮泗"]},"related":["cn--466--p01", "cn--420--p01"]},

  {"id":"cn--482--c01","track":"cn","year":482,"yearApprox":false,"dim":"culture","weight":3,"title":"顾欢注《道德经》立羲皇之旨","summary":"以玄理释五千文，南齐朝廷遂有郑卫之辨","detail":{"background":"欢字景怡，吴郡盐官人，早从东林诸僧受业，晚居县之山，聚徒教授；世祖诏征不就。","process":"欢以王弼、何晏之说行而老旨遂杂，乃注《道德经》，立羲皇上人之义；又著《夷夏论》，以道释两门为殊途。","impact":"《夷夏论》出而明僧翔、谢镇之之伦叠与往复，释道之争至是为南朝一议题。","figures":["顾欢","明僧翔","谢镇之","萧赜"],"place":"县、吴郡（今浙江嵊州、江苏苏州一带）","state":"南朝齐","sources":["《南齐书·顾欢传》","《弘明集》"],"tags":["夷夏论","道德经注","释道之争"]},"related":[]},

  {"id":"cn--484--i01","track":"cn","year":484,"yearApprox":false,"dim":"institution","weight":3,"title":"北魏始班百官之禄","summary":"太和八年准官取禄，脏满一匹者死","detail":{"background":"北魏自国初以来百官无禄，以兵赏与货卖为资；牧守之任，多肆贪夺，民不堪命。","process":"太和八年，准官得依郡县常调之外增益为禄，始班百官之禄；其旧无禄之世，赃满一匹者死之令亦寻加重。","impact":"吏治自此有俸可守，牧守之贪少戢；均田、三长之令皆得而行。","figures":["元宏","高祐","李冲"],"place":"平城（今山西大同东北）","state":"北魏","sources":["《魏书·高祖纪》","《魏书·食货志》"],"tags":["班禄","吏治","太和改制"]},"related":["cn--485--i01", "cn--486--i01"]},

  {"id":"cn--485--i01","track":"cn","year":485,"yearApprox":false,"dim":"institution","weight":5,"title":"北魏始受田，均田之制立","summary":"太和九年诏受民田，课以桑麻奴婢耕牛","detail":{"background":"代北以来民多流亡，豪强占山护泽，编户日减；李安世请限田，高祖从之。","process":"太和九年，下诏分受天下民田：诸男夫十五以上受露田四十亩，妇人二十亩，奴婢依良，牛一具受田三十亩，有桑之地别课桑田。","impact":"受田之制自此为北朝、隋、唐所沿用，课调与府兵皆以其上立；编户渐复而荒田得辟。","figures":["元宏","李安世","李冲"],"place":"平城（今山西大同东北）","state":"北魏","sources":["《魏书·食货志》","《魏书·高祖纪》"],"tags":["均田","授田","北朝土地"]},"related":["cn--533--s01"]},

  {"id":"cn--486--i01","track":"cn","year":486,"yearApprox":false,"dim":"institution","weight":4,"title":"北魏立邻党乡三长，行新租调","summary":"太和十年置三长，检括户口而改课调","detail":{"background":"旧制民间立宗主督护，多隐冒之弊，三五十家始共一使；州郡藉口，赋税不均。","process":"太和十年，初置邻长、里长、党长，五家为邻，五邻为里，五里为党，检校户口；省旧租调而更定新式，九品之家各以差降。","impact":"豪强隐冒始可得而括，州郡之政行于村里；唐之乡里与里正之制即其遗也。","figures":["元宏","李冲","游明根"],"place":"平城（今山西大同东北）","state":"北魏","sources":["《魏书·李冲传》","《魏书·食货志》"],"tags":["三长制","租调制","户口"]},"related":["cn--484--i01", "cn--485--i01"]},
  {"id":"cn--493--p01","track":"cn","year":493,"yearApprox":false,"dim":"politics","weight":3,"title":"魏主假南伐以定迁都之谋","summary":"讲武之诏既下，六军南出而留者不能止","detail":{"background":"平城地在塞下，漕运不通，每有水旱，民多饥乏；代乡旧族恋其本土，鲜有迁志，穆罴、陆叡之徒迭有谏阻。","process":"太和十七年七月讲武于平城之南，八月车驾发京师，帝戎服执鞭冒雨而出，群臣于马前请停南伐；帝曰不南伐即当迁都，欲以众定之，十月至洛阳。","impact":"迁都之议由是而定，代迁之人相属于道；改服语、定姓族诸令皆张本于此。","figures":["元宏","任城王澄","李冲","穆罴"],"place":"平城、洛阳（今山西大同东北、河南洛阳东）","state":"北魏","sources":["《魏书·高祖纪》","《魏书·任城王澄传》"],"tags":["迁都","南伐","平城"]},"related":["cn--398--p01", "cn--494--p01"]},

  {"id":"cn--494--p01","track":"cn","year":494,"yearApprox":false,"dim":"politics","weight":5,"title":"北魏徙都洛阳","summary":"以太和十八年为定，代迁之人与营构之制并行","detail":{"background":"洛阳自晋末屡经兵火，宫室为墟，而地当天下之中，水陆之会，华夏旧都也；平城之民犹守其落。","process":"太和十八年，帝北还平城，亲喻留台百官以迁洛之意，任城王澄、李冲分任其劳；代迁之人相继而南，其不从者寻有穆泰、陆叡之谋而就诛。","impact":"北魏都洛垂四十年，衣冠鳞集，礼乐营造之业大兴；而六镇代迁之隙，遂为后日之乱。","figures":["元宏","李冲","穆泰","陆叡"],"place":"洛阳（今河南洛阳东）","state":"北魏","sources":["《魏书·高祖纪》","《魏书·李冲传》"],"tags":["迁都洛阳","代迁","六镇"]},"related":["cn--493--p01", "cn--495--i01"]},

  {"id":"cn--495--i01","track":"cn","year":495,"yearApprox":false,"dim":"institution","weight":4,"title":"诏断北语，一从正音","summary":"朝堂之语限以雅言，故违者加于降削","detail":{"background":"代迁之人布在洛邑，国语北俗相承，婚宦之间华鲜杂糅；帝欲一之，乃先正其言语衣服。","process":"太和十九年，帝引见朝臣于明阳堂，诏不得为北语，一从正音；年三十已下见朝者不许故违，三十已上素习者一任不改，违者当加降削。又禁缯彩为夹领小袖之衣。","impact":"北语北服既禁，代人之在洛者渐与士流同风；姓族门第之格亦由是而议。","figures":["元宏","彭城王勰"],"place":"洛阳（今河南洛阳东）","state":"北魏","sources":["《魏书·高祖纪》"],"tags":["雅言","服制","太和改制"]},"related":["cn--494--p01", "cn--496--p01"]},

  {"id":"cn--496--p01","track":"cn","year":496,"yearApprox":false,"dim":"politics","weight":3,"title":"魏改国姓为元，定族姓之格","summary":"从驾迁洛者列为勋宗，姓族与士庶之分始齐","detail":{"background":"代北诸姓随魏而南，其初以部落为次，与中原郡望不相校；帝既正其言语衣服，乃欲齐其门第。","process":"太和二十年，改拓跋氏为元氏，并改代北诸姓；又诏刊定勋贤族姓，与中原之甲门相准，司州之人为天下第首。","impact":"代北之姓既附华夏之谱，鲜卑贵戚之门第由是而定；隋唐所谓关陇郡望之分，其端在此。","figures":["元宏","宋弁"],"place":"洛阳（今河南洛阳东）","state":"北魏","sources":["《魏书·官氏志》","《魏书·高祖纪》"],"tags":["改姓","族姓","门第"]},"related":["cn--495--i01", "cn--494--p01"]},

  {"id":"cn--501--c01","track":"cn","year":501,"yearApprox":true,"dim":"culture","weight":4,"title":"刘勰成《文心雕龙》","summary":"勒为五十篇，自原道以迄书记","detail":{"background":"勰家贫不婚，依沙门僧祐居建康定林寺十余年，遂博通经论；齐末文体渐讹，莫或能正。","process":"乃撰《文心雕龙》，上篇论文之枢纽，下篇叙文体之流别，勒成五十篇，又为序志以明其指；以贫贱无自取誉，候沈约于车前而要之，约深以为得。","impact":"文之原流体制，得此书而有统纪；齐梁以后言文体者必称焉。","figures":["刘勰","僧祐","沈约"],"place":"建康（今江苏南京）","state":"南朝齐","sources":["《梁书·刘勰传》","《文心雕龙·序志》"],"tags":["文论","文体","齐梁"]},"related":["cn--443--c01", "cn--530--c01"]},

  {"id":"cn--502--p01","track":"cn","year":502,"yearApprox":false,"dim":"politics","weight":3,"title":"和帝逊位，萧衍建国号梁","summary":"雍州之兵东下，未期年而受禅","detail":{"background":"东昏之世诛戮不恒，江、益之藩皆不自保；衍以雍州据上游，与荆州合谋而兵起，襄汉随之而定。","process":"中兴二年，衍入建康总摄万机，追废东昏；四月受齐禅即皇帝位，国号大梁，改元天监。","impact":"齐亡而梁承之，在位四十余年；江南之盛与侯景之祸，皆在其世。","figures":["萧衍","萧颖胄","萧宝融"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·武帝纪》","《南齐书·和帝纪》"],"tags":["禅代","南朝梁","雍州"]},"related":["cn--479--p01", "cn--548--p01"]},

  {"id":"cn--504--c01","track":"cn","year":504,"yearApprox":false,"dim":"culture","weight":3,"title":"范缜著《神灭论》","summary":"以形质神用为言，若刀刃之与利","detail":{"background":"梁武崇饰释典，缜独非之，著论以明其意；贵游之徒共加诘难而莫能屈。","process":"缜以为神即形也，形即神也，形存则神存，形谢则神灭；以刃之与利为喻，未闻刃没而利存，岂容形亡而神在。","impact":"天监六年，帝以其论示王公朝贵，往复者六十余人而缜不能改；形神之辨遂为南朝一议题。","figures":["范缜","萧衍"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·范缜传》","《弘明集》"],"tags":["神灭论","形神之辨","佛理之争"]},"related":["cn--482--c01", "cn--527--c01"]},

  {"id":"cn--507--m01","track":"cn","year":507,"yearApprox":false,"dim":"military","weight":3,"title":"邵阳洲之役，寿春入梁","summary":"淮水盛涨，魏师大溃，淮南之地尽焉","detail":{"background":"寿春为淮南之会，得之者可以制江、淮；魏人围义阳，梁人救之，淮上诸戍相承用兵。","process":"天监六年，梁将昌义之等取寿春，魏中山王元英以大众救之，军于邵阳洲，夹淮而阵；会淮水盛长，魏师大溃，英脱身而走。","impact":"寿春入于梁而淮南尽焉；正始以后，梁人屡出而魏人守其北。","figures":["元英","昌义之","萧衍"],"place":"邵阳洲、寿春（今安徽凤台、寿县）","state":"南朝梁","sources":["《梁书·昌义之传》","《魏书·中山王英传》"],"tags":["淮西","寿春","南北朝战争"]},"related":["cn--450--m01"]},

  {"id":"cn--516--a01","track":"cn","year":516,"yearApprox":true,"dim":"art","weight":3,"title":"洛阳永宁寺九层浮图成","summary":"佛殿之制拟于太极，九级出于云表","detail":{"background":"迁洛之后佛法复盛，王公舍第为寺，都下塔庙以百数；灵太后欲崇其制。","process":"熙平之初创永宁寺于宫之西，佛殿拟于太极，中起九层之浮图，记载去地千尺，金盘照于云表，去京师百里已遥见之；正光中忽起火灾，帝御殿瞻之而叹。","impact":"永宁一塔为六朝土木之极，而焚于未几；《洛阳伽蓝记》所纪之盛，即自此寺发之。","figures":["灵太后","元诩"],"place":"洛阳永宁寺（今河南洛阳东）","state":"北魏","sources":["《洛阳伽蓝记》","《魏书·释老志》"],"tags":["永宁寺","浮图","北朝佛教"]},"related":["cn--446--c01", "cn--460--a01"]},

  {"id":"cn--520--x01","track":"cn","year":520,"yearApprox":true,"dim":"explore","weight":4,"title":"郦道元注《水经》","summary":"因水证地，并记川源、郡县与故老传闻","detail":{"background":"《水经》记诸水所由而文多疏略；魏晋以来郡县迁徙，旧名与今地往往不相值。","process":"道元以《水经》为基而广之，自津渠溪谷缘流讨源，条记其所径过，兼载故迹、碑版、歌谣；其所未至者，则访于行人而阙其所疑。","impact":"《水经注》四十卷，后世言水道、郡望与金石者所不能废；地理之文，六朝莫盛焉。","figures":["郦道元"],"place":"洛阳、邺城一带（今河南、河北）","state":"北魏","sources":["《水经注》","《魏书·郦道元传》"],"tags":["地理","水道","碑刻"]},"related":["cn--268--s01"]},

  {"id":"cn--524--p01","track":"cn","year":524,"yearApprox":false,"dim":"politics","weight":3,"title":"六镇兵民起事，沃野陷","summary":"镇户怨于配隶，怀荒杀将以应沃野","detail":{"background":"六镇之人，旧以镇戍得官；迁洛之后府户日贱，有司比之徒隶，怀荒之民因饥请粮而不得。","process":"正光五年，沃野镇民破六韩拔陵杀守将，自称真王，改元神嘉；诸镇之民相率响应，关陇河北俱乱，魏人不能制。","impact":"北魏之亡实兆于此；尔朱荣、高欢之徒皆因六镇之众而起，河朔自此不复安。","figures":["破六韩拔陵","元诩","李崇"],"place":"沃野、怀荒（今内蒙古乌拉特前旗、河北张北一带）","state":"北魏","sources":["《魏书·肃宗纪》"],"tags":["六镇","镇户","北魏衰亡"]},"related":["cn--494--p01", "cn--528--p01"]},

  {"id":"cn--526--m01","track":"cn","year":526,"yearApprox":false,"dim":"military","weight":3,"title":"葛荣收六镇之众，据殷州","summary":"河北之镇人北走，鲜于余党合而为一","detail":{"background":"六镇既乱，鲜于修礼余党北走；柔玄、怀荒之兵继起，河北之人所在响应。","process":"孝昌之际，葛荣并其众而北，破魏师，杀其将元融，据殷州；自邺以北皆附之，魏之府库兵人在焉。","impact":"河北为魏根本，丧于群盗；寻为尔朱荣所灭，而六镇之众尽入其军。","figures":["葛荣","元融","元诩"],"place":"殷州、邺城一带（今河北隆尧、临漳西）","state":"北魏","sources":["《魏书·肃宗纪》"],"tags":["河北","六镇余众","葛荣"]},"related":["cn--524--p01", "cn--528--p01"]},

  {"id":"cn--527--c01","track":"cn","year":527,"yearApprox":false,"dim":"culture","weight":3,"title":"梁武帝舍身同泰寺","summary":"设无遮大会，御法席而称戒律之子","detail":{"background":"帝自天监以来宗事释典，制断酒肉，讲席之会或自为文；都下寺塔日盛。","process":"大通元年，帝舍身于同泰寺，设无遮大会，自居房室；在寺数日，群臣累表上请，以钱奉赎，乃还宫，大赦改元。其后又再舍身焉。","impact":"人主以身事佛，都下寺塔因是极盛；而郊庙之费岁出于赎，国用稍屈。","figures":["萧衍"],"place":"建康同泰寺（今江苏南京北）","state":"南朝梁","sources":["《梁书·武帝纪》"],"tags":["舍身","同泰寺","佛教"]},"related":["cn--504--c01", "cn--546--m01"]},

  {"id":"cn--528--p01","track":"cn","year":528,"yearApprox":false,"dim":"politics","weight":3,"title":"尔朱荣立庄帝，杀朝士于河阴","summary":"陶渎伏甲，王公已下以千数被害","detail":{"background":"灵太后临朝，佞幸用事，二九月之间帝暴崩而幼主立；太原王尔朱荣以胡骑南向，河北之众随之。","process":"武泰元年四月，荣奉立庄帝，伏甲于河阴之陶渎，因朝士毕集，尽杀公卿已下，记载死者二千余人；高阳王雍、李彦之徒俱遇祸，帝为之避正殿。","impact":"洛阳衣冠横戮略尽，尔朱荣以柱国之重内挟天子；迁洛以来之盛，至是大坏。","figures":["尔朱荣","元子攸","元雍"],"place":"河阴陶渚（今河南孟津东）","state":"北魏","sources":["《洛阳伽蓝记》","《魏书·尔朱荣传》"],"tags":["河阴之变","尔朱","朝士"]},"related":["cn--526--m01", "cn--534--p01"]},

  {"id":"cn--530--c01","track":"cn","year":530,"yearApprox":true,"dim":"culture","weight":4,"title":"昭明太子等撰《文选》","summary":"集姬汉以来之文，区以别为三十八体","detail":{"background":"统以嫡嗣居东宫，爱士好辞，引刘孝绰、王筠、殷芸之伦以为左右；自汉以来辞赋日滋，旧有总聚之选而未尽。","process":"乃即所集文簿，撰其遗事，上起周代，下隔梁初，凡次序数十百家，勒成三十卷，以赋诗骚铭诔为目，区以别之；孝绰实与其议。","impact":"《文选》行而「文选之学」为后世专门，唐人士业此文，宋代犹称「文选烂，秀才半」;文章之统纪，自兹益章。","figures":["萧统","刘孝绰","王筠"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·昭明太子传》","《文选》"],"tags":["文选","总集","文章体制"]},"related":["cn--501--c01"]},

  {"id":"cn--531--p01","track":"cn","year":531,"yearApprox":false,"dim":"politics","weight":4,"title":"高欢起兵于信都","summary":"收六镇余众据冀州，与尔朱氏争魏政","detail":{"background":"六镇起事后，尔朱荣以河阴之戮专魏政；高欢起于怀朔镇，为荣所抚，领镇兵。荣寻为庄帝所杀，欢以镇众请讨之。","process":"普泰元年，欢自滏口西讨尔朱兆，次邺，以河北之众不可久留，遂起兵于信都，收河北之众，与尔朱氏相持；寻与诸将议立元朗为帝，改元天成。","impact":"河北自此别为一局；欢以六镇之众立国之基，二年之内遂有魏政，南北朝之分裂由是而深。","figures":["高欢","尔朱兆","元朗"],"place":"信都（今河北冀州）","state":"北魏","sources":["《北齐书·神武纪上》","《资治通鉴》梁纪"],"tags":["六镇余众","信都起兵","北魏分裂"]},"related":["cn--524--p01", "cn--532--m01"]},
  {"id":"cn--531--f01","track":"cn","year":531,"yearApprox":false,"dim":"figure","weight":2,"title":"昭明太子统卒","summary":"东宫引士撰文选，年三十有一","detail":{"background":"统字德施，武帝长子，少敏慧，及长，爱士好辞，引刘孝绰、王筠、殷芸之伦入东宫讲论。","process":"中大通三年四月卒于显阳殿，年三十有一；帝将葬，以所撰文集行于世家。谥曰昭明，赠文帝之礼。","impact":"《文选》之撰出于其东宫一时文士之手；统死而适安王之乱旋起，江左衣冠之盛渐替。","figures":["萧统","萧衍","刘孝绰"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·昭明太子传》","《南史·昭明太子传》"],"tags":["昭明太子","文选学","东宫文士"]},"related":["cn--530--c01", "cn--531--p02"]},
  {"id":"cn--531--p02","track":"cn","year":531,"yearApprox":false,"dim":"politics","weight":2,"title":"晋安王纲立为皇太子","summary":"昭明既殂，次立太子，东宫之宠复盛","detail":{"background":"昭明太子既殁，武帝以次子晋安王纲次当嫡嗣；寻有夺嫡之议。","process":"中大通三年冬，立纲为皇太子；摛文之士徐摛、庾肩吾之徒并为东宫属，春坊之制大备。","impact":"东宫之文自是益侈，「宫体」之号由此而兴；梁室之治乱亦随之。","figures":["萧纲","萧衍","徐摛"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·简文帝纪》","《南史·简文帝纪》"],"tags":["皇太子","宫体","梁室"]},"related":["cn--531--f01", "cn--549--p01"]},
  {"id":"cn--531--m01","track":"cn","year":531,"yearApprox":false,"dim":"military","weight":2,"title":"侯渊破韩楼于蓟城","summary":"六镇余众入幽州，尔朱氏寻定河北","detail":{"background":"葛荣死，其党韩楼复收余众据蓟城；幽、燕之间镇人蜂起，魏之北境不守。","process":"尔朱荣遣侯渊为幽州刺史，率骑数百驰入其地，张设疑兵以诱斩韩楼，蓟城之众遂散，河北底定。","impact":"六镇余部至是略尽；而河朔之民离散既久，高欢得之以为兵本，幽、冀自此不复为魏有。","figures":["侯渊","韩楼","尔朱荣"],"place":"蓟城（今北京西南）","state":"北魏","sources":["《资治通鉴》梁纪","《北史·侯渊传》"],"tags":["六镇余波","河北","幽州"]},"related":["cn--526--m01", "cn--531--p01"]},
  {"id":"cn--531--e01","track":"cn","year":531,"yearApprox":false,"dim":"economy","weight":2,"title":"梁省天下田租税丁","summary":"以岁俭诏省田租，江左之赋暂宽","detail":{"background":"梁自天监用兵以后，国用仰于租调；普通末岁不登，民多流冗。","process":"中大通三年以岁俭诏天下省田租之半，又弛关市之征；江左之赋由是暂宽。","impact":"江左赋役本轻，梁末复省其租；然侯景乱起，二宫焚毁，吴会之业遂耗。","figures":["萧衍"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·武帝纪中》","《资治通鉴》梁纪"],"tags":["田租","复除","江左赋役"]},"related":["cn--527--c01"]},
  {"id":"cn--532--m01","track":"cn","year":532,"yearApprox":false,"dim":"military","weight":3,"title":"韩陵之战，尔朱氏亡","summary":"欢以少众背洹水而陈，合击破尔朱兆","detail":{"background":"高欢起兵后，尔朱兆、尔朱世隆等内相疑贰；欢以妹妻兆而阴图之，兆遂与欢绝。","process":"普泰二年二月，欢进至邺南之韩陵，背洹水而陈；以羸兵饵其锋，伏骑于左右，合击大破之，尔朱兆西走，寻为所擒，尔朱氏之党尽。","impact":"魏政尽归高氏，洛阳徒有空名；明年而关陇别立一主，两都之局遂成。","figures":["高欢","尔朱兆","段荣"],"place":"韩陵（今河南安阳东北）","state":"北魏","sources":["《北齐书·神武纪上》","《资治通鉴》梁纪"],"tags":["韩陵","尔朱氏","河北"]},"related":["cn--531--p01", "cn--534--p01"]},
  {"id":"cn--533--s01","track":"cn","year":533,"yearApprox":true,"dim":"science","weight":3,"title":"贾思勰撰《齐民要术》","summary":"起耕稼迄酒豉，采捃经传，爱及歌谣","detail":{"background":"后魏以来，代北之民南徙，河朔耕法与中土旧术相杂；《要术》旧题高阳太守贾思勰撰，其爵里史无明文。","process":"乃采捃经传，爰及歌谣，询之老成，验之行事；起自耕农，终于醯醢，资生之目靡不毕载，凡九十二篇，勒为十卷。","impact":"《齐民要术》为今存最早而最完之农书；后魏以来北方耕织、畜牧、酿造之法赖以不尽失，北朝民事于此见其崖略。","figures":["贾思勰"],"place":"高阳（今河北蠡县一带）","state":"北魏、东魏","sources":["《齐民要术·自序》","《四库全书总目提要》"],"tags":["农书","齐民要术","代北耕稼"]},"related":["cn--485--i01", "cn--520--x01", "cn--541--i01"]},
  {"id":"cn--534--p01","track":"cn","year":534,"yearApprox":false,"dim":"politics","weight":5,"title":"孝武帝西奔，北魏遂分","summary":"帝自洛阳西入关，高欢别立宗子于河北","detail":{"background":"帝既擢用关陇之豪以抗高欢，欢遂举兵向京师；帝所恃者独宇文泰一军而已。","process":"永熙三年夏，欢举兵向京师，帝西出关，高欢追之不及；寻至长安，欢遂入洛阳，宫室残毁，还于邺。","impact":"元魏之统自此中分，长安与晋阳各立一宗；北朝之分竞历四十余年而隋兴焉。","figures":["元修","高欢","宇文泰"],"place":"洛阳至长安（今河南、陕西）","state":"北魏","sources":["《魏书·孝武帝纪》","《北史·魏本纪》","《资治通鉴》梁纪"],"tags":["永熙入关","北魏分裂","两都"]},"related":["cn--528--p01", "cn--535--p01", "cn--534--p02"]},
  {"id":"cn--534--p02","track":"cn","year":534,"yearApprox":false,"dim":"politics","weight":3,"title":"东魏孝静帝立于襄国","summary":"高欢别立元善见，改元天平","detail":{"background":"孝武既入关，高欢以宗子幼者宜所立，众议未决。","process":"永熙三年十月立元善见，时止十岁，改元天平，是为孝静帝；欢自为大丞相，居晋阳以督山东之众。","impact":"东魏自是帝常拱手，相权出于别宫；十有六年而齐代魏，其制皆因欢之旧。","figures":["元善见","高欢","司马子如"],"place":"襄国（今河北邢台）","state":"东魏","sources":["《魏书·孝静帝纪》","《北史·齐本纪》"],"tags":["东魏","孝静帝","晋阳"]},"related":["cn--534--p01", "cn--535--p02"]},
  {"id":"cn--534--d01","track":"cn","year":534,"yearApprox":false,"dim":"disaster","weight":2,"title":"永宁寺浮图灾","summary":"火起九层，三月熄而永熙之乱继之","detail":{"background":"永宁寺塔成于熙平，金盘照云；孝庄、节闵之间兵革屡及都下。","process":"永熙三年二月夜塔上忽起火，巢鹊惊飞，烟火之声闻于数十里，经像房柱一时俱尽。","impact":"洛阳佛寺之盛尽于此一炬；未几而帝西奔、都东徙，故墟行旅，至《伽蓝记》所叙已为丘墟。","figures":["元修"],"place":"洛阳永宁寺（今河南洛阳东）","state":"北魏","sources":["《洛阳伽蓝记》","《魏书·灵征志》"],"tags":["火灾","永宁寺","洛阳残毁"]},"related":["cn--516--a01", "cn--534--p01"]},
  {"id":"cn--535--p01","track":"cn","year":535,"yearApprox":false,"dim":"politics","weight":3,"title":"西魏文帝即位长安","summary":"宇文泰酖孝武而立南阳王，改元大统","detail":{"background":"孝武入关后与宇文泰嫌隙日深，泰每事多所裁抑。","process":"永熙三年十二月泰宴于城西，帝暴崩，世遂以为酖；泰迎立南阳王宝炬，是为文帝，改元大统，都长安。","impact":"西魏与东魏并立之局始定；元氏徒有空名，而泰以柱国辅政，关陇之制从此创。","figures":["元宝炬","宇文泰","元修"],"place":"长安（今陕西西安西北）","state":"西魏","sources":["《周书·文帝纪上》","《北史·魏本纪》"],"tags":["西魏","大统","宇文泰"]},"related":["cn--534--p01", "cn--535--p02"]},
  {"id":"cn--535--c01","track":"cn","year":535,"yearApprox":true,"dim":"culture","weight":3,"title":"菩提流支《十地经论》译成","summary":"永平以来译部帙既成，地论之学遂北盛","detail":{"background":"北魏自宣武以后佛法复炽，西域三藏相继至洛；永宁寺成，遂开译馆。","process":"菩提流支于洛阳译《十地经论》等部，自永平迄于孝昌部帙始备，旋随僧众东迁于邺，译事不辍。","impact":"《十地》之学盛于邺、晋，判为南道、北道两家；后之净影、地论诸师悉由此出，北朝义学自是不专在江左。","figures":["菩提流支"],"place":"洛阳、邺城（今河南、河北）","state":"北魏","sources":["《历代三宝纪》","《续高僧传》"],"tags":["译经","地论","北朝佛教"]},"related":["cn--460--a01", "cn--538--c01"]},
  {"id":"cn--535--p02","track":"cn","year":535,"yearApprox":false,"dim":"politics","weight":2,"title":"吐谷浑夸吕立","summary":"西州远可汗再称于青海，数寇西境","detail":{"background":"伏连筹既死，其子夸吕立，始自署为大可汗，置百官，仿中国之号。","process":"西魏文帝大统初夸吕继位，都伏俟城于青海之西；后数寇西、鄯二州，杀凉州刺史长史，凉州道阻。","impact":"吐谷浑自是时与魏周称寇，通使于北齐、萧梁；青海一道遂为南北朝与西域之间枢纽。","figures":["夸吕"],"place":"伏俟城（青海湖西恰不钦一带）","state":"吐谷浑","sources":["《周书·吐谷浑传》","《北史·吐谷浑传》"],"tags":["吐谷浑","青海","羌中道"]},"related":["cn--439--m01"]},
  {"id":"cn--536--f01","track":"cn","year":536,"yearApprox":false,"dim":"figure","weight":2,"title":"陶弘景卒于山中","summary":"历六朝而不仕，书问常以岭间为报","detail":{"background":"弘景字通明，丹阳秣陵人，宋末解褐奉朝请，齐永明中挂神武门冠，往句曲山立馆修道。","process":"梁天监以后尝再征不出；朝廷每有凶吉大事，无不咨询，时人目为「山中宰相」。大同二年卒，谥曰贞白先生。","impact":"其上清一派由之传于江东，而本草、历算、炼丹之业皆附以行；六朝隐逸之门遂为后世所宗。","figures":["陶弘景","萧衍"],"place":"句曲山（今江苏句容茅山）","state":"南朝梁","sources":["《梁书·处士传》","《南史·陶弘景传》"],"tags":["茅山","隐逸","本草"]},"related":["cn--482--c01"]},
  {"id":"cn--537--m01","track":"cn","year":537,"yearApprox":false,"dim":"military","weight":3,"title":"沙苑之战，宇文泰以少破高欢","summary":"伏兵于渭曲菱蔓之间，欢师大溃","detail":{"background":"高欢以西魏新取弘农，自晋阳出西河，冯翊而西；宇文泰众不满万，军至沙苑。","process":"大统三年十月，泰用李弼、于谨之计，伏于渭曲，命军士偃于菱、蔓之间，约闻鼓而起；欢军至而泰军横击，大破之。","impact":"高欢之众自是不得轻出关西，西魏立国于长安始固，而泰之名望亦自此成。","figures":["宇文泰","高欢","李弼","于谨"],"place":"沙苑（今陕西大荔南）","state":"西魏、东魏","sources":["《周书·文帝纪下》","《北齐书·神武纪下》","《资治通鉴》梁纪"],"tags":["沙苑","以少击众","东西魏"]},"related":["cn--534--p01", "cn--543--m01"]},
  {"id":"cn--538--c01","track":"cn","year":538,"yearApprox":true,"dim":"culture","weight":2,"title":"地论师慧光讲《十地》于邺","summary":"《十地》之学分南北道，邺下讲席不绝","detail":{"background":"《十地经论》既出，学侣云会；慧光从菩提流支受业，后与道宠各立门户。","process":"东魏天平、元象之间，慧光在邺都讲《十地》《华严》之部，学徒千数；武定中卒于邺。其师资所传，后遂判为南道、北道两家。","impact":"地论南北道之争历北齐、北周而不已；净影慧远出于南道，天台、华严之教皆食其绪余。","figures":["慧光","菩提流支","道宠"],"place":"邺城（今河北临漳西南）","state":"东魏","sources":["《续高僧传》","《历代三宝纪》"],"tags":["地论","邺下义学","南北道"]},"related":["cn--535--c01", "cn--556--c01"]},
  {"id":"cn--539--f01","track":"cn","year":539,"yearApprox":false,"dim":"figure","weight":2,"title":"陈庆之卒","summary":"以七百骑纳元颢入洛，谥曰武","detail":{"background":"庆之字文子，义阳人也，事武帝于潜邸；普通中累破魏军，洛州之役以七百骑纳元颢入洛阳。","process":"大通以后常镇义阳、涡阳之间，前后十数战，未尝挫衄；大同五年卒，谥曰武。","impact":"梁室北方之镇倚庆之为重；及其死而淮上诸戍渐孤，侯景之乱江左无复可用之兵。","figures":["陈庆之","萧衍","元颢"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·陈庆之传》","《南史·陈庆之传》"],"tags":["北伐","义阳","梁之名将"]},"related":["cn--507--m01", "cn--548--m01"]},
  {"id":"cn--541--p01","track":"cn","year":541,"yearApprox":false,"dim":"politics","weight":2,"title":"李贲据交州","summary":"越人乘梁吏失驭，称于六标","detail":{"background":"梁末交州刺史萧咨为政失驭，土人怨之；李贲累世仕于州里。","process":"大同七年贲举兵，州镇不能制；累遣将讨之，贲保屈都、六标之间，置百官、建年号以自立。","impact":"交州自是别为一国，陈、隋之间累讨不服；林邑、盘盘诸国亦因之北争，南海之局遂异于宋、齐以来。","figures":["李贲","萧咨","陈霸先"],"place":"龙编、六标（今越南北宁、河内一带）","state":"梁交州","sources":["《南史·夷貊传》","《陈书·高祖纪》"],"tags":["交州","李贲","岭南"]},"related":["cn--548--m01", "cn--551--p01"]},
  {"id":"cn--541--i01","track":"cn","year":541,"yearApprox":true,"dim":"institution","weight":4,"title":"苏绰奏行六条诏书","summary":"先心后治，劝科养教均讼，牧守非此不任","detail":{"background":"宇文泰以关中土瘠民贫、守令多不称职，深欲以治道整齐军国。","process":"大统初，苏绰草诏以进，凡六条：一曰治心，二曰敦教化，三曰尽地力，四曰擢贤良，五曰恤狱讼，六曰均赋役。泰书置坐右，朝士讽诵焉。","impact":"西魏、北周之治一出六条；唐长孺以为关陇制度之根本在此，隋室承之而开皇之治亦沿其流。","figures":["苏绰","宇文泰"],"place":"长安（今陕西西安西北）","state":"西魏","sources":["《周书·苏绰传》","《资治通鉴》梁纪"],"tags":["六条诏书","关中制度","守令"]},"related":["cn--546--f01", "cn--556--i01"]},
  {"id":"cn--541--d01","track":"cn","year":541,"yearApprox":true,"dim":"disaster","weight":2,"title":"东魏河北大水","summary":"河北数州并灾，州镇城戍多被其害","detail":{"background":"北朝之世河决为灾往往书于史册；定、冀之境漕渠所仰，而水害亦独甚。","process":"天平、兴和之间，河北数州大水，州镇城戍多被其害；有司以工赈之，乃出官粟振其乏。","impact":"河北为东魏、北齐根本，兵赋所出而水旱间作；齐文宣以下常徙其饥民，国本以虚。","figures":["元善见"],"place":"河北数州（今河北中部、南部）","state":"东魏","sources":["《魏书·灵征志》","《魏书·孝静帝纪》"],"tags":["水灾","黄河","北齐河北"]},"related":["cn--524--p01", "cn--550--p01"]},
  {"id":"cn--543--m01","track":"cn","year":543,"yearApprox":false,"dim":"military","weight":2,"title":"邙山之役，宇文泰东讨不克","summary":"泰救金墉，为高欢所乘，丧师而还","detail":{"background":"东魏洛州戍兵与玉壁之守相继入于西魏，高欢自晋阳西临以讨之；宇文泰东出会其众。","process":"大统九年春，泰军至邙山，与欢军相遇；陈未定而欢兵四合，泰师遂败，诸将多陷没者，金墉之戍亦弃而退，崤、陕复震。","impact":"东西魏之强弱至是未分，而河、洛之间遂为百战之地；三年而玉壁之围复起。","figures":["宇文泰","高欢"],"place":"邙山、金墉（今河南洛阳东北）","state":"西魏、东魏","sources":["《周书·文帝纪下》","《北齐书·神武纪下》","《资治通鉴》梁纪"],"tags":["邙山","东西魏相持","金墉"]},"related":["cn--546--m01", "cn--537--m01"]},
  {"id":"cn--546--f01","track":"cn","year":546,"yearApprox":false,"dim":"figure","weight":2,"title":"苏绰卒，宇文泰失其佐","summary":"大统十二年卒，泰哭之而辍食","detail":{"background":"绰字令绰，武功人，少好学，尤长于算；泰与语，卧而听之，自旦达暮。","process":"大统十二年十二月卒，官至度支尚书、司农卿；泰每念其规谏，尝因宴而叹。","impact":"绰为泰定计帐、屯田、六条之制；其死也，关陇制度已立，卢辩续成六官之事。","figures":["苏绰","宇文泰","卢辩"],"place":"长安（今陕西西安西北）","state":"西魏","sources":["《周书·苏绰传》"],"tags":["苏绰","关中制度","大统"]},"related":["cn--541--i01", "cn--556--i01"]},
  {"id":"cn--546--m01","track":"cn","year":546,"yearApprox":false,"dim":"military","weight":3,"title":"玉壁之役，高欢不克而还","summary":"欢起土山、为地道，孝宽随机拒之","detail":{"background":"玉壁本东魏所城，后入于西魏，为崤、陕之蔽；高欢深以为患。","process":"武定四年欢悉众围玉壁，起土山、为地道以攻之；韦孝宽随机拒守，凡六十余日不陷，欢军病死及馁者相属，乃委积而退。","impact":"西魏以是得守崤、陕之固，不复忧河东；高欢归晋阳而发病，明年遂卒。","figures":["高欢","韦孝宽","宇文泰"],"place":"玉壁（今山西稷山西南）","state":"东魏、西魏","sources":["《周书·韦孝宽传》","《北齐书·神武纪下》","《资治通鉴》梁纪"],"tags":["玉壁","城守","东西魏"]},"related":["cn--543--m01", "cn--547--f01"]},
  {"id":"cn--547--f01","track":"cn","year":547,"yearApprox":false,"dim":"figure","weight":3,"title":"高欢卒于晋阳","summary":"玉壁败归而疾，诸子不能制侯景","detail":{"background":"欢自玉壁之败，发疾；以河南侯景跋扈，顾诸子皆幼，惧其后难相制。","process":"武定五年正月卒于晋阳，属事于高澄；秘不发丧，未几而景果叛，欢所虑者遂验。","impact":"欢起于六镇，挟河北之众以立东魏之基；其死也，齐代魏之势已成，而淮南之乱亦由是起。","figures":["高欢","高澄","侯景"],"place":"晋阳（今山西太原西南）","state":"东魏","sources":["《北齐书·神武纪下》","《资治通鉴》梁纪"],"tags":["高欢","晋阳","北齐基业"]},"related":["cn--546--m01", "cn--547--m01"]},
  {"id":"cn--547--m01","track":"cn","year":547,"yearApprox":false,"dim":"military","weight":2,"title":"侯景叛于河南，请援于魏、梁","summary":"颍川一战而景势蹙，遂请内附于江左","detail":{"background":"高欢死，侯景素与高澄不相下，遂据有河南之地，疑惧而反。","process":"武定五年景西请宇文泰之援，东魏遣高敖曹、慕容绍宗讨之，景战于颍川而败，所领余众无几，乃南遣使请于梁。","impact":"梁纳景而河南之地尽入于东魏；江左自此得虚名而招实祸，明年而建康围。","figures":["侯景","高澄","慕容绍宗","萧衍"],"place":"颍川、寿阳（今河南禹州、安徽寿县）","state":"东魏、梁","sources":["《梁书·侯景传》","《北齐书·慕容绍宗传》","《资治通鉴》梁纪"],"tags":["侯景","河南","梁纳叛"]},"related":["cn--548--m01", "cn--539--f01"]},
  {"id":"cn--547--c01","track":"cn","year":547,"yearApprox":true,"dim":"culture","weight":3,"title":"杨衒之撰《洛阳伽蓝记》","summary":"重过洛阳而伤其崩坏，寺塔园苑勒为一书","detail":{"background":"永熙之乱，洛阳宫室、寺塔咸尽；齐神武迁邺而都址东移，旧京遂为丘墟。","process":"武定五年杨衒之重至洛阳，伤其崩坏，乃考其寺塔之由、园苑之旧，勒为《洛阳伽蓝记》五卷；以城中之寺为首，而四郭之第舍、朝士之风流附见焉。","impact":"北都百年之土木、礼乐与人物，赖此书而粗存；自《水经注》之外，北朝地理之文莫盛于衒之，后世考洛阳宫寺者多取资焉。","figures":["杨衒之"],"place":"洛阳（今河南洛阳东）","state":"东魏","sources":["《洛阳伽蓝记》","《四库全书总目提要》"],"tags":["洛阳伽蓝记","都邑记载","北朝地理"]},"related":["cn--534--d01", "cn--516--a01"]},
  {"id":"cn--548--m01","track":"cn","year":548,"yearApprox":false,"dim":"military","weight":5,"title":"侯景举兵反，济江逼建康","summary":"自寿阳南向，缘江诸军皆溃","detail":{"background":"景既失河南之地，梁室无赖，而宗室诸王各怀去就；羊鸦仁守悬瓠，粮运不属。","process":"太清二年八月景反于寿阳，南北朝廷俱不为备；十月济江，缘江诸军望风解散，十一月至建康阙下。","impact":"自建康被围而江左之局大坏：二宫隔绝，方镇各立，吴会之民死者相枕，南朝自此不复与北抗。","figures":["侯景","萧衍","萧正德"],"place":"寿阳至建康（今安徽寿县、江苏南京）","state":"南朝梁","sources":["《梁书·侯景传》","《南史·贼臣传》","《资治通鉴》梁纪"],"tags":["侯景之乱","建康","渡江"]},"related":["cn--547--m01", "cn--549--p01"]},
  {"id":"cn--548--p01","track":"cn","year":548,"yearApprox":false,"dim":"politics","weight":3,"title":"梁室诏内外戒严，诸军入援","summary":"台城仓卒誓守，勤王之师聚而无长","detail":{"background":"景之未济江也，萧正德内应之书屡至；朝议以江防为足恃，都不设备。","process":"及景济江，始下诏内外戒严，大赦以安反侧；诸州镇兵并遣入援，宗室与方镇之师相继集于都下。","impact":"援军虽聚而莫适为主，各保所部以观成败，故围卒不解而台城陷；梁室之亡不在景之强，而在方镇之自为守。","figures":["萧衍","萧纶","萧正德"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·武帝纪下》","《南史·梁本纪中》","《资治通鉴》梁纪"],"tags":["戒严","勤王","台城之围"]},"related":["cn--548--m01", "cn--549--p01"]},
  {"id":"cn--549--p01","track":"cn","year":549,"yearApprox":false,"dim":"politics","weight":4,"title":"台城陷，侯景总览朝政","summary":"援军不进而宫城破，太子死之","detail":{"background":"柳仲礼、萧范等四方之军号数十万，聚于都城之外而互不相下。","process":"太清三年三月台城陷，景入据之，纵兵掠夺；帝犹御正殿见之，寻幽絷于省内，皇太子大器遇害。","impact":"江左中央之权自此旁落，诸王分镇遂成敌国；西魏、北齐因得东下，南朝之地日蹙。","figures":["侯景","萧衍","萧大器","柳仲礼"],"place":"建康台城（今江苏南京北）","state":"南朝梁","sources":["《梁书·简文帝纪》","《南史·贼臣传》","《资治通鉴》梁纪"],"tags":["台城之围","侯景之乱","建康"]},"related":["cn--548--m01", "cn--549--d01"]},
  {"id":"cn--549--d01","track":"cn","year":549,"yearApprox":false,"dim":"disaster","weight":3,"title":"围城之后，都下大饥疫","summary":"内外隔绝数月，饿疫相枕于路","detail":{"background":"自建康受围，漕运不通；都城内外庐舍多毁，时又疾疫。","process":"城中之食既尽，饿殍相接，疫死者相枕藉；及景得志，肆兵攘夺，都下之民存者无几。","impact":"都下之残破自此极矣；侯景乱平而江左衣冠、仓廪与释氏之寺塔同尽，陈室遂以一方自立。","figures":["萧衍","侯景"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·侯景传》","《南史·贼臣传》"],"tags":["饥疫","建康残破","侯景之乱"]},"related":["cn--549--p01", "cn--552--m01"]},
  {"id":"cn--550--p01","track":"cn","year":550,"yearApprox":false,"dim":"politics","weight":4,"title":"齐代魏，文宣帝即位","summary":"高洋受魏禅，国号齐，改元天保","detail":{"background":"高澄嗣其父之业，将受禅而遇膳奴之祸；弟洋代之，居晋阳，威刑自立。","process":"武定八年五月洋受魏禅，国号齐，改元天保，降封孝静帝为中山王；以邺为都，而晋阳为别宫，恒自住之。","impact":"北朝自是齐、周对峙，江左则梁、陈相代；文宣初政励精，河北之治稍理，其后肆暴而齐之乱阶即起。","figures":["高洋","元善见","高澄"],"place":"邺城（今河北临漳西南）","state":"北齐","sources":["《北齐书·文宣帝纪》","《资治通鉴》梁纪"],"tags":["北齐代魏","天保","邺城"]},"related":["cn--534--p02", "cn--577--p01"]},
  {"id":"cn--550--i01","track":"cn","year":550,"yearApprox":true,"dim":"institution","weight":4,"title":"西魏成六柱国、十二大将军之制","summary":"分督诸军，入则宿卫出则临戎","detail":{"background":"宇文泰以关中土寡兵少，六坊之众与从六镇入关之户皆在所藉。","process":"大统中乃督诸军为六师，更为十二大将军以统之，每大将军督二开府，分团统领；其将有功伐、著时望者入为柱国。","impact":"是制也，兵农相参、将位世袭，关陇之豪由是合为一贯；隋室与唐初之门第，多由此出。","figures":["宇文泰","李虎","赵贵","于谨"],"place":"长安（今陕西西安西北）","state":"西魏","sources":["《周书·文帝纪下》","《唐六典》","《北史》"],"tags":["府兵","十二大将军","关陇集团"]},"related":["cn--541--i01", "cn--556--i01"]},
  {"id":"cn--551--p01","track":"cn","year":551,"yearApprox":false,"dim":"politics","weight":3,"title":"侯景弑简文帝","summary":"废为晋安王，寻以酒进而崩","detail":{"background":"景自都督中外、进位相国，封汉王，备九锡；以王僧辩、陈霸先之兵且至，乃谋自代。","process":"大宝二年废帝为晋安王，寻进酒而帝崩；景立武帝曾孙栋，改元天正，寻亦废之而自立，国号汉。","impact":"梁室统绪三绝，江左之望遂在方镇；王、陈由立国之功而代兴，霸先之业本于此。","figures":["侯景","萧纲","萧栋"],"place":"建康（今江苏南京）","state":"南朝梁","sources":["《梁书·简文帝纪》","《南史·贼臣传》","《资治通鉴》梁纪"],"tags":["侯景之乱","弑逆","梁室"]},"related":["cn--549--p01", "cn--552--m01"]},
  {"id":"cn--551--m01","track":"cn","year":551,"yearApprox":false,"dim":"military","weight":2,"title":"百济乘梁乱攻新罗","summary":"获其西鄙城戍，汉水之争夺以起","detail":{"background":"侯景乱起，梁之命爵不通于海东；百济圣王乘新罗之弱北图侵地。","process":"梁室方乱，百济北讨新罗，拔其边城数处，取汉水上游之地；新罗告急于梁而不得救，寻亦反袭百济。","impact":"汉水流域之争夺遂定三国之势：新罗得之而通中国之道开，百济自此日蹙，高句丽益孤。","figures":["百济圣王","真兴王"],"place":"汉水上游（今朝鲜半岛中部）","state":"百济、新罗","sources":["《三国史记》","《周书·异域传下》"],"tags":["百济","新罗","海东"]},"related":["cn--553--p02", "cn--549--p01"]},
  {"id":"cn--552--m01","track":"cn","year":552,"yearApprox":false,"dim":"military","weight":4,"title":"王僧辩、陈霸先平侯景","summary":"二军俱进建康，景走死于胡豆洲","detail":{"background":"景弑逆之后寻自立为汉帝；王僧辩督水军自上江而下，陈霸先率众会之。","process":"大宝三年僧辩、霸先连破景于武昌、湓口之间，进克郢城；其春复建康，景东走，至胡豆洲为乱兵所杀，传首江陵。","impact":"江左之乱暂平，而功在方镇；僧辩、霸先由是分据内外，五年而陈氏代梁，建国之基实定于此。","figures":["王僧辩","陈霸先","侯景"],"place":"建康、胡豆洲（今江苏南京、高港一带）","state":"南朝梁","sources":["《梁书·王僧辩传》","《陈书·高祖纪》","《资治通鉴》梁纪"],"tags":["平侯景","王僧辩","陈霸先"]},"related":["cn--551--p01", "cn--555--p01"]},
  {"id":"cn--552--p01","track":"cn","year":552,"yearApprox":false,"dim":"politics","weight":5,"title":"突厥伊利可汗建国","summary":"阿史那土门破柔然，自号可汗通魏","detail":{"background":"突厥先世居金山之下，为柔然锻奴；土门既立，招聚其众，数有殊绩。","process":"土门西击铁勒大破之，声震塞北，柔然汗国寻乱，土门遂自立，号伊利可汗，遣使于西魏请婚，始与中国通使。","impact":"未十年而北方自柔然转为突厥，关陇与河北并事绥怀；其势西被于中亚，北朝之外患自此移于隋唐。","figures":["阿史那土门","宇文泰"],"place":"金山、高车故地（今阿尔泰山一带）","state":"突厥","sources":["《周书·突厥传》","《北史·突厥传》","《资治通鉴》梁纪"],"tags":["突厥崛起","伊利可汗","北狄"]},"related":["cn--553--p01", "cn--565--p01"]},
  {"id":"cn--552--p02","track":"cn","year":552,"yearApprox":false,"dim":"politics","weight":3,"title":"梁元帝即位江陵","summary":"承圣之号始于荆州，上游立国","detail":{"background":"侯景平而武陵王纪称帝于蜀，陈霸先、王僧辩分据要镇；元帝据荆州，上下游之兵方强。","process":"侯景既平，即位于江陵，改元承圣；以荆州为都而不还建康，寻与武陵相讨，蜀随以不守。","impact":"朝廷之势寄于上流，而江陵西逼于魏，建康东制于陈；梁祚之尽、南北之界皆自此定。","figures":["萧绎","萧纪","王僧辩"],"place":"江陵（今湖北荆州）","state":"南朝梁","sources":["《梁书·元帝纪》","《南史·梁本纪下》","《资治通鉴》梁纪"],"tags":["承圣","江陵","梁室"]},"related":["cn--554--m01", "cn--553--m01"]},
  {"id":"cn--553--m01","track":"cn","year":553,"yearApprox":false,"dim":"military","weight":3,"title":"西魏取蜀，克成都","summary":"尉迟迥自散关入，益州遂非梁有","detail":{"background":"梁室内乱，武陵王纪据蜀称帝，与江陵相讨；西魏宇文泰欲乘其弊而蜀道险远。","process":"承圣二年遣尉迟迥出散关，次汉中，径趋成都；蜀人震恐，纪之所署守令多降，迥遂有剑南之地。","impact":"西魏得蜀而并上游之势，江陵遂处其包围之中；南北之别自此以汉水、三峡为枢，隋取陈亦因之。","figures":["尉迟迥","萧纪","宇文泰"],"place":"成都、汉中（今四川、陕西）","state":"西魏","sources":["《周书·尉迟迥传》","《资治通鉴》梁纪"],"tags":["取蜀","剑南","梁之削弱"]},"related":["cn--552--p02", "cn--554--m01"]},
  {"id":"cn--553--p01","track":"cn","year":553,"yearApprox":false,"dim":"politics","weight":4,"title":"木杆可汗立，突厥遂盛","summary":"东灭柔然余部，西破嚈哒，北方无两主","detail":{"background":"伊利可汗寻死，嗣立者不久；其弟俟斤代立，号木杆可汗，性勇壮而多权略。","process":"木杆既立，西击嚈哒而尽有西域之道，北并契骨诸部；柔然余烬奔于西魏，漠北遂定于一。","impact":"自阴山至西域一线皆属突厥，北周、北齐各以重币结之；塞北之强族始为中国边患之最大者。","figures":["木杆可汗"],"place":"漠北（今蒙古高原）","state":"突厥","sources":["《周书·突厥传》","《北史·突厥传》"],"tags":["木杆可汗","柔然","嚈哒"]},"related":["cn--552--p01", "cn--565--p01"]},
  {"id":"cn--553--p02","track":"cn","year":553,"yearApprox":false,"dim":"politics","weight":3,"title":"新罗真兴王取汉江流域","summary":"乘梁乱得汉水之地，南与百济为仇","detail":{"background":"百济因梁室丧乱，北侵新罗；新罗真兴王既立，亦乘间图汉水之下流。","process":"真兴王十四年遣使入于梁，请讨百济以自效；梁以远不能救。其后遂城汉北诸戍，南与百济接境相争。","impact":"新罗得汉江而下通中国、北接高句丽，立国之基以广；百济寻败于管城，三国之势始定。","figures":["真兴王"],"place":"汉江流域（今朝鲜半岛中部）","state":"新罗","sources":["《三国史记》","《周书·异域传下》"],"tags":["新罗","真兴王","海东三国"]},"related":["cn--551--m01", "cn--554--m01"]},
  {"id":"cn--553--m02","track":"cn","year":553,"yearApprox":false,"dim":"military","weight":2,"title":"北齐文宣帝破契丹","summary":"亲逾山险以掩其不备，大破契丹之众","detail":{"background":"齐室起于六镇，恒、燕之北与蠕蠕、契丹接境；文宣既立，东北数为其患。","process":"天保四年契丹犯塞，文宣自晋阳北讨之，亲冒山险以掩其不意，大破其众，获牛马羊畜不可胜计；余部寻降。","impact":"契丹自是羁属于邺，北齐得安其东北以专意于周、陈之争；而营、幽之北，塞外诸部与边人错居，其俗浸染于中夏。","figures":["高洋"],"place":"北方塞外（今辽西、内蒙古东南一带）","state":"北齐","sources":["《北齐书·文宣帝纪》","《北史·齐本纪》"],"tags":["契丹","塞外民族","北齐"]},"related":["cn--550--p01", "cn--553--p01"]},
  {"id":"cn--554--m01","track":"cn","year":554,"yearApprox":false,"dim":"military","weight":4,"title":"西魏陷江陵，梁元帝死之","summary":"于谨长驱而济，城破而帝见杀","detail":{"background":"元帝与宇文泰书辞相失，又召魏人以自固；于谨以三策料之，断其下计。","process":"承圣三年魏师济汉而围江陵，中外断绝；城陷，帝奉其玺绶而出，寻为所杀，西魏大掠而还。","impact":"梁祚至此而尽；江陵之地止立后梁，其重则入于北周；江左衣冠文献多徙而北，南北之衡遂偏于关陇。","figures":["萧绎","于谨","杨忠","宇文泰"],"place":"江陵（今湖北荆州）","state":"西魏、南朝梁","sources":["《梁书·元帝纪》","《周书·于谨传》","《资治通鉴》梁纪"],"tags":["江陵之陷","梁元帝","西魏东侵"]},"related":["cn--552--p02", "cn--554--c01"]},
  {"id":"cn--554--c01","track":"cn","year":554,"yearApprox":false,"dim":"culture","weight":3,"title":"梁元帝焚其图书","summary":"城陷之前聚而焚之，辞林为之扫地","detail":{"background":"元帝好聚书，自江左以及荆州，前后所藏盈于秘阁；侯景乱起，建康之图籍已再坏。","process":"及江陵将陷，聚所读书而焚之于殿前，君臣相顾而叹，辞章散逸；其名画法书亦为魏军所携而北。","impact":"自晋、宋以来江左之文集、小学、图籍，再坏于侯景，三坏于江陵；隋、唐求书所收，其缺憾于此可见。","figures":["萧绎","萧詧"],"place":"江陵（今湖北荆州）","state":"南朝梁","sources":["《梁书·元帝纪》","《南史·梁本纪下》","《资治通鉴》梁纪"],"tags":["焚书","图籍散亡","江陵"]},"related":["cn--554--m01", "cn--530--c01"]},
  {"id":"cn--554--d01","track":"cn","year":554,"yearApprox":false,"dim":"disaster","weight":3,"title":"江陵士民驱入关中","summary":"城破之后大掠，老弱填于道路","detail":{"background":"江陵陷，魏军收其府库，简士民之工巧者；宇文泰方欲实关中。","process":"既克而大掠，驱荆州吏民而西，分充军赐；其老弱不堪行者填于道路，长安之有南人实自此始。","impact":"荆州士民北迁者，后多入隋唐之籍；江左衣冠文献由是北流，而荆、郢之间丘墟相望，数十年不复其旧。","figures":["于谨","宇文泰"],"place":"江陵至长安（今湖北、陕西）","state":"西魏","sources":["《周书·于谨传》","《北史》","《资治通鉴》梁纪"],"tags":["江陵之掠","北迁","士民流散"]},"related":["cn--554--m01", "cn--554--a01"]},
  {"id":"cn--554--a01","track":"cn","year":554,"yearApprox":false,"dim":"art","weight":3,"title":"庾信使长安，遂留北","summary":"衔命西来而国亡，文章自此一变","detail":{"background":"信字子山，南阳新野人，与父肩吾及徐摛父子并为东宫文体；侯景乱后奔江陵。","process":"承圣三年信奉使于西魏，会江陵陷，遂留长安；历事魏、周，久困于异代之禄，晚年之文多南方之思。","impact":"信在江左与徐陵并称「徐庾体」，及入北而其境与文俱变；《哀江南》之作遂开北地辞赋之新面，唐人称其「清新庾开府」。","figures":["庾信","宇文泰","王褒"],"place":"长安（今陕西西安西北）","state":"西魏、北周","sources":["《周书·庾信传》","《北史·文苑传》"],"tags":["庾信","徐庾体","南北文学"]},"related":["cn--554--d01", "cn--578--a01"]},
  {"id":"cn--555--p01","track":"cn","year":555,"yearApprox":false,"dim":"politics","weight":3,"title":"陈霸先袭杀王僧辩","summary":"自京口夜袭石头，江左遂归陈氏","detail":{"background":"江陵既陷，僧辩迎齐所立之萧渊明为嗣，霸先以为不可，书往复不决。","process":"绍泰元年九月霸先自京口举兵袭石头，擒僧辩缢杀之；寻破齐军于莫府山，奉敬帝而立，江左之政尽归霸先。","impact":"陈氏代梁之业定于此时；而淮阴、姑孰之北兵寻至，淮南之地多入于齐，南朝之北界自此益蹙。","figures":["陈霸先","王僧辩","萧渊明"],"place":"建康石头（今江苏南京西）","state":"南朝梁","sources":["《陈书·高祖纪》","《资治通鉴》梁纪"],"tags":["陈霸先","王僧辩","梁末方镇"]},"related":["cn--552--m01", "cn--557--p02"]},
  {"id":"cn--555--p02","track":"cn","year":555,"yearApprox":false,"dim":"politics","weight":2,"title":"后梁萧詧称帝江陵","summary":"魏人所立之梁，方数千里而称藩","detail":{"background":"江陵陷后，宇文泰以萧詧为梁主，使镇荆州，而留戍兵以制其出入。","process":"绍泰中萧詧即皇帝位于江陵之东岸，改元大定；所守一州之地，称藩于西魏，岁修职贡，而魏留戍以制之。","impact":"自是江陵别立一梁，为北方之附庸，历三世而隋废之；南北之界以汉水为限，而陈有江左而已。","figures":["萧詧","宇文泰"],"place":"江陵（今湖北荆州）","state":"后梁","sources":["《周书·萧詧传》","《北史·萧詧传》","《资治通鉴》梁纪"],"tags":["后梁","附庸","江陵"]},"related":["cn--554--m01", "cn--587--p01"]},
  {"id":"cn--556--i01","track":"cn","year":556,"yearApprox":false,"dim":"institution","weight":4,"title":"宇文泰初仿《周礼》置六官","summary":"以卢辩典其事，一周之制始代魏晋","detail":{"background":"泰以魏之官制繁碎，又欲以古制作成其新命之象；卢辩洽闻旧章，遂典其事。","process":"太平元年正月始命依《周礼》置六官，以泰为太师、大冢宰；其九命之品、都冢之号，皆辩等据《周官》为之，未几而周受禅。","impact":"六官之制行于周、隋之际，虽隋氏废之以复汉、魏之旧，而关陇政权之礼乐规模多因焉；苏绰、卢辩之业至是成。","figures":["宇文泰","卢辩"],"place":"长安（今陕西西安西北）","state":"西魏","sources":["《周书·文帝纪下》","《北史·艺术传》"],"tags":["六官","周礼","关陇制度"]},"related":["cn--541--i01", "cn--557--p01"]},
  {"id":"cn--556--f01","track":"cn","year":556,"yearApprox":false,"dim":"figure","weight":3,"title":"宇文泰卒于长安","summary":"自武功还而疾，以子幼托侄护","detail":{"background":"泰自平侯莫陈、并六镇之众，相魏二十余年；是岁自同州还，遇疾于武功。","process":"太平元年冬卒，年五十；以诸子皆幼，属其后事于兄子护；时朝野惶惧，护受顾命而总军国。","impact":"泰一身当关中数十年的局面：六条以治民，六官以立国，府兵以制军；自是周、隋之统皆其所遗。","figures":["宇文泰","宇文护"],"place":"长安、武功（今陕西西安、扶风南）","state":"西魏","sources":["《周书·文帝纪下》","《北史·周本纪》"],"tags":["宇文泰","顾命","关陇"]},"related":["cn--556--i01", "cn--557--p01"]},
  {"id":"cn--556--c01","track":"cn","year":556,"yearApprox":false,"dim":"culture","weight":2,"title":"那连提黎耶舍至邺译经","summary":"天保中西域三藏东来，敕住天平寺","detail":{"background":"北齐之世佛法最盛于邺都；西域沙门负其梵本相继而东。","process":"天保七年那连提黎耶舍至邺，敕住天平寺，昭玄都统一曹助其传译，所出经论数部，笔受之臣并当时名德。","impact":"自菩提流支译《十地》以后，邺下译事不辍；隋开皇十年敕召入京，续译于长安，北朝译业至隋而合。","figures":["那连提黎耶舍","高洋"],"place":"邺城天平寺（今河北临漳西南）","state":"北齐","sources":["《历代三宝纪》","《续高僧传》"],"tags":["译经","邺下","北齐佛教"]},"related":["cn--535--c01", "cn--568--a01"]},
  {"id":"cn--557--p01","track":"cn","year":557,"yearApprox":false,"dim":"politics","weight":4,"title":"周受魏禅，孝闵帝即位","summary":"宇文觉即天王位，国号周","detail":{"background":"泰既定六官之制，魏室徒拥空名；泰死，护总百揆，遂禅代之谋。","process":"恭帝逊位，宇文觉即天王位，国号周，追尊文王；以护为大司马、晋国公，居守而制朝廷。","impact":"西魏凡三世而绝，北周之基由此始；其国虽小，有蜀、有江汉之北，与齐、陈鼎足者二十余年。","figures":["宇文觉","宇文护","元廓"],"place":"长安（今陕西西安西北）","state":"北周","sources":["《周书·文帝纪下》","《周书·孝闵帝纪》","《资治通鉴》陈纪"],"tags":["北周代魏","天王","宇文护"]},"related":["cn--556--f01", "cn--557--p03"]},
  {"id":"cn--557--p02","track":"cn","year":557,"yearApprox":false,"dim":"politics","weight":4,"title":"陈代梁，武帝即位","summary":"陈霸先受梁禅，国号陈，改元永定","detail":{"background":"霸先既去僧辩，破北齐之师，据京口以制建康；敬帝冲幼，朝权独归。","process":"永定元年冬受梁禅，国号陈，是为高祖武帝；梁主萧方智降封江阴王，江左之统三易其姓。","impact":"陈有江左一隅，户口与土地视梁大减；凭淮、汉之险以自守，南北之势自此不复均。","figures":["陈霸先","萧方智"],"place":"建康（今江苏南京）","state":"南朝陈","sources":["《陈书·高祖纪》","《南史·陈本纪》","《资治通鉴》陈纪"],"tags":["陈代梁","永定","江左"]},"related":["cn--555--p01", "cn--589--p01"]},
  {"id":"cn--557--p03","track":"cn","year":557,"yearApprox":false,"dim":"politics","weight":2,"title":"宇文护废杀孝闵帝","summary":"帝欲诛护而不果，九月遂见废","detail":{"background":"帝虽泰之嫡子，既立，不堪护之专；群臣多附护，左右皆其腹心。","process":"九月护与公卿谋废帝为略阳公，寻遇杀；迎立鲁公毓，是为明帝，护之威权自此益盛。","impact":"周室之权尽入于护，三主相代皆其废置；武帝亲政之后，反齐、灭佛之谋皆自含怒于护始。","figures":["宇文护","宇文觉","宇文毓"],"place":"长安（今陕西西安西北）","state":"北周","sources":["《周书·孝闵帝纪》","《北史·周本纪》","《资治通鉴》陈纪"],"tags":["宇文护","废立","北周"]},"related":["cn--557--p01", "cn--560--p01"]},
  {"id":"cn--559--f01","track":"cn","year":559,"yearApprox":false,"dim":"figure","weight":2,"title":"北齐文宣帝高洋卒","summary":"天保十年末遇疾而崩，齐政三变","detail":{"background":"洋初即位，委用杨愔等，励精为政；数年以后肆其酗暴，诛戮无度。","process":"天保十年十二月卒于邺宫；太子殷立，是为废帝，寻为孝昭所废；数年之间，三主更代。","impact":"文宣之世，西拒周、北备突厥，而境内粗理；及其后诸主相乘，赏罚无章，齐人之势遂日诎于周。","figures":["高洋","高殷","杨愔"],"place":"邺城（今河北临漳西南）","state":"北齐","sources":["《北齐书·文宣帝纪》","《北史·齐本纪》"],"tags":["文宣帝","高洋","北齐"]},"related":["cn--550--p01", "cn--565--p02"]},
  {"id":"cn--560--p01","track":"cn","year":560,"yearApprox":false,"dim":"politics","weight":3,"title":"宇文护弑明帝，立武帝","summary":"糖饼进毒而世宗崩，武帝立于长安","detail":{"background":"明帝虽为护所立，而性沉明，颇有威名；护之母阎氏亦不悦帝，护由是忌之。","process":"武成二年四月护遣左右进糖饼以毒，帝遇弑；迎立滕王邕，是为武帝，年十八。","impact":"护三废立而周主皆非其死；武帝外若谦退，内定诛护之谋，亲政之后灭佛、平齐之业皆由此作。","figures":["宇文护","宇文毓","宇文邕"],"place":"长安（今陕西西安西北）","state":"北周","sources":["《周书·武帝纪上》","《北史·周本纪》","《资治通鉴》陈纪"],"tags":["宇文护","弑逆","周武帝"]},"related":["cn--557--p03", "cn--565--p01"]},
  {"id":"cn--560--p02","track":"cn","year":560,"yearApprox":false,"dim":"politics","weight":2,"title":"陈文帝即位","summary":"霸先嗣子冲幼，世祖以长立","detail":{"background":"武帝崩而嗣子昌年幼，临川王蒨以次立；时留异、陈宝应据郡不受代。","process":"天嘉元年世祖即位于建康，改元天嘉；讨留异于东阳、陈宝应于闽中，江左之乱略定。","impact":"陈室至是始有立国之规；而淮南之地寻入于周，文帝所能守者止江南数郡而已。","figures":["陈蒨","陈霸先","留异"],"place":"建康（今江苏南京）","state":"南朝陈","sources":["《陈书·世祖纪》","《南史·陈本纪》"],"tags":["陈文帝","天嘉","江左"]},"related":["cn--557--p02", "cn--562--p01"]},
  {"id":"cn--560--e01","track":"cn","year":560,"yearApprox":true,"dim":"economy","weight":2,"title":"北齐复治长城之戍","summary":"连岁发夫修塞，自瓦桥东至于海","detail":{"background":"天保中已筑长城，而工役未就；蠕蠕、突厥之寇逼于幽、肆之间。","process":"皇建之际又发夫续修其戍，置烽戍，自瓦桥东引至于海；连年之役，河朔之民疲于转输。","impact":"北齐之边备在朔方而不在河南，故其国力尽于长城一役；周人东向，而齐之兵已先敝。","figures":["高演"],"place":"自肆州北至海（今山西北部、河北）","state":"北齐","sources":["《北齐书·孝昭帝纪》","《北史·齐本纪》"],"tags":["长城","河朔","役政"]},"related":["cn--562--m01", "cn--577--p01"]},
  {"id":"cn--561--p01","track":"cn","year":561,"yearApprox":false,"dim":"politics","weight":2,"title":"北齐武成帝立","summary":"孝昭无嗣，母弟湛入承大统","detail":{"background":"废帝殷在位数月而为孝昭所废；演立一年而殂，无嗣。","process":"太宁元年孝昭崩，太后以母弟相王湛入继；改元太宁，寻传位于太子纬，而自为太上皇。","impact":"齐室之统自此不复归于长；后主冲幼，权在近习与诸王，十余年间而邺城为周有。","figures":["高湛","高演","胡太后"],"place":"邺城（今河北临漳西南）","state":"北齐","sources":["《北齐书·武成帝纪》","《北史·齐本纪》"],"tags":["北齐废立","武成帝","邺城"]},"related":["cn--559--f01", "cn--565--p02"]},
  {"id":"cn--562--p01","track":"cn","year":562,"yearApprox":false,"dim":"politics","weight":1,"title":"后梁萧岿嗣立于江陵","summary":"詧死而岿立，称藩于周","detail":{"background":"萧詧以江陵附魏，魏人留戍临其城；詧寻忧愤而卒。","process":"天嘉中岿嗣梁王之位，改元天保；周人以其地狭，命还守旧封，而荆襄之间多入于陈。","impact":"后梁一姓仅守一州，为南北之缓冲；开皇七年隋废其国，江陵之地遂直属关中。","figures":["萧岿","萧詧"],"place":"江陵（今湖北荆州）","state":"后梁","sources":["《周书·萧詧传》","《北史·萧詧传》"],"tags":["后梁","附庸","江陵"]},"related":["cn--555--p02", "cn--587--p01"]},
  {"id":"cn--562--m01","track":"cn","year":562,"yearApprox":false,"dim":"military","weight":2,"title":"突厥南寇，齐主御于晋阳","summary":"木杆之后塞北兵至，太原戒严","detail":{"background":"突厥既得漠北，与北周结昏；齐之所恃者，赂遗而已。","process":"河清元年突厥自晋北南入，声言至邺；齐主自晋阳拒之，前锋破其游骑，会其国内变而退。","impact":"塞北一寇而齐、周俱为之动；自是北朝岁费府库以奉突厥，齐人修长城、周人结婚好，皆为此虏。","figures":["高湛","木杆可汗"],"place":"晋阳、肆州（今山西太原、忻州一带）","state":"北齐、突厥","sources":["《北齐书·武成帝纪》","《周书·突厥传》","《资治通鉴》陈纪"],"tags":["突厥","晋阳","北齐北边"]},"related":["cn--560--e01", "cn--565--p01"]},
  {"id":"cn--565--p01","track":"cn","year":565,"yearApprox":true,"dim":"politics","weight":3,"title":"周与突厥结昏，遣使往逆","summary":"周遣使往逆，木杆寻悔其约","detail":{"background":"宇文泰、宇文护世与突厥结昏，木杆寻悔，遂缓其期。","process":"武成末护复遣使往逆，具卤簿以迎之；木杆寻悔其约，迁延数年，会木杆死，其弟佗钵立。","impact":"周与突厥既昏，北齐处其冲；其后灭齐之时，突厥果内扰而周不能制，和亲之为得失在此。","figures":["宇文邕","阿史那皇后","宇文护"],"place":"长安（今陕西西安西北）","state":"北周、突厥","sources":["《周书·皇后传》","《北史·突厥传》","《资治通鉴》周纪"],"tags":["和亲","突厥","北周"]},"related":["cn--553--p01", "cn--577--p01"]},
  {"id":"cn--565--p02","track":"cn","year":565,"yearApprox":false,"dim":"politics","weight":3,"title":"北齐武成帝传位于后主","summary":"以幼主当应运之谶，自为太上皇","detail":{"background":"或言齐室将衰、主上应让；武成遂欲以冲子当之，且图逸豫。","process":"天统元年帝禅位于太子纬，时甫十岁，自称太上皇帝；胡太后与和士开等并用，纲纪遂紊。","impact":"后主在位十有二年，而佞幸、乐工、尼媪之流填于朝廷；周人三伐而齐不支，亡国之兆已定于传位之日。","figures":["高纬","高湛","和士开","胡太后"],"place":"邺城（今河北临漳西南）","state":"北齐","sources":["《北齐书·后主纪》","《北史·齐本纪》","《资治通鉴》周纪"],"tags":["北齐后主","传位","佞幸"]},"related":["cn--561--p01", "cn--577--p01"]},
  {"id":"cn--568--a01","track":"cn","year":568,"yearApprox":false,"dim":"art","weight":2,"title":"唐邕刻《维摩》等经于鼓山石窟","summary":"北齐之末刻经于邺西，岩壁为之有字","detail":{"background":"邺都佛法之盛，自天保以来，讲席与刻经并起；唐邕历官显要，雅信释氏。","process":"后主之世邕写《维摩》《思益》《华严》等部，刻之于鼓山石窟之壁，命工勒石，以备来者之览。","impact":"鼓山刻经今存其迹，与南北诸石窟并足稽北朝书体、刻工与释典之流布。","figures":["唐邕","高纬"],"place":"邺西鼓山石窟寺（今河北临漳、峰峰一带）","state":"北齐","sources":["《北齐书·唐邕传》","《续高僧传》"],"tags":["石窟","刻经","响堂山"]},"related":["cn--556--c01", "cn--574--c01"]},
  {"id":"cn--569--c01","track":"cn","year":569,"yearApprox":true,"dim":"culture","weight":3,"title":"智顗至建康讲《法华》","summary":"陈光大中来止瓦官寺，说《法华》之旨","detail":{"background":"智顗事南岳慧思于光州、南岳，习《法华》三昧；陈废帝之世东下。","process":"光大之际来止建康瓦官寺，讲《法华经》之题旨与《大智度论》之要，陈之朝贵执弟子礼；天台一家之纲目，实成于此时之说。","impact":"天台一宗之学自江东立其基；隋开皇中顗复行化于荆、扬之间，撰《法华玄义》，而南朝天台之教北行于隋。","figures":["智顗","慧思"],"place":"建康瓦官寺（今江苏南京）","state":"南朝陈","sources":["《续高僧传》","《法华玄义》"],"tags":["天台","法华","智顗"]},"related":["cn--586--c01", "cn--556--c01"]},
  {"id":"cn--572--p01","track":"cn","year":572,"yearApprox":false,"dim":"politics","weight":3,"title":"周武帝诛宇文护，亲总万机","summary":"会公卿于殿中而杀之，威权始归帝","detail":{"background":"护连弑二帝，权移人主；帝外示宽假，而阴与左右之士定谋，所忌者唯护。","process":"建德元年帝与护共听《酒诰》于仁寿殿，因以玉挺击护，左右遂杀之；并诛其诸子，诏数其罪，自是军国之政尽出于帝。","impact":"北周之权始一反于君；帝既亲政，遂有诛求于齐、禁断于浮屠之志，关陇之局自此一变。","figures":["宇文邕","宇文护"],"place":"长安（今陕西西安西北）","state":"北周","sources":["《周书·武帝纪上》","《北史·宇文护传》","《资治通鉴》周纪"],"tags":["诛宇文护","亲政","北周"]},"related":["cn--560--p01", "cn--574--c01"]},
  {"id":"cn--573--p01","track":"cn","year":573,"yearApprox":true,"dim":"politics","weight":2,"title":"突厥送阿史那氏于周","summary":"佗钵以木杆之女来归，帝纳为皇后","detail":{"background":"周与突厥议婚累年，木杆寻悔，及弟佗钵立，复申前好。","process":"建德中佗钵遣使送女来归，周备礼迎于塞下；帝纳阿史那氏为皇后，突厥之使相望于长安。","impact":"周北一无事，得专意于山东；及武帝灭齐，突厥果以救齐为名入寇，而周以新定之业应之。","figures":["宇文邕","阿史那皇后","佗钵可汗"],"place":"长安（今陕西西安西北）","state":"北周、突厥","sources":["《周书·皇后传》","《北史·突厥传》","《资治通鉴》周纪"],"tags":["和亲","突厥","北周"]},"related":["cn--565--p01", "cn--577--p01"]},
  {"id":"cn--573--c01","track":"cn","year":573,"yearApprox":false,"dim":"culture","weight":2,"title":"周武帝集三教于含元殿","summary":"论三教先后，以儒为宗而次及老、释","detail":{"background":"帝以齐、周并争，须有以整其风俗，而寺僧之众、二教之争日闻于朝。","process":"建德中三教之义累集于含元殿论之；帝亲正其序，以儒教处先，而释、老次之，朝士、僧道并预其会。","impact":"三教高下之议自此启于北朝，明年遂有断佛之诏；隋、唐因之，三教论难遂为朝廷故事。","figures":["宇文邕","卫元嵩"],"place":"长安含元殿（今陕西西安西北）","state":"北周","sources":["《周书·武帝纪》","《广弘明集》"],"tags":["三教","含元殿","北周"]},"related":["cn--574--c01", "cn--504--c01"]},
  {"id":"cn--574--c01","track":"cn","year":574,"yearApprox":false,"dim":"culture","weight":5,"title":"周武断佛、道二教","summary":"初断二教，僧还俗而图籍入官","detail":{"background":"帝以沙门不婚、不耕而耗生民之力，又纳卫元嵩之议，欲一其风。","process":"建德三年五月初断佛、道二教，经像悉毁，罢沙门、道士并令还民，三宝之田籍没入官；集僧于庭而数其罪，沙门虽有抗辞而莫之救。","impact":"太武之禁不至此之整一；北方寺观扫地而兵农之资尽出，未四年而北齐亦亡，齐地之佛同归于尽。","figures":["宇文邕","卫元嵩","昙宗"],"place":"长安及关陇诸州（今陕西、甘肃）","state":"北周","sources":["《周书·武帝纪》","《广弘明集》","《资治通鉴》周纪"],"tags":["建德灭佛","三武之祸","僧尼还俗"]},"related":["cn--446--c01", "cn--577--p01"]},
  {"id":"cn--575--m01","track":"cn","year":575,"yearApprox":false,"dim":"military","weight":2,"title":"周武帝首次亲伐北齐","summary":"自风陵而济，克数戍而帝遇疾还","detail":{"background":"齐之后主昏于酒色，诛戮将相；周人以帝亲政之锐，谋东伐。","process":"建德四年帝亲勒六军，自风陵济河而东，克河阴、武陟诸戍；会帝不豫，乃焚舟而还。","impact":"周人始知其可以得志于齐；明年而复举，平阳之役遂为入邺之阶。","figures":["宇文邕","高纬"],"place":"河阴、洛口（今河南孟津、巩义东北）","state":"北周","sources":["《周书·武帝纪下》","《北齐书·后主纪》","《资治通鉴》周纪"],"tags":["伐齐","亲征","周齐"]},"related":["cn--576--m01", "cn--577--p01"]},
  {"id":"cn--576--m01","track":"cn","year":576,"yearApprox":false,"dim":"military","weight":3,"title":"周再伐齐，拔晋州平阳","summary":"六军重出而平阳陷，齐人来救","detail":{"background":"帝以平阳为晋阳之肩背、邺都之藩篱，不先取之不可东向。","process":"建德五年帝复亲征，急攻平阳，旬有数日而拔之；留兵而守，齐主悉众来救，围之数重，城中守御不移。","impact":"平阳一失，齐之三道震骇；帝以逸待劳，明年遂长驱而入邺。","figures":["宇文邕","高纬","梁士彦"],"place":"平阳、晋州（今山西临汾）","state":"北周、北齐","sources":["《周书·武帝纪下》","《北齐书·后主纪》","《资治通鉴》周纪"],"tags":["平阳","晋州","北齐之亡"]},"related":["cn--575--m01", "cn--577--p01"]},
  {"id":"cn--577--p01","track":"cn","year":577,"yearApprox":false,"dim":"politics","weight":5,"title":"周入邺，北齐亡","summary":"乘胜东下，齐主就禽而五主之祚尽","detail":{"background":"平阳既陷，齐主奔于邺；周人料其众叛，故不战而图其都。","process":"建德六年正月周师入邺，齐主东走，至于渤海之野而兵散，乃就擒；并其诸王皆至长安，齐凡五主、二十有八年而亡。","impact":"黄河以北尽入于周，南朝之所守者淮南而已；隋室代周，遂以混一之势临江左。","figures":["宇文邕","高纬","宇文宪"],"place":"邺城（今河北临漳西南）","state":"北周","sources":["《周书·武帝纪下》","《北齐书·后主纪》","《资治通鉴》周纪"],"tags":["北齐亡","平邺","统一趋势"]},"related":["cn--550--p01", "cn--581--p01"]},
  {"id":"cn--578--a01","track":"cn","year":578,"yearApprox":true,"dim":"art","weight":3,"title":"庾信作《哀江南赋》","summary":"追梁室之乱离，一篇皆江南之痛","detail":{"background":"信自江陵入关，历事西魏、北周；位望通显而客情愈至，晚年乃追述梁末之事。","process":"乃作《哀江南》之赋，叙梁室之乱亡与己身之羁旅，上及衣冠之流离，下及江关之萧瑟；其序与辞并行于世。","impact":"六朝辞赋至此为一大结穴；北地文士由是渐变南方新声之体，南北之文由是渐合，唐人论赋多推及之。","figures":["庾信"],"place":"长安（今陕西西安西北）","state":"北周","sources":["《庾子山集》","《周书·庾信传》"],"tags":["哀江南赋","庾信","南北文学"]},"related":["cn--554--a01", "cn--580--f01"]},
  {"id":"cn--578--f01","track":"cn","year":578,"yearApprox":false,"dim":"figure","weight":3,"title":"周武帝崩于长安","summary":"亲政六年而帝遽殂，宣帝立而政尽变","detail":{"background":"帝躬履俭素，勤于政事，方欲北抚突厥、南图江左。","process":"宣政元年六月帝崩；太子赟立，是为宣帝，在位二年而崩，静帝冲幼，政遂归于杨坚。","impact":"灭齐之业未三年而身殂；典学之君一殁，禁断之令随弛，隋氏之代周亦因其短促而成。","figures":["宇文邕","宇文赟","杨坚"],"place":"长安（今陕西西安西北）","state":"北周","sources":["《周书·武帝纪下》","《北史·周本纪》"],"tags":["周武帝","宣政","北周衰亡"]},"related":["cn--577--p01", "cn--579--p01"]},
  {"id":"cn--579--p01","track":"cn","year":579,"yearApprox":false,"dim":"politics","weight":2,"title":"周宣帝传位于静帝","summary":"自称天元皇帝而内行不出，朝政益紊","detail":{"background":"帝即位之后，悉改武帝之政，浮屠之禁寻弛；而多内宠，刑罚无恒。","process":"大象元年二月传位于太子阐，是为静帝，方八岁；帝自称天元皇帝，犹总万机，寻东巡至于洛阳、邺城。","impact":"周室之权自此倒悬；宣帝崩而静主冲幼，外戚杨坚以顾命入据朝廷，二年而周亡。","figures":["宇文赟","宇文阐","杨坚"],"place":"长安、邺城（今陕西、河北）","state":"北周","sources":["《周书·宣帝纪》","《北史·周本纪》","《资治通鉴》周纪"],"tags":["周宣帝","传位","天元皇帝"]},"related":["cn--578--f01", "cn--580--p01"]},
  {"id":"cn--580--p01","track":"cn","year":580,"yearApprox":false,"dim":"politics","weight":4,"title":"周宣帝崩，杨坚总百揆","summary":"静帝冲幼，外戚以顾命入秉朝权","detail":{"background":"宣帝在东巡途中遇疾而还；后父杨坚以外戚居朝，素为帝所忌。","process":"大象二年五月帝崩，太子阐立，是为静帝；刘昉、郑译定议，以坚为假黄钺、左大丞相，居中总百揆，王、郑之徒皆见任使。","impact":"周室之政不便于宗藩而尽归于杨氏；尉迟迥之乱起，不百日而平，未周岁而隋受禅。","figures":["杨坚","宇文阐","刘昉","郑译"],"place":"长安（今陕西西安西北）","state":"北周","sources":["《隋书·高祖纪上》","《周书·静帝纪》","《资治通鉴》周纪"],"tags":["杨坚辅政","顾命","北周末"]},"related":["cn--579--p01", "cn--581--p01"]},
  {"id":"cn--580--m01","track":"cn","year":580,"yearApprox":false,"dim":"military","weight":3,"title":"尉迟迥起兵相州，兵败死之","summary":"三总管举兵而不克，邺城寻废","detail":{"background":"杨坚辅政，尉迟迥以相州都督起兵，赵、郓、荆州各镇多应之；坚所恃者唯关中。","process":"六月迥举兵于邺，众号数十万；丞相府遣韦孝宽督军讨之，战于邺城之下，迥军败，登城楼自刺而死。","impact":"关东之兵一举而定；隋室惩其地而徙相州，邺都之业至是遂尽，而宇文之党亦无所复倚。","figures":["尉迟迥","韦孝宽","高颎","杨坚"],"place":"邺城（今河北临漳西南）","state":"北周","sources":["《周书·尉迟迥传》","《隋书·高祖纪上》","《资治通鉴》周纪"],"tags":["尉迟迥","相州","杨坚代周"]},"related":["cn--580--p01", "cn--580--p02"]},
  {"id":"cn--580--p02","track":"cn","year":580,"yearApprox":true,"dim":"politics","weight":2,"title":"徙相州于安阳，邺城遂废","summary":"惩尉迟迥之据，发徙其民而焚其居","detail":{"background":"邺自东魏、北齐皆为都，而山东之乱常自邺始。","process":"相州既平，高颎以邺城殷盛而数为用户之患，奏徙其州治于安阳，并迁其居民；邺中宫室寻亦焚废。","impact":"北朝以来河北第一大都自此不复为都，人物悉徙于安阳；而隋、唐河北之势分，其端在此。","figures":["高颎","杨坚"],"place":"邺城、安阳（今河北临漳、安阳）","state":"隋","sources":["《隋书·高祖纪上》","《隋书·地理志》"],"tags":["邺城残废","徙治","河北"]},"related":["cn--580--m01", "cn--534--p02"]},
  {"id":"cn--580--f01","track":"cn","year":580,"yearApprox":false,"dim":"figure","weight":2,"title":"庾信卒于长安","summary":"六朝最后一大宗匠没于关内","detail":{"background":"信自江陵入关，历事西魏、北周；位望通显而常怀羁旅，晚岁遂成《哀江南》之赋。","process":"开皇元年卒于长安，隋室为具礼祭之，追赠有加；其诗文行于代，北人竞传习之。","impact":"六朝文学至是而最后一大宗匠没；南朝之声律与北朝之贞干，由是合流于隋、唐之文。","figures":["庾信","杨坚"],"place":"长安（今陕西西安西北）","state":"隋","sources":["《周书·庾信传》","《北史·文苑传》","《庾子山集》"],"tags":["庾信","六朝文学","南北文合"]},"related":["cn--554--a01", "cn--578--a01"]},
  {"id":"cn--581--p01","track":"cn","year":581,"yearApprox":false,"dim":"politics","weight":5,"title":"隋受周禅，文帝即位","summary":"杨坚即皇帝位，国号隋，改元开皇","detail":{"background":"坚既平尉迟迥，进爵为王，太子、诸王多被徙；静帝拱手而已。","process":"开皇元年二月受周禅，即皇帝位，国号隋，改元开皇；追尊其父忠为太祖，周之六官悉废而复汉、魏之旧。","impact":"北朝之统自拓跋氏之兴垂二百年至是转移；关陇、河北与淮南之势，由此一归于隋，未十年而混一之功成焉。","figures":["杨坚","宇文阐","杨忠"],"place":"长安（今陕西西安西北）","state":"隋","sources":["《隋书·高祖纪上》","《资治通鉴》隋纪"],"tags":["隋代周","开皇","统一前夜"]},"related":["cn--577--p01", "cn--589--p01"]},
  {"id":"cn--581--i01","track":"cn","year":581,"yearApprox":false,"dim":"institution","weight":3,"title":"隋废六官，复汉魏之旧","summary":"省周礼之文，置三省台省之官","detail":{"background":"宇文氏以《周礼》立六官，事虽行而名实不相应；高颎、苏威知不可久。","process":"受禅之初即废六官之号，复置三省、六曹与御史台之属，居其任者多周之旧臣；台省之制遂为唐所因。","impact":"周、隋之际官制的一大改更；自是六省之制行于后世，而关陇之礼乐遗意渐微。","figures":["杨坚","高颎","苏威"],"place":"长安（今陕西西安西北）","state":"隋","sources":["《隋书·百官志》","《隋书·高祖纪上》"],"tags":["官制","三省","隋唐之际"]},"related":["cn--556--i01", "cn--583--i02"]},
  {"id":"cn--581--a01","track":"cn","year":581,"yearApprox":false,"dim":"art","weight":3,"title":"隋诏创大兴城于龙首原","summary":"以汉长安卑隘，别营新邑于其东","detail":{"background":"汉、魏以来之长安，城小而隘，宫阙故物皆前世所为；水卤不便。","process":"开皇二年诏于龙首原之东营新都，命太子左庶子宇文恺领其制度；城分宫城、皇城，里坊棋布，徙旧都之民实之。","impact":"大兴城为隋唐长安之基，其规制开后世里坊都城之盛；隋、唐之世东亚诸国之营国者多取则焉。","figures":["杨坚","宇文恺"],"place":"大兴城（今陕西西安）","state":"隋","sources":["《隋书·高祖纪上》","《隋书·宇文恺传》","《唐两京城坊考》"],"tags":["大兴城","都城","宇文恺"]},"related":["cn--494--p01", "cn--582--p01"]},
  {"id":"cn--582--p01","track":"cn","year":582,"yearApprox":true,"dim":"politics","weight":2,"title":"隋徙都于大兴城","summary":"新邑既成，帝自长安故城徙居之","detail":{"background":"汉长安自末造以来，宫室残旧，人物湫隘；新都之役已成。","process":"新都既成，以大兴为名，徙旧都之民实之；帝寻自长安故城移居新都，事在开皇之初；旧都之仓署及宗庙渐废，长安故城但为坊里。","impact":"隋唐三百余年的关中政治中心自此定于龙首原之东；其地望与漕渠之利害，并系于隋、唐国势。","figures":["杨坚"],"place":"大兴城（今陕西西安）","state":"隋","sources":["《隋书·高祖纪上》","《唐两京城坊考》"],"tags":["徙都","大兴","长安"]},"related":["cn--581--a01"]},
  {"id":"cn--583--i01","track":"cn","year":583,"yearApprox":true,"dim":"institution","weight":4,"title":"隋班新令，定均田与租调","summary":"新令既行，丁男受田而课有常品","detail":{"background":"周末之政赋烦而户隐；高颎、苏威受诏更定令格式。","process":"开皇之初班新令于天下，定丁男、妇人之受田，为课调之品，而务在宽简；其后又减前代役数。","impact":"均田、租调至隋而定型，唐之制多其所遗；与下「貌阅」「输籍」二令相乘，隋室遂致户口之盛。","figures":["杨坚","高颎","苏威"],"place":"长安（今陕西西安西北）","state":"隋","sources":["《隋书·食货志》","《通典·食货》"],"tags":["均田","租调","开皇之治"]},"related":["cn--485--i01", "cn--585--i03"]},
  {"id":"cn--583--i02","track":"cn","year":583,"yearApprox":true,"dim":"institution","weight":4,"title":"《开皇律》成","summary":"更定科条，去前代之苛而五刑以齐","detail":{"background":"周、齐之末科条烦酷，鞭、杖、流、死之目各有异同；高颎等奉诏删定。","process":"新律以名例为首而勒十二篇，去前代苛酷之条，定笞、杖、徒、流、死之等；自是讫于唐之《贞观律》，多循其文。","impact":"隋律为汉、魏以来刑制之总结，开唐律之先；其五刑之制与篇目为东亚后世刑书所祖。","figures":["杨坚","高颎","苏威","裴政"],"place":"长安（今陕西西安西北）","state":"隋","sources":["《隋书·刑法志》","《隋书·高祖纪上》"],"tags":["开皇律","五刑","唐律所本"]},"related":["cn--268--i01", "cn--581--i01"]},
  {"id":"cn--583--c01","track":"cn","year":583,"yearApprox":false,"dim":"culture","weight":2,"title":"牛弘奏请访求遗书","summary":"以篇牍散亡，诏访天下异本而资以币","detail":{"background":"自侯景之乱与江陵之败，篇牍三坏；秘书所藏多残缺。","process":"开皇三年弘以上表请访遗书，诏分遣使人搜访于诸道，人间异本渐出；其校写之，藏于秘阁。","impact":"隋室由是粗备一代图书，唐之《隋书·经籍志》所著录者多基于此；六朝散亡之文赖以不尽泯。","figures":["牛弘","杨坚"],"place":"长安（今陕西西安西北）","state":"隋","sources":["《隋书·牛弘传》","《隋书·经籍志》"],"tags":["求书","经籍志","目录"]},"related":["cn--554--c01", "cn--586--c01"]},
  {"id":"cn--583--d01","track":"cn","year":583,"yearApprox":false,"dim":"disaster","weight":2,"title":"关内旱俭，隋人东出就食","summary":"都中廪藏不给，诏听民东出关就食","detail":{"background":"隋都长安而关中仓廪尚虚，户口稍滋，仰食于漕；会关内不登。","process":"开皇三年关内旱俭，都中廪藏不给，诏听民东出，就食于陕、洛之间；帝亦遣使抚慰，且罢不急之役。","impact":"都内仰食关东之病自是不去，隋、唐遂有广运之渠与东都之制；仓廪之政为有隋之急务。","figures":["杨坚"],"place":"关中、陕洛（今陕西、河南）","state":"隋","sources":["《隋书·食货志》","《隋书·高祖纪上》"],"tags":["旱饥","就食","漕运之由"]},"related":["cn--585--e01", "cn--581--a01"]},
  {"id":"cn--585--i03","track":"cn","year":585,"yearApprox":false,"dim":"institution","weight":4,"title":"隋大索貌阅天下户口","summary":"按人口之状以定老幼，得新附之户甚众","detail":{"background":"江左以来，民多避役，诈老诈小，依附于豪家而不上于版籍。","process":"开皇五年令诸州貌阅其人，定其年貌；若有一人形貌不符，里正以上远配；又令群居依附之户皆析其籍，不许容于豪家。","impact":"隋之版籍至是大进，国家赋役之本由是而实；唐之租庸调与均田，皆赖此等检括之法。","figures":["杨坚","高颎"],"place":"长安及诸州（今陕西、河南、河北）","state":"隋","sources":["《隋书·高祖纪上》","《隋书·食货志》"],"tags":["大索貌阅","户口","赋役"]},"related":["cn--585--i04", "cn--140--e01"]},
  {"id":"cn--585--i04","track":"cn","year":585,"yearApprox":false,"dim":"institution","weight":3,"title":"隋用输籍定样","summary":"州县每年正月定户之高下，使民不知欺","detail":{"background":"貌阅虽行，而豪强之赋或轻、下户之课或重，吏得上下其手。","process":"高颎以人间赋等不定，乃奏令诸州县每年正月五日，据民贫富定为输籍之样；而令其自出，民无侥幸。","impact":"输籍之法行而豪强无所隐其户，国家课调有准；唐代之九等定户，即循此而成。","figures":["高颎","杨坚"],"place":"诸州县（今黄河、长江之间）","state":"隋","sources":["《隋书·食货志》","《通典·食货》"],"tags":["输籍定样","户等","赋税"]},"related":["cn--585--i03", "cn--486--i01"]},
  {"id":"cn--585--e01","track":"cn","year":585,"yearApprox":true,"dim":"economy","weight":3,"title":"隋立义仓，民间岁俭则赈","summary":"度民之获而贮于社，号曰义仓","detail":{"background":"都内之仓仰于漕运，而州县之民有凶年则无所取给。","process":"开皇中民部奏请，令诸州百姓及军人祠祀之际，计户劝课，各随所熟而出粟麦，贮之于社；至俭岁则发以赈之。","impact":"隋之仓廪至是甲于前代，而州县社仓之法亦遂为后世所不能废。","figures":["长孙平","杨坚"],"place":"诸州之社仓（今河南、河北、陕西）","state":"隋","sources":["《隋书·长孙平传》","《隋书·食货志》"],"tags":["义仓","社仓","备荒"]},"related":["cn--583--d01", "cn--585--i03"]},
  {"id":"cn--586--c01","track":"cn","year":586,"yearApprox":true,"dim":"culture","weight":3,"title":"净影慧远撰《大乘义章》","summary":"撮众部之义为一书，北地义学之宗","detail":{"background":"慧远事昭玄统法上，习《地论》《华严》之部，后住邺都之净影寺；北地义学之盛至是极。","process":"远撮群经论之义，随事分类而释之，勒成《大乘义章》，自法体以至义味，条流粲然；其书晚出而数经修订。周武断释，乃隐于汲郡之西山；及隋室既兴，又住长安之净影寺，其学遂行于关、邺之间。","impact":"《大乘义章》为唐以前义学之总钥；天台、华严之判释多所采及，北地义学至隋而与江东合。","figures":["慧远","法上"],"place":"邺城净影寺、长安（今河北、陕西）","state":"北齐、隋","sources":["《大乘义章》","《续高僧传》"],"tags":["地论","净影慧远","义章"]},"related":["cn--538--c01", "cn--569--c01"]},
  {"id":"cn--587--c01","track":"cn","year":587,"yearApprox":true,"dim":"culture","weight":2,"title":"三论之学盛于江左","summary":"《中》《百》《十二门》之疏，江南相承以讲","detail":{"background":"罗什所出三论之文，南朝以来传于江东；僧诠之徒以之立于建康。","process":"陈、隋之间，吉藏承其师说而讲《三论》，江表义学之士多归之；随其讲疏之目，渐成一家之章句。","impact":"三论之宗由江东而传于隋唐之世；其破邪显正之方法，与天台之止观并为南朝义学之两峰。","figures":["吉藏","僧诠"],"place":"建康、会稽（今江苏、浙江）","state":"南朝陈","sources":["《续高僧传》","《三论玄义》"],"tags":["三论","吉藏","江南义学"]},"related":["cn--569--c01", "cn--504--c01"]},
  {"id":"cn--587--p01","track":"cn","year":587,"yearApprox":false,"dim":"politics","weight":2,"title":"隋废后梁，江陵为郡县","summary":"徵梁主入朝而撤其国，荆、襄直属于关","detail":{"background":"萧氏自詧以来以江陵附魏、周；至是隋文帝以江陵之地为必取。","process":"开皇七年徵后梁主琮入朝，寻因其国人之乱而废梁国，以其地为郡县；荆襄之间，遂与江北直隶关中。","impact":"南北之势至是已成；后梁之废为隋伐陈除其腋肘之患，长江上游不复有间。","figures":["杨坚","萧琮"],"place":"江陵（今湖北荆州）","state":"隋","sources":["《隋书·高祖纪上》","《北史·萧詧传》","《资治通鉴》隋纪"],"tags":["废后梁","江陵","隋之统一"]},"related":["cn--555--p02", "cn--588--m02"]},
  {"id":"cn--588--m01","track":"cn","year":588,"yearApprox":true,"dim":"military","weight":3,"title":"贺若弼镇广陵，上取陈之策","summary":"临江北而缮兵，密奏取陈之宜","detail":{"background":"隋既代周，欲东下而患江之险；高颎以取陈之策对，且命将临淮。","process":"开皇中以贺若弼为吴州总管，镇于广陵，阴缮舟甲、习水战；弼上取陈之策，帝深纳之。","impact":"江北三镇（广陵、六合、横江）之局既定，陈人之备遂疲于奔命；明年隋师济江，弼实当东路之锋。","figures":["贺若弼","高颎","杨坚"],"place":"广陵（今江苏扬州）","state":"隋","sources":["《隋书·贺若弼传》","《资治通鉴》隋纪"],"tags":["贺若弼","广陵","伐陈之谋"]},"related":["cn--588--m02", "cn--587--p01"]},
  {"id":"cn--588--s01","track":"cn","year":588,"yearApprox":true,"dim":"science","weight":2,"title":"杨素在永安造五层楼船","summary":"舰高数层而容八百人，为伐陈之具","detail":{"background":"隋既谋江南，而水战之具须素习；信州当三峡之下。","process":"杨素在永安造大舰，名曰五牙，上起楼五层，容战士八百人；舳舻蔽江而下，陈人见之夺气。","impact":"楼船之制至隋而大备，江上水战之具自此为一格；唐、宋江行舟师多循其遗意。","figures":["杨素","杨坚"],"place":"永安、江州（今重庆奉节、江西九江）","state":"隋","sources":["《隋书·杨素传》","《资治通鉴》隋纪"],"tags":["楼船","舟师","五牙舰"]},"related":["cn--588--m01", "cn--589--p01"]},
  {"id":"cn--588--m02","track":"cn","year":588,"yearApprox":false,"dim":"military","weight":3,"title":"隋以晋王广为元帅伐陈","summary":"三道临江而诸军受节度，陈人始惧","detail":{"background":"陈政浸乱，隋谋益坚；高颎既定取陈之策，贺若弼、杨素分临上下游。","process":"开皇八年春诏以晋王广为元帅，镇于寿春，节度诸军；沿江诸总管道并受其处分，舟师临江，陈人始惧。","impact":"南北之师至是大集，明年而陈亡；隋之混一由淮南一路得之，而晋王总戎之功遂为后日夺宗之张本。","figures":["杨广","贺若弼","杨素","杨坚"],"place":"寿春（今安徽寿县）","state":"隋","sources":["《隋书·高祖纪上》","《隋书·贺若弼传》","《资治通鉴》隋纪"],"tags":["伐陈","元帅","隋之统一"]},"related":["cn--588--m01", "cn--587--p01", "cn--589--p01"]},
  {"id":"cn--588--p01","track":"cn","year":588,"yearApprox":false,"dim":"politics","weight":2,"title":"陈后主不设备","summary":"隋人临淮而边书不至，君臣奏宴不辍","detail":{"background":"陈主以江为天然之阻，且隋方北备突厥，谓必不能济。","process":"至德之末，边镇之书或不以闻；诸将请发兵，多见抑而不行，君臣奏宴于后庭。","impact":"明年隋师至而诸将解体，台城之降遂不旋踵；陈室之亡非以其地，而以其不设备也。","figures":["陈叔宝","江总","孔范"],"place":"建康（今江苏南京）","state":"南朝陈","sources":["《陈书·后主纪》","《南史·陈本纪下》","《资治通鉴》陈纪"],"tags":["陈后主","不设备","江左"]},"related":["cn--589--p01", "cn--588--m01"]},
];
